// Correcciones Simulia — tanda 3 — parte 4 de 7: protocolos y escalas (preguntas propias) (10 oct 2026)
// Pegar en mongosh (Compass) conectado a SimuLIA. Guarda copia de cada original antes de tocarlo.
const db2 = db.getSiblingDB('CSV');
const backup = db2.getCollection('backup_correcciones_2026_10_10_t3');
let ok=0, del=0, warn=0;
function fix(coll, filter, set) {
  const c = db2.getCollection(coll); const d = c.find(filter).toArray();
  if (d.length !== 1) { warn++; print('⚠️ ' + coll + ' ' + JSON.stringify(filter).slice(0,90) + ' -> ' + d.length); return; }
  backup.insertOne({ coll, original: d[0], savedAt: new Date() });
  c.updateOne({ _id: d[0]._id }, { $set: set }); ok++;
}
function rm(coll, filter) {
  const c = db2.getCollection(coll); const d = c.find(filter).toArray();
  if (d.length !== 1) { warn++; print('⚠️ ' + coll + ' ' + JSON.stringify(filter).slice(0,90) + ' -> ' + d.length); return; }
  backup.insertOne({ coll, original: d[0], deleted: true, savedAt: new Date() });
  c.deleteOne({ _id: d[0]._id }); del++;
}

fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a09") }, {"long_answer": "Para mejorar la seguridad y la transparencia del suministro farmacéutico, la Estrategia apoya acciones legislativas europeas como la Ley de Medicamentos Críticos y la modificación de la contratación pública para incorporar criterios cualitativos, como la resiliencia y diversificación del suministro, además del precio. Restringir la producción europea de genéricos, excluir a fabricantes europeos de los contratos públicos o vetar innovaciones no certificadas por terceros países irían en contra del objetivo de fortalecer la cadena de suministro en la Unión."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a0c") }, {"long_answer": "Para promover la transparencia en la publicación de resultados de ensayos clínicos financiados con fondos públicos, se prevé incluir en los contratos tipo cláusulas que aseguren la difusión de los resultados y un procedimiento de comunicación a las autoridades competentes. Permitir la publicación solo en medios privados sin supervisión, restringir la comunicación hasta la comercialización o conceder exclusividad a la industria sin obligación de reporte reducirían la transparencia que se pretende garantizar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a0d") }, {"long_answer": "Dentro de CERTERA, la plataforma de terapias avanzadas, el ISCIII coordina y articula los distintos nodos participantes, integrando infraestructuras de producción y desarrollo y facilitando las alianzas con el sector industrial para acercar estas terapias a los pacientes. No se limita a financiar ensayos clínicos internacionales, no se dedica a la producción de medicamentos genéricos y su papel no es solo apoyar la investigación básica, ya que busca precisamente la conexión con la industria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a14") }, {"long_answer": "El Plan identifica a las personas mayores como un grupo especialmente vulnerable, ya que la soledad no deseada, la pérdida de roles, las enfermedades crónicas y el dolor aumentan el riesgo de conducta suicida, que alcanza tasas elevadas en edades avanzadas, sobre todo en varones. Adolescentes y jóvenes, personas LGTBIQ+ y personas con discapacidad son también colectivos vulnerables en el Plan, pero la combinación de soledad no deseada y enfermedades crónicas se describe específicamente en relación con las personas mayores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a16") }, {"long_answer": "Los consumidores habituales de alcohol sin diagnóstico formal no figuran como uno de los grupos en situación de vulnerabilidad recogidos en el Plan, que habla de trastornos por consumo de sustancias dentro de los factores clínicos, no de este colectivo concreto. En cambio, el Plan sí incluye expresamente entre los grupos vulnerables a las personas que sufren violencia, a las que padecen enfermedades graves o dolor y a las que se encuentran en riesgo de pobreza y exclusión social."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a1a") }, {"long_answer": "La Ley Orgánica 8/2021, de protección integral a la infancia y la adolescencia frente a la violencia, establece que las comunidades autónomas desarrollen protocolos de actuación intersectoriales en el ámbito educativo frente a distintas formas de violencia, incluidas las conductas autolíticas y el suicidio. No se limita a exigir formación a los docentes, no prevé sanciones para estudiantes con conductas suicidas, que serían contraproducentes y estigmatizantes, y tampoco prohíbe abordar el suicidio en las aulas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a1b") }, {"long_answer": "La Ley Orgánica 8/2021 crea en los centros educativos la figura del coordinador o coordinadora de bienestar y protección del alumnado, cuya función es promover medidas que aseguren el bienestar de niños, niñas y adolescentes y fomentar la cultura del buen trato, actuando como referente ante situaciones de violencia. No le corresponde supervisar el rendimiento académico, imponer disciplina mediante sanciones ni gestionar los recursos económicos del centro."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a26") }, {"long_answer": "El Plan destaca a adolescentes y jóvenes como el grupo en el que ha aumentado el sufrimiento emocional, con un incremento de conductas autolesivas e ideación suicida, y en el que es necesario promover espacios saludables y libres de violencia, incluido el entorno digital. Las personas mayores, las personas con discapacidad y las personas privadas de libertad son también colectivos vulnerables, pero sus factores de riesgo se describen en relación con otros aspectos, como la soledad, la discriminación o el entorno penitenciario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a28") }, {"long_answer": "En las personas con enfermedades graves o dolor, el Plan señala que el sufrimiento emocional y los sentimientos de desesperanza asociados a su situación afectan negativamente a su bienestar y aumentan el riesgo de conducta suicida, por lo que requieren una atención integral que incluya la esfera psicológica. El acceso a tratamientos médicos, el apoyo social intensivo y la vigilancia comunitaria no son factores que perjudiquen su bienestar; al contrario, el apoyo social es un factor protector."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a2a") }, {"long_answer": "El sistema de vigilancia en salud mental aplicado a la prevención del suicidio tiene la función de proporcionar información relevante sobre persona, lugar y tiempo, es decir, quién, dónde y cuándo se producen las conductas suicidas, para orientar la toma de decisiones y priorizar intervenciones. No debe registrar solo los suicidios consumados, ya que los intentos son un indicador clave de riesgo; no centraliza el tratamiento, y tampoco excluye los entornos educativos y laborales, que son ámbitos relevantes de prevención."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a2e") }, {"long_answer": "La estrategia estatal de Recursos Humanos en Atención Primaria que debe elaborarse antes de 2027 pretende garantizar la accesibilidad, la longitudinalidad, la estabilidad de las plantillas, la atracción de talento y la reducción de la temporalidad, pilares para un primer nivel asistencial sólido. Reducir profesionales para ahorrar, concentrar el trabajo en pocas especialidades o incrementar la temporalidad y la rotación son contrarios a esos objetivos y perjudicarían la continuidad de la atención."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a2f") }, {"long_answer": "El Plan establece que las comunidades autónomas elaboren un plan de recursos humanos para Atención Primaria a 10 años, basado en la estrategia estatal y en las recomendaciones previamente consensuadas, de modo que la planificación de plantillas tenga una perspectiva de medio y largo plazo. Suspender cualquier plan hasta 2027, esperar directrices europeas o limitar la planificación a hospitales de referencia impedirían abordar el déficit de profesionales que afecta al primer nivel asistencial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a32") }, {"long_answer": "La indicación, uso y autorización de dispensación de medicamentos y productos sanitarios por parte de las enfermeras está regulada por el Real Decreto 954/2015 y sus modificaciones posteriores, especialmente el Real Decreto 1302/2018, que desarrollan el marco para la elaboración de guías y protocolos de actuación. El Real Decreto 300/2010 no regula este ámbito, la Ley General de Sanidad de 1986 es una norma general del sistema sanitario y no es cierto que solo exista normativa autonómica, ya que la regulación es estatal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a36") }, {"long_answer": "La ampliación progresiva de la cartera común de salud bucodental del SNS se orienta a garantizar la equidad en el acceso a estas prestaciones, priorizando colectivos como la población infantojuvenil, las embarazadas, las personas con discapacidad y los mayores de 65 años, que tienen mayor necesidad o menor acceso a la atención dental. Ofrecer solo tratamientos estéticos no es un objetivo sanitario, reducir la cartera iría en sentido contrario a la ampliación y concentrar los servicios en grandes hospitales se aleja de su prestación en Atención Primaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a37") }, {"long_answer": "El Plan de Ampliación de la cartera de salud bucodental fija como meta que en 2027 el 70% del colectivo priorizado reciba las nuevas prestaciones, lo que refleja una implantación progresiva con un objetivo de cobertura elevado. Los porcentajes del 50% y del 30% quedan por debajo de la meta establecida, y el 90% no corresponde al objetivo fijado en el documento para ese año."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a38") }, {"long_answer": "La reingeniería de los procesos administrativos en Atención Primaria busca eliminar pasos innecesarios y facilitar la incorporación de avances tecnológicos, con el fin de aligerar la carga administrativa que soportan los profesionales y dedicar más tiempo a la atención directa. Incrementar la burocracia, eliminar los sistemas digitales o externalizar todos los procesos a empresas privadas son medidas opuestas a la simplificación y modernización que persigue el Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a3c") }, {"long_answer": "El Plan prevé que, antes de 2027, todas las comunidades autónomas hayan implantado herramientas de inteligencia artificial orientadas a la transcripción conversacional en las consultas, que registran automáticamente la información de la entrevista clínica y reducen el tiempo de documentación. No se limita a hospitales terciarios, ya que el foco es Atención Primaria; no se plantea restringir su uso por deficiencias técnicas y tampoco se pospone indefinidamente, puesto que tiene un plazo definido."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a40") }, {"long_answer": "Para seleccionar un modelo de gestión integral de la demanda como recomendación nacional, el Plan se basa en la evaluación de las buenas prácticas desarrolladas en las comunidades autónomas y en el mapa de competencias de los profesionales de Atención Primaria, de forma que cada demanda sea atendida por el profesional más adecuado. Los sondeos internacionales estandarizados no son la base de la selección, y aplicar una tecnología sin consenso o elegir de forma unilateral sin los profesionales contradice el enfoque participativo del Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a41") }, {"long_answer": "El Plan fija como meta que el 100% de las comunidades autónomas cuenten con planes autonómicos de renovación de infraestructuras y equipamiento antes de diciembre de 2025, para adecuar los centros de salud a la cartera de servicios actualizada. Los porcentajes del 75% y del 60% no corresponden a la meta establecida, y afirmar que no se fija ningún objetivo es incorrecto, ya que se trata de una acción con plazo e indicador definidos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a42") }, {"long_answer": "El Plan establece la actualización anual de las acciones priorizadas en las Estrategias y Planes nacionales del SNS que afectan a Atención Primaria, de modo que los equipos trabajen con objetivos vigentes y coordinados con el resto del sistema. Las normas internas de cada hospital sin coordinación no se refieren al primer nivel, las instrucciones sin evidencia científica contradicen la práctica basada en pruebas y las recomendaciones exclusivas de sociedades farmacéuticas no son el marco de referencia previsto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a44") }, {"long_answer": "En el abordaje de la persona mayor polimedicada, el Plan prioriza las situaciones de mayor riesgo: el uso de 8 o más fármacos, la conciliación de la medicación en las transiciones asistenciales y los medicamentos de alto riesgo, que concentran la mayor parte de los eventos adversos evitables. Reducir solo los fármacos cardiovasculares es un enfoque parcial, evitar toda medicación sin evaluación es inadecuado y potencialmente peligroso, y no priorizar ningún grupo farmacológico iría en contra de la estrategia de centrar la revisión en lo más relevante."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a48") }, {"long_answer": "El Registro Estatal de Profesionales Sanitarios es importante para la estrategia estatal de recursos humanos en Atención Primaria porque permite disponer de datos fiables sobre el número, la distribución y las características de los profesionales, imprescindibles para planificar y hacer seguimiento de las plantillas. No es cierto que carezca de relevancia en la planificación, no sirve solo para la gestión económica y no se limita al ámbito hospitalario, ya que incluye a todos los profesionales sanitarios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a4d") }, {"long_answer": "El Plan prevé la implantación progresiva en Atención Primaria de un instrumento estandarizado, aprobado por el Consejo Interterritorial del SNS, para la detección temprana de la violencia de género, de modo que todos los profesionales utilicen una herramienta común y validada. Un cuestionario domiciliario no estructurado carece de la sistematización necesaria, la evaluación psicológica en atención especializada no es una herramienta de detección precoz en el primer nivel y un registro confidencial entre servicios sociales no es el instrumento de cribado descrito."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a4e") }, {"long_answer": "El plan de formación específica en violencia de género incluye a los equipos de Atención Primaria, de Salud Mental y de atención al embarazo, parto y puerperio, ámbitos en los que es más probable detectar situaciones de violencia y en los que la mujer puede ser especialmente vulnerable, como durante la gestación. Limitarlo solo a Atención Primaria o solo a Salud Mental deja fuera ámbitos clave, y los equipos hospitalarios y de emergencias no son los incluidos en esta formación específica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a55") }, {"long_answer": "Para mejorar la continuidad asistencial en personas con problemas de salud mental, el Plan propone promover programas colaborativos entre Atención Primaria y Salud Mental, que permiten compartir casos, protocolos y formación, y atender en el primer nivel a muchas personas con problemas leves o moderados. Derivar siempre sin seguimiento en Atención Primaria fragmenta la atención, reducir las visitas al primer nivel resta accesibilidad y limitar la comunicación entre profesionales es contrario a la coordinación que se busca."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a57") }, {"long_answer": "En los pacientes polimedicados, el Plan promueve la optimización de la terapia farmacológica con la participación conjunta de farmacéuticos y prescriptores, mediante la revisión de la medicación para detectar duplicidades, interacciones o fármacos innecesarios y ajustar el tratamiento a los objetivos de cada persona. Mantener las prescripciones sin revisar perpetúa los riesgos, trasladar el seguimiento a la consulta hospitalaria aleja la atención del primer nivel y limitar la revisión a enfermería excluye a otros profesionales necesarios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a58") }, {"long_answer": "El Plan fomenta la participación comunitaria integrando a las comunidades en los procesos de toma de decisiones sobre las políticas sanitarias de Atención Primaria y Comunitaria, mediante estructuras como consejos de salud y procesos participativos que recogen las necesidades de la población. Centralizar las decisiones sin consulta, limitar la participación a profesionales sanitarios o eliminar las consultas comunitarias para acelerar trámites son contrarios a la orientación comunitaria que el Plan pretende reforzar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a59") }, {"long_answer": "El modelo de cálculo de necesidades de recursos humanos en Atención Primaria se caracteriza por basarse en la morbilidad de la población, los resultados en salud y sus características sociodemográficas, superando el cálculo tradicional basado solo en el número de tarjetas sanitarias. Calcular según la plantilla actual sin considerar la demanda, asignar recursos iguales en todas las zonas sin análisis o planificar solo especialidades hospitalarias no permitirían ajustar los recursos a las necesidades reales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a5d") }, {"long_answer": "En formación sanitaria especializada, el Plan prevé aprobar en 2027 los nuevos programas formativos de Enfermería Familiar y Comunitaria y de Enfermería Obstétrico-Ginecológica, actualizando las competencias que adquieren los residentes de estas especialidades vinculadas a Atención Primaria. No se plantea eliminar la especialidad de Enfermería Familiar y Comunitaria, que se quiere reforzar; tampoco una formación única sin diferenciación entre especialidades ni trasladar la formación a universidades extranjeras."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a61") }, {"long_answer": "En el análisis de procesos resolubles en Atención Primaria antes de 2027, el Plan prioriza aprobar y jerarquizar aquellos procesos de salud que pueden resolverse en el primer nivel, con el objetivo de lograr un incremento significativo de su capacidad resolutiva y evitar derivaciones innecesarias. La derivación sistemática a especialistas hospitalarios, la disminución de procesos atendidos en Atención Primaria o la exclusión de las patologías crónicas son contrarias a este objetivo, ya que la cronicidad es precisamente uno de los ámbitos propios del primer nivel."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a62") }, {"long_answer": "El modelo de gestión integral de la demanda implica la intervención del conjunto de profesionales del equipo de Atención Primaria según un mapa de competencias adaptado a las necesidades de la ciudadanía, de forma que cada demanda sea resuelta por el profesional más adecuado, incluidas enfermería y personal administrativo. La derivación inmediata al médico sin gestión previa, una gestión puramente administrativa sin participación clínica o la descentralización sin coordinación no responden a este modelo de trabajo en equipo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a6d") }, {"long_answer": "La Comisión de Atención Primaria y Comunitaria (CAPYCO) tiene, en relación con el Plan 2025-2027, la función de debatir y validar los criterios de distribución de los créditos destinados a las comunidades autónomas para desarrollar las acciones previstas. No ejecuta directamente las acciones, que corresponden a las administraciones competentes; no se limita a supervisar indicadores de salud mental y no gestiona la financiación de infraestructuras hospitalarias, ajenas al ámbito del Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a72") }, {"long_answer": "El Plan establece que antes de finalizar 2025 se presente y apruebe en la Comisión de Recursos Humanos del SNS un modelo común de recertificación de los profesionales sanitarios, que permita acreditar periódicamente que mantienen actualizadas sus competencias. Un programa de formación en gestión administrativa no es el objeto de esta acción, un plan exclusivo para médicos especialistas hospitalarios no se ajusta al ámbito de Atención Primaria ni al carácter común del modelo y un protocolo de desvinculación de temporales no guarda relación con la recertificación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a7d") }, {"long_answer": "Para evaluar el impacto del Plan de Acción 2025-2027 se emplean indicadores definidos de resultados en salud y de accesibilidad, que permiten valorar si las acciones se traducen en mejoras reales para la población y en el funcionamiento de Atención Primaria. Las encuestas de satisfacción por sí solas ofrecen una visión parcial, la monitorización de llamadas telefónicas solo recoge un aspecto concreto de la actividad y el análisis exclusivo de costes no permite valorar los resultados en salud."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a82") }, {"long_answer": "El Plan fija como meta que, en diciembre de 2027, el 100% de las comunidades autónomas tengan aprobada una oferta de empleo anual para todas las categorías profesionales de Atención Primaria, lo que favorece la estabilidad de las plantillas y la reducción de la temporalidad. Los porcentajes en torno al 75%, el 50% o inferiores al 30% no corresponden al objetivo establecido, que busca que la medida alcance a todo el territorio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a84") }, {"long_answer": "En relación con el modelo común de recertificación, las comunidades autónomas deben incluir en su plan anual de formación acciones específicas sobre recertificación profesional en Atención Primaria, para que los profesionales conozcan el modelo y puedan cumplir sus requisitos. Los cursos de inglés, los entrenamientos tecnológicos sin relación clínica o la especialización en cirugía general no se vinculan con la recertificación ni con las competencias propias del primer nivel asistencial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a85") }, {"long_answer": "Para promover el retorno a Atención Primaria, el Plan propone reservar en los concursos de traslado un porcentaje común de plazas para enfermeras especialistas en Enfermería Familiar y Comunitaria que trabajan en el ámbito hospitalario, de forma que puedan incorporarse a puestos acordes con su especialidad. Los médicos especialistas en cirugía ambulatoria, los técnicos de laboratorio hospitalario y el personal administrativo hospitalario no son el colectivo al que se dirige esta medida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779c0") }, {"long_answer": "Para fomentar el uso de genéricos y biosimilares, la Estrategia incluye la implementación de planes específicos que aumenten su utilización y mejoren su accesibilidad, ya que la competencia que introducen genera ahorros que permiten financiar la innovación. Imponer precios elevados reduciría su atractivo y su ventaja económica, eliminar su financiación sería contrario a su promoción y evitar sistemas de información sobre su consumo impediría hacer el seguimiento que la propia Estrategia prevé."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779c1") }, {"long_answer": "La Estrategia destaca que España es el primer país europeo en número de ensayos clínicos con medicamentos y que a nivel mundial solo la superan Estados Unidos y China, gracias a la calidad de sus centros, sus investigadores y la agilidad de su marco regulatorio. Decir que no tiene relevancia en investigación clínica, que se centra en ensayos con genéricos o que ha limitado su participación internacional contradice esta posición de liderazgo.", "option_1": "Es el primer país europeo en ensayos clínicos y, a nivel mundial, solo le superan Estados Unidos y China."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779c3") }, {"long_answer": "La Estrategia busca transformar la relación tradicional entre la industria farmacéutica y las instituciones públicas, basada en un esquema de proveedor-cliente, en un modelo de colaboración con dinámicas virtuosas que integren investigación, producción y acceso a los medicamentos. No se describe como una alianza ya consolidada que no requiere cambios, ni como una relación tercerizada sin innovación conjunta, y tampoco como una dependencia exclusiva de la industria extranjera, ya que el documento parte precisamente de reforzar la colaboración con el tejido industrial que opera en España.", "option_4": "Una relación de dependencia exclusiva de la industria extranjera."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779c5") }, {"long_answer": "El Plan de Recuperación, Transformación y Resiliencia constituye el marco en el que se inscribe la Estrategia de la Industria Farmacéutica, ya que favorece las reformas e inversiones necesarias para que España refuerce su liderazgo en innovación y su autonomía estratégica en el ámbito de la salud. No es cierto que no tenga relación con la Estrategia o que se oponga a sus líneas de acción, y tampoco se limita a financiar infraestructuras sanitarias físicas, ya que incluye investigación, digitalización y capacidades industriales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779cd") }, {"long_answer": "La Estrategia de la Industria Farmacéutica se alinea con la Estrategia Farmacéutica para Europa y contribuye a sus objetivos compartidos de innovación, acceso equitativo a los medicamentos y sostenibilidad de los sistemas sanitarios. No responde a políticas independientes sin coordinación, no se centra exclusivamente en el mercado español sin relación con la Unión Europea y no pretende eliminar la colaboración con las agencias europeas, que es esencial en el marco regulatorio de los medicamentos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779d0") }, {"long_answer": "El Reglamento (UE) 2021/2282 sobre evaluación de tecnologías sanitarias regula únicamente la evaluación de los aspectos clínicos de medicamentos y productos sanitarios mediante evaluaciones clínicas conjuntas a escala europea, mientras que los aspectos no clínicos, como los económicos, éticos u organizativos, siguen siendo competencia de cada Estado miembro. Por ello no evalúa aspectos clínicos y no clínicos a la vez, no se limita a los aspectos económicos y no excluye a los medicamentos, que son uno de sus ámbitos principales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779d2") }, {"long_answer": "La modificación del artículo 92 de la Ley de Garantías y Uso Racional de los Medicamentos establece como regla general que el uso compasivo de medicamentos antes de su autorización de comercialización sea gratuito para el paciente, salvo en casos justificados, con el fin de garantizar el acceso equitativo a tratamientos en situaciones especiales. No es correcto que lo pague siempre el paciente, no se limita a medicamentos ya autorizados, ya que se refiere precisamente a los no autorizados, y no está prohibido."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779d3") }, {"long_answer": "La sistematización de los cauces de interacción temprana, el llamado early dialogue, entre compañías y administración pretende mejorar la coordinación entre las distintas estructuras del sistema sanitario que intervienen en la regulación, la evaluación y la financiación, de modo que los desarrolladores reciban orientaciones coherentes desde fases tempranas. No busca reducir la inversión privada en I+D, no se limita a la transferencia tecnológica preclínica y no pretende centralizar las decisiones exclusivamente en la administración."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779d5") }, {"long_answer": "La Estrategia contempla una financiación acelerada, de carácter provisional o condicionado, para determinados medicamentos, sujeta a revisión posterior a medida que se disponga de más evidencia y sin que esta vía tenga repercusión en la fase de negociación del precio. No se trata de una financiación sin revisiones futuras, no se aplica solo a genéricos y biosimilares, que no presentan la incertidumbre que justifica esta vía, y no excluye las áreas de alta incertidumbre clínica, que son precisamente su ámbito natural."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779d8") }, {"long_answer": "Entre los objetivos de la reforma del procedimiento de inclusión de nuevos medicamentos en la prestación farmacéutica figura consolidar fases de instrucción y de resolución diferenciadas e independientes, lo que refuerza la objetividad y la transparencia de las decisiones. Reducir la evaluación económica, eliminar los criterios clínicos en favor del precio o delegar la evaluación en la industria farmacéutica irían en contra del rigor e independencia que persigue la reforma."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779da") }, {"long_answer": "Para mejorar la evaluación económica en la fijación de precios, la Estrategia propone tener en cuenta la incertidumbre financiera y el análisis del impacto presupuestario, de manera que las decisiones consideren no solo el valor del medicamento, sino también su efecto sobre la sostenibilidad del sistema. Limitarse a los costes directos sin impacto económico, basarse solo en precios internacionales o analizar un supuesto beneficio sin fines económicos no permiten una evaluación económica completa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779df") }, {"long_answer": "Según la Estrategia, el reposicionamiento de medicamentos que ya han perdido los periodos de protección permitirá reconocer nuevas indicaciones a instancia de terceros sin ánimo de lucro, como grupos académicos o sociedades científicas, y sin que ello suponga una penalización en el precio del medicamento. No se reserva solo a las empresas comerciales, no implica una reducción automática del precio y sí se contempla como medida dentro del marco que propone la Estrategia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779e1") }, {"long_answer": "Para completar la incorporación de biomarcadores en el SNS se considera imprescindible facilitar el intercambio de datos genómicos con garantías de seguridad y protección de datos, ya que la medicina de precisión requiere compartir información entre centros y comunidades para que las pruebas sean útiles y equitativas. Permitir actividades autonómicas sin coordinación generaría desigualdades, limitar el diagnóstico molecular a centros privados restringiría el acceso y excluir los biomarcadores de la cartera impediría su uso en la práctica clínica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779e3") }, {"long_answer": "La disposición adicional sexta de la Ley de Garantías, que regula las aportaciones de la industria por volumen de ventas al SNS, se actualizará para ampliar los ámbitos de venta de medicamentos financiados incluidos y para incorporar criterios ambientales en el cálculo de las aportaciones. Reducir los ámbitos de dispensación, eliminar los criterios relacionados con la huella de carbono o centrarse solo en medicamentos hospitalarios son contrarios a la ampliación y a la orientación ambiental que se plantea."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779e6") }, {"long_answer": "La investigación en Atención Primaria se fomentará mediante la creación de unidades de investigación clínica y de programas desarrollados en colaboración entre el ISCIII y las comunidades autónomas, para que los profesionales del primer nivel dispongan de estructuras de apoyo y puedan participar en ensayos y estudios. Confinar la investigación a hospitales especializados, evitar los ensayos descentralizados o eliminar la investigación cooperativa en red son medidas contrarias a este impulso."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779ea") }, {"long_answer": "Entre las estructuras que se reforzarán como soporte a la investigación biomédica figuran los CIBER, la plataforma SCReN de ensayos clínicos, los Institutos de Investigación Sanitaria, el CSIC, el CIEMAT y las universidades, que conforman el ecosistema público de investigación en España. Limitarse a las universidades públicas, a los departamentos privados de I+D o a centros privados internacionales no refleja la amplitud de estructuras que la Estrategia pretende fortalecer."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779eb") }, {"long_answer": "Para fortalecer la investigación en el SNS se priorizarán recursos humanos específicos como los contratos de gestión de la investigación en los Institutos de Investigación Sanitaria, el personal bioinformático, la enfermería especializada en investigación y la farmacia hospitalaria, entre otros perfiles de apoyo. Contar solo con médicos especialistas sin otros profesionales, limitarse a personal administrativo o externalizar la investigación a empresas privadas no permitiría construir equipos multidisciplinares estables."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779f9") }, {"long_answer": "TERAFRONT es una sociedad mercantil de capital mixto en la que el 51% corresponde al socio privado y el 49% a la participación pública, aportada por el CDTI a través de su programa INNVIERTE, lo que permite combinar el impulso público con la gestión empresarial en el desarrollo de terapias avanzadas. No es una entidad 100% pública ni totalmente privada, y afirmar que no tiene participación del CDTI es incorrecto, ya que este organismo es precisamente el socio público."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca9779fa") }, {"long_answer": "El Pool de Patentes de Medicamentos (Medicines Patent Pool) se cita en la Estrategia como ejemplo de colaboración público-privada para facilitar el acceso a tecnologías sanitarias con responsabilidad social, ya que negocia licencias voluntarias con los titulares de patentes para que fabricantes de genéricos produzcan medicamentos asequibles para países de ingresos bajos y medios. No es una organización privada sin supervisión pública, ni un programa de formación de pacientes, ni un fondo para adquirir equipos médicos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a10") }, {"long_answer": "El Plan recoge que, ante la limitada capacidad predictiva de los factores de riesgo aislados, se proponen modelos basados en algoritmos de aprendizaje automático que integran múltiples variables clínicas, psicológicas y sociales para estimar mejor el riesgo de conducta suicida. Los modelos exclusivos para adolescentes, los centrados solo en factores individuales o los que excluyen variables sociales serían más limitados, precisamente porque la conducta suicida es multifactorial y requiere integrar distintas dimensiones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a1d") }, {"long_answer": "Uno de los objetivos principales del Plan de prevención del suicidio es reducir el estigma asociado a la conducta suicida, porque el estigma dificulta que las personas en riesgo y sus allegados pidan ayuda y que se hable del problema de forma abierta y responsable. Incrementar la hospitalización obligatoria no es un objetivo del Plan, limitar la información pública contradice la sensibilización y la comunicación responsable, y fomentar el aislamiento social aumentaría el riesgo, ya que la conexión social es un factor protector."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a20") }, {"long_answer": "El Grupo Motor del Plan de prevención del suicidio se encarga de diseñar las líneas estratégicas y de colaborar con personas expertas, instituciones, sociedades científicas y personas con experiencia vivida para desarrollarlas, actuando como órgano de impulso y coordinación técnica. No realiza intervenciones clínicas directas, no gestiona el presupuesto del Sistema Nacional de Salud y no tiene funciones de supervisión del cumplimiento de la normativa general."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a25") }, {"long_answer": "Fuera del ámbito sanitario, el Plan prioriza la implantación de programas de prevención del suicidio en escuelas, comunidades, lugares de trabajo, prisiones y fuerzas armadas, entornos donde se concentran personas en riesgo y donde es posible detectar señales de alarma y promover factores protectores. Los hospitales y centros de salud mental pertenecen al ámbito sanitario, y limitarse a zonas rurales o a áreas urbanas densas dejaría fuera a gran parte de la población y de los entornos clave."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a3d") }, {"long_answer": "La identificación y definición de procesos de salud susceptibles de resolverse en Atención Primaria antes de 2027 busca mejorar su capacidad resolutiva, mediante un consenso con las comunidades autónomas, las sociedades científicas y las asociaciones de pacientes que garantice la viabilidad y aceptación de los procesos seleccionados. Limitar las funciones de Atención Primaria para delegarlas en el hospital, eliminar procesos no invasivos u obligar a derivar todos los procesos son contrarios a este objetivo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a3f") }, {"long_answer": "El modelo de gestión integral de la demanda que se publicará en 2027 tiene como finalidad atender de forma eficaz y satisfactoria las necesidades de los pacientes y promover una gestión preventiva y proactiva de la salud, en lugar de limitarse a responder a la demanda espontánea. Concentrar la demanda en el hospital, eliminar la coordinación entre profesionales de Atención Primaria o reducir las consultas presenciales al mínimo no responden a los principios de accesibilidad y trabajo en equipo del modelo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a45") }, {"long_answer": "En relación con el Plan de Prevención de la Fragilidad en la persona mayor, el objetivo fijado para 2027 es que el 50% de las comunidades autónomas presenten evidencias de la implementación del documento de consenso actualizado sobre prevención de la fragilidad y las caídas. Que solo lo implementen hospitales públicos es contrario a su enfoque, centrado en Atención Primaria y la comunidad; hospitalizar a toda la población mayor no tiene sentido preventivo y reducir los recursos para las personas mayores iría en sentido contrario al Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a4a") }, {"long_answer": "El objetivo principal de implantar las recomendaciones de no hacer en Atención Primaria es adecuar la práctica clínica a la evidencia científica para mejorar la calidad y la seguridad de la atención, evitando pruebas, tratamientos o intervenciones que no aportan beneficio o pueden causar daño. Aunque reducir procedimientos innecesarios puede generar ahorros, el ahorro de costes es una consecuencia y no el objetivo principal; mejorar la precisión diagnóstica en atención especializada no es su ámbito y aumentar las visitas programadas no se relaciona con estas recomendaciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a4b") }, {"long_answer": "El Plan de Acción prioriza, en la persona mayor polimedicada, a quienes utilizan 8 o más fármacos y la conciliación de la medicación, especialmente en las transiciones entre niveles asistenciales, ya que son las situaciones con mayor riesgo de errores, interacciones y efectos adversos. Aumentar la prescripción de antibióticos con fines preventivos favorece las resistencias, suspender todos los medicamentos sin valoración puede descompensar enfermedades y aumentar los controles hospitalarios no responde al abordaje desde Atención Primaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a4f") }, {"long_answer": "En línea con el Plan Estratégico Nacional para la reducción de la obesidad infantil, en Atención Primaria se promueve el apoyo a la lactancia materna siguiendo las recomendaciones de la Iniciativa para la Humanización de la Asistencia al Nacimiento y la Lactancia (IHAN), dado que la lactancia materna protege frente al exceso de peso en la infancia. La promoción exclusiva de dietas hipocalóricas no es adecuada en niños, las campañas de actividad física intensiva no son la medida descrita y el uso rutinario de suplementos no está indicado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a52") }, {"long_answer": "En materia de sistemas de información, el Plan impulsa mejoras en la medición de la calidad de Atención Primaria y el benchmarking entre comunidades autónomas, lo que permite comparar resultados, identificar buenas prácticas y orientar la mejora continua. Externalizar completamente la gestión de los datos sanitarios plantea problemas de control y confidencialidad, reducir indicadores clínicos empobrece la evaluación y eliminar las comparaciones entre comunidades es contrario al objetivo de aprendizaje compartido."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a54") }, {"long_answer": "Dentro de la línea 6, el Plan considera imprescindible reforzar la atención domiciliaria de los equipos de Atención Primaria, porque permite atender a personas con dependencia, enfermedades crónicas avanzadas o necesidades paliativas en su entorno, mejorando la continuidad de los cuidados y evitando ingresos. El acceso preferente a pruebas hospitalarias, la formación en cirugía menor o la gestión administrativa centralizada pueden ser útiles, pero no son la actividad que el Plan señala como imprescindible reforzar en esta línea."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a5a") }, {"long_answer": "El modelo de recertificación profesional propuesto para Atención Primaria busca una acreditación periódica que garantice que los profesionales mantienen actualizada su competencia a lo largo de su carrera, vinculando el ejercicio profesional a la formación y el desarrollo continuos. Eliminar los requisitos de actualización, conceder una certificación única sin formación continua o limitar la evaluación al personal médico contradicen el propio concepto de recertificación, que se plantea para todos los profesionales sanitarios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a5c") }, {"long_answer": "La estrategia estatal de Recursos Humanos para Atención Primaria debe garantizar la accesibilidad de la población a sus profesionales, la longitudinalidad de la atención, la estabilidad de las plantillas, la atracción del talento y la reducción de la temporalidad, condiciones necesarias para un primer nivel asistencial resolutivo. Aumentar la rotación rápida del personal, priorizar la temporalidad o desvincular a los profesionales de su comunidad perjudicarían la continuidad asistencial y la relación con los pacientes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a6b") }, {"long_answer": "Uno de los objetivos del Plan de Acción de Atención Primaria y Comunitaria 2025-2027 es mejorar la capacidad de resolución y la gestión de la demanda en Atención Primaria, de forma que el primer nivel pueda resolver más problemas de salud y atender a la población con mayor agilidad. Reducir el número de centros de salud urbanos, aumentar la especialización hospitalaria en áreas rurales o instalar unidades móviles de atención especializada no figuran entre sus objetivos y no refuerzan la Atención Primaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a6e") }, {"long_answer": "En 2024 se destinaron 85 millones de euros a financiar acciones de formación y de mejora en Atención Primaria basadas en la evidencia, distribuidos entre las comunidades autónomas para desarrollar las líneas del marco estratégico. Las cifras de 493 millones para digitalización, 172 millones para equipamiento hospitalario o 50 millones para campañas de vacunación no corresponden a la asignación descrita para formación y mejora de Atención Primaria en ese año."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a70") }, {"long_answer": "Para la monitorización de las ofertas de empleo en Atención Primaria en 2024, el indicador clave es el porcentaje de comunidades autónomas con la convocatoria de estabilización resuelta antes del 31 de diciembre de 2024, en relación con los procesos destinados a reducir la temporalidad. El número de plazas ofertadas en hospitales, el índice de rotación en atención especializada o el número de cursos impartidos no miden la estabilización del empleo en Atención Primaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a71") }, {"long_answer": "Para mejorar la organización y las condiciones laborales en Atención Primaria, el Plan prevé alcanzar en la Comisión de Recursos Humanos del SNS un acuerdo con compromiso de seguimiento y evaluación antes de 2027, de forma que las medidas pactadas se apliquen y se pueda comprobar su cumplimiento. Reducir la jornada sin cambios retributivos, incluir clínicos en cargos administrativos nacionales o derivar a los pacientes crónicos a otros niveles no son los resultados previstos para esta acción."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a73") }, {"long_answer": "El Plan establece que el 100% de las comunidades autónomas incluyan en su plan de formación acciones específicas sobre el modelo común de recertificación antes del primer semestre de 2026, para que su implantación sea homogénea en todo el SNS. Los porcentajes del 70% y del 50% no corresponden a la meta fijada, y no es una medida voluntaria, ya que forma parte de las acciones con objetivo e indicador definidos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a74") }, {"long_answer": "El modelo común para calcular las necesidades de recursos humanos en Atención Primaria debe basarse en la morbilidad de la población, en los resultados en salud y en sus características sociodemográficas, de modo que las plantillas se ajusten a la complejidad real de cada zona. Contar solo el número de médicos activos, considerar exclusivamente a la población mayor de 65 años o fijar un número fijo de profesionales por centro ignorarían las diferencias de necesidades entre territorios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a75") }, {"long_answer": "El Plan prevé que en 2026 todas las comunidades autónomas hayan identificado, según el modelo común aprobado, las necesidades de plantilla de al menos el 50% de sus áreas de salud, como primer paso para adecuar los recursos humanos a las necesidades reales. Reducir la plantilla rural un 10% o establecer contratos temporales en el 75% de los centros contradicen los objetivos de suficiencia y estabilidad, y crear unidades exclusivas de cuidados paliativos no es la medida vinculada a este modelo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a7c") }, {"long_answer": "En la mejora continua de la formación sanitaria especializada en Atención Primaria, el objetivo es asegurar la estabilidad de las unidades docentes y la calidad de las comisiones de docencia, sometidas a auditorías, para garantizar una formación de residentes de calidad en el primer nivel asistencial. Reducir a la mitad la duración de los programas, excluir la formación en atención comunitaria o privatizar la formación son medidas contrarias a la calidad y al enfoque comunitario de estas especialidades."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a83") }, {"long_answer": "El Plan 2025-2027 fija como indicador de ajuste de la temporalidad que, en diciembre de 2027, la tasa de temporalidad en las categorías profesionales de Atención Primaria se sitúe en el 8%, en coherencia con el objetivo general de reducción de la temporalidad en el empleo público. Una temporalidad superior al 15% o por debajo del 20% sería demasiado elevada para ese objetivo, y una temporalidad variable sin límite impediría medir el cumplimiento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a88") }, {"long_answer": "La línea 1 del Plan de Acción de Atención Primaria y Comunitaria 2025-2027 se dedica a fidelizar y atraer talento hacia la Atención Primaria, porque la falta de profesionales, la dificultad para cubrir plazas y la salida de personal hacia otros ámbitos son algunos de los principales problemas del primer nivel asistencial. Por ello recoge medidas de estabilidad laboral, condiciones atractivas y desarrollo profesional. La mejora de la capacidad diagnóstica, la financiación y la digitalización también aparecen en el Plan, pero corresponden a otras líneas o acciones y no constituyen el objetivo de la línea 1."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a8b") }, {"long_answer": "La línea 2 del Plan de Acción de Atención Primaria y Comunitaria busca ampliar los perfiles profesionales del equipo de Atención Primaria y mejorar su coordinación, incorporando o reforzando figuras como fisioterapia, psicología clínica, farmacia, trabajo social u otras, para dar una respuesta más resolutiva y multidisciplinar. Las demás opciones van en sentido contrario al Plan: no se plantea reducir el personal sanitario, ni limitar la dispensación de medicamentos a los médicos, ni eliminar procesos administrativos con el objetivo de abaratar costes, sino reorganizar y reforzar el equipo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a8e") }, {"long_answer": "Según los datos de diagnóstico que recoge el Plan de Acción de Atención Primaria y Comunitaria, el promedio de población asignada por profesional de Medicina Familiar y Comunitaria es de 1.351 personas. Esta cifra, procedente de los sistemas de información del SNS, se utiliza como referencia para valorar la carga asistencial y la necesidad de ajustar los cupos. La cifra de 1.370 es próxima pero no coincide con la reflejada en el documento, 901 personas es un valor muy inferior propio de otros perfiles o ámbitos, y 2.000 personas supera ampliamente el promedio nacional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a99") }, {"long_answer": "La evaluación del Plan de Acción de Atención Primaria 2022-2023 mostró que más del 80% de las acciones previstas alcanzaron un cumplimiento parcial o total, lo que el nuevo Plan 2025-2027 toma como punto de partida para dar continuidad a las medidas y reforzar las que quedaron pendientes. Las cifras inferiores, como menos del 40%, entre el 50 y el 60% o el 75%, no corresponden al resultado de la evaluación recogido en el documento, que fue claramente más favorable."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a9a") }, {"long_answer": "Según el diagnóstico de recursos humanos del Plan de Acción de Atención Primaria y Comunitaria, el 60% de las vacantes se cubrió con contratos de al menos dos años ofrecidos a los profesionales al terminar la residencia. Este tipo de medida busca retener a los especialistas recién formados y favorecer la estabilidad de los equipos, uno de los objetivos de la línea de fidelización del talento. Los porcentajes del 76%, el 100% y el 45% no corresponden al dato que recoge el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a9b") }, {"long_answer": "El Plan de Acción de Atención Primaria y Comunitaria recoge que el 64,70% de las Comunidades Autónomas, es decir, 11 de las 17, han implantado un presupuesto finalista específico para la mejora de la Atención Primaria. Este tipo de partida reservada garantiza que los fondos se destinen realmente al primer nivel asistencial. El 58,80% equivaldría a 10 de 17 comunidades y no es el dato del documento; el 75% y el 30% tampoco corresponden a la cifra recogida en el diagnóstico de situación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a9d") }, {"long_answer": "El Plan establece que la Atención Primaria debe coordinarse y alinearse con instituciones sanitarias y no sanitarias, incluidas Salud Pública y la Atención Sociosanitaria, para actuar sobre los determinantes sociales de la salud, ya que estos dependen de ámbitos como la vivienda, la educación, el empleo o los servicios sociales. Limitar esa coordinación solo a la Atención Especializada, solo a las Administraciones Locales o exclusivamente a los Servicios Sociales sería insuficiente, porque el abordaje de los determinantes exige una acción intersectorial amplia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a9e") }, {"long_answer": "Según los datos de opinión ciudadana que recoge el Plan, procedentes del Barómetro Sanitario, el 46,50% de la población cree que la sanidad pública presta los mismos servicios con independencia de la comunidad autónoma de residencia. Es decir, menos de la mitad percibe homogeneidad entre territorios, lo que refuerza la necesidad de trabajar la equidad y la cohesión del SNS. Los porcentajes del 75,80%, el 82% y el 57% no corresponden al dato que recoge el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aa1") }, {"long_answer": "Uno de los retos de la línea 6 del Plan de Acción de Atención Primaria y Comunitaria es impulsar la atención familiar en el hogar y garantizar la continuidad asistencial, especialmente en personas con dependencia, cronicidad compleja o al final de la vida, coordinando la Atención Primaria con el resto de recursos sanitarios y sociales. Las demás opciones contradicen la filosofía del Plan: no se busca reducir profesionales en zonas urbanas, ni centralizar la atención en los hospitales, ni aumentar la burocracia, sino acercar la atención al domicilio y reducir cargas administrativas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aa4") }, {"long_answer": "Según los datos del Barómetro Sanitario recogidos en el Plan, el 69% de los pacientes que recibieron consulta telefónica en Atención Primaria se declara bastante o muy satisfecho con ella. Es un nivel de satisfacción aceptable, aunque inferior al de la atención presencial, por lo que el Plan plantea criterios comunes para la atención no presencial y su uso como complemento, no como sustituto. Los porcentajes del 82,20%, el 50,30% y el 33,90% no corresponden al dato recogido en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aa9") }, {"long_answer": "El Plan potencia las herramientas digitales en las zonas rurales más despobladas para fortalecer la cobertura asistencial y mejorar el acceso a la atención sanitaria, ya que la dispersión geográfica y la falta de profesionales dificultan la atención presencial continua. La teleconsulta y otras herramientas complementan la atención, pero no pretenden reemplazar por completo la presencialidad. Tampoco buscan restringir el acceso para ahorrar recursos ni reservar estas herramientas en exclusiva al personal sanitario, lo que iría en contra de la equidad que persigue el Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ab1") }, {"long_answer": "El Plan promueve la investigación cooperativa en redes específicas de Atención Primaria mediante la priorización de convocatorias de redes dentro de la Acción Estratégica en Salud (AES), gestionada por el Instituto de Salud Carlos III. Con ello se pretende que los grupos de Atención Primaria accedan a financiación estable y colaboren entre sí. Las demás opciones van en sentido contrario: no se busca reducir la participación de los clínicos, ni limitar la cooperación a los grandes hospitales, ni eliminar las redes de Atención Primaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ab4") }, {"long_answer": "Para favorecer que los profesionales de Atención Primaria participen en la convocatoria de intensificación de la actividad investigadora, el Plan prevé liberar parte de su tiempo de dedicación asistencial, de modo que puedan dedicar horas de su jornada a investigar sin abandonar la práctica clínica. No se contempla una reducción de jornada sin límite ni la suspensión completa de la actividad asistencial, ya que se busca compatibilizar ambas tareas, y tampoco se limita a liberar tareas administrativas, que no es el objeto de la intensificación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ab6") }, {"long_answer": "El Plan fija como objetivo que el porcentaje de profesionales de Atención Primaria integrados en los Institutos de Investigación Sanitaria (IIS) acreditados aumente en un 15% o más durante el periodo 2025-2027, tomando como referencia la situación de enero de 2024. Con ello se pretende reforzar el peso de la Atención Primaria en las estructuras de investigación biomédica. Un incremento del 5% sin evaluación, una disminución o la ausencia de incremento no se corresponden con la meta del Plan, que apuesta por impulsar la investigación en este nivel."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977abc") }, {"long_answer": "El Plan atribuye al Ministerio de Sanidad la evaluación, antes de 2026, del grado de implantación de la modalidad de atención no presencial en Atención Primaria en las Comunidades Autónomas, en coherencia con su papel de coordinación y cohesión del SNS. No la realizan las Comunidades Autónomas sin coordinación central, ya que se busca una visión de conjunto, ni el Instituto de Salud Carlos III al margen del Ministerio, ni entidades privadas, que no tienen competencias de evaluación de las políticas del SNS."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977abd") }, {"long_answer": "El indicador previsto es el número de estancias formativas ofertadas y realizadas, desglosadas por sexo, señalando las realizadas por personas de instituciones distintas a la que oferta la estancia; así se puede seguir su evolución anual y la movilidad entre grupos. Las estancias internas sin colaboración externa no reflejan intercambio entre instituciones, que es precisamente lo que se quiere medir. Contabilizar las estancias canceladas o las de duración inferior a una semana no informa sobre la evolución de la colaboración interinstitucional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ac0") }, {"long_answer": "Para aumentar la presencia de los grupos de investigación de Atención Primaria en proyectos europeos, el Plan prioriza la difusión de las convocatorias y el apoyo dirigido a estos grupos, por ejemplo mediante asesoramiento en la preparación de propuestas, ya que su participación internacional es todavía escasa. Reducir la participación para ahorrar costes, incluir solo proyectos con presencia hospitalaria o fomentar proyectos sin profesionales de Atención Primaria contradice el objetivo de fortalecer la investigación propia de este nivel asistencial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ac5") }, {"long_answer": "El Plan prevé publicar en diciembre de 2025 un documento con los indicadores comunes consensuados en el Grupo de Trabajo de Salud Comunitaria para evaluar las Estrategias de Salud Comunitaria de las Comunidades Autónomas. Disponer de indicadores comunes permite comparar la implantación entre territorios y facilita la evaluación participada. Un plan de capacitación profesional, un informe sobre brecha digital o un manual de implementación de servicios comunitarios pueden ser útiles, pero no son el documento ligado a la evaluación de las Estrategias en esa fecha."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ac7") }, {"long_answer": "Para medir la incorporación de los condicionantes sociales y del contexto familiar en la Historia de Salud Digital, el Plan utiliza el porcentaje de Comunidades Autónomas que han incorporado el conjunto mínimo de condicionantes consensuado. Este indicador refleja si los sistemas de información recogen de forma homogénea aspectos como la situación social o familiar, relevantes para una atención integral. El número de profesionales formados, el número de visitas no presenciales o la satisfacción de los pacientes miden otras cuestiones y no la incorporación de esos datos a la historia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ac8") }, {"long_answer": "Incluir herramientas de recomendación de activos para la salud en la Historia de Salud Digital permite al profesional ofrecer un consejo integral y adaptado a cada persona sin salir del contexto de la consulta, recomendando recursos comunitarios como grupos, asociaciones o actividades del barrio. Es una forma de facilitar la prescripción social desde la propia historia clínica. No tiene como objetivo principal reducir la carga administrativa, aumentar las visitas presenciales de seguimiento ni mejorar la interoperabilidad entre hospitales, que son cuestiones abordadas en otras acciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977acc") }, {"long_answer": "Las convocatorias competitivas y no competitivas específicas para Atención Primaria buscan, entre otros fines, facilitar el inicio en la investigación, especialmente de los profesionales jóvenes, que suelen tener más dificultades para competir con grupos consolidados en las convocatorias generales. Así se favorece la creación de una masa crítica investigadora en este nivel. Reducir la tensión asistencial, aumentar el uso de la Historia de Salud Digital o incrementar la atención presencial a grupos vulnerables son objetivos de otras líneas del Plan, no de estas convocatorias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ad2") }, {"long_answer": "El Plan toma como referencia para la modalidad de atención no presencial en Atención Primaria la norma UNE 179011:2023, una norma técnica española sobre la teleconsulta y la atención sanitaria no presencial que establece requisitos de calidad y seguridad para este tipo de atención. La ISO 9001:2015 regula sistemas de gestión de calidad en general y la ISO 14001:2018 se refiere a la gestión ambiental, por lo que no son específicas de la atención no presencial. La UNE 139802:2022 pertenece a la serie de normas de accesibilidad de las tecnologías de la información y no es la referencia citada para la atención no presencial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ad3") }, {"long_answer": "La educación sanitaria individualizada avanzada no es uno de los niveles de la formación online en orientación comunitaria dirigida a profesionales de Atención Primaria, ya que este itinerario se centra en el trabajo colectivo y comunitario, no en la intervención individual. Los niveles formativos que recoge el Plan son la acción comunitaria para la salud, la equidad en salud con el curso Aprendiendo con el pueblo gitano y la educación para la salud grupal sobre estilos de vida, todos ellos orientados a la intervención con grupos y comunidades."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ad7") }, {"long_answer": "La evaluación convocada para antes de 2026 tiene como objetivo medir el grado de implantación de la modalidad de atención no presencial en Atención Primaria en las Comunidades Autónomas, para conocer cómo se está aplicando y si se ajusta a los criterios comunes acordados. Auditar la calidad de la historia clínica digital, evaluar la capacitación en salud comunitaria o medir la penetración de la telemonitorización en pacientes crónicos son cuestiones diferentes, que no constituyen el objeto de esta evaluación concreta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ad8") }, {"long_answer": "Dentro del Plan de Transformación Digital de Atención Primaria, el grupo de trabajo encargado de la escuela de pacientes y de la promoción de la salud es el GT3. Este grupo impulsa herramientas digitales para que la ciudadanía acceda a información de salud fiable y participe activamente en su autocuidado. Los grupos GT2, GT4 y GT6 tienen asignados otros ámbitos del plan de transformación digital, por lo que no son los responsables de la escuela de pacientes ni de la promoción de la salud."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ad9") }, {"long_answer": "Para garantizar la equidad en el acceso, el Plan propone adecuar las modalidades de atención, presencial, telefónica o telemática, a las necesidades de la población y reducir la brecha digital, de manera que nadie quede excluido por su edad, nivel socioeconómico o competencias digitales. Imponer la asistencia presencial obligatoria en todos los casos restaría accesibilidad, limitar la teleconsulta a las personas mayores no tiene justificación y eliminar la atención online en zonas rurales perjudicaría precisamente a la población con más dificultades de acceso."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ada") }, {"long_answer": "La Estrategia de Salud Comunitaria plantea implicar a diferentes agentes, incluida la ciudadanía, en todo el proceso, desde la identificación de necesidades y activos hasta la planificación, la ejecución y la evaluación de las intervenciones. La participación comunitaria es un elemento central de la orientación comunitaria de la Atención Primaria. Por eso son incorrectas las opciones que plantean una gestión exclusivamente profesional, un trabajo solo entre administraciones y profesionales o una delegación total en asociaciones locales sin coordinación con el sistema sanitario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977adc") }, {"long_answer": "El Plan establece como objetivo que, a partir de 2026, el 100% de las Comunidades Autónomas publiquen anualmente la evaluación de la implementación de sus Estrategias de Salud Comunitaria. La publicación por todas las comunidades favorece la transparencia, la rendición de cuentas y la comparación entre territorios, y se apoya en los indicadores comunes consensuados en el Grupo de Trabajo de Salud Comunitaria. Los porcentajes del 75%, el 50% y el 25% no se corresponden con la meta, que alcanza a la totalidad de las comunidades."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ae4") }, {"long_answer": "El Instrumento Estandarizado aprobado por el Consejo Interterritorial del SNS para los servicios sanitarios tiene como objetivo mejorar la detección temprana de la violencia de género, facilitando que los profesionales, especialmente de Atención Primaria, identifiquen precozmente los casos y actúen de forma homogénea en todo el territorio. La formación en atención materna, la reducción de la obesidad infantil y la gestión de recursos humanos en zonas rurales son objetivos de otras actuaciones y no guardan relación con este instrumento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aea") }, {"long_answer": "El Plan fija como meta que para 2027 al menos el 80% de las Comunidades Autónomas trabajen en la identificación de las personas en situación de soledad no deseada, un problema con repercusiones sobre la salud física y mental, sobre todo en personas mayores. La Atención Primaria, por su cercanía y longitudinalidad, ocupa un lugar privilegiado para detectar estas situaciones y vincular a las personas con recursos comunitarios. Los porcentajes del 60%, el 50% y el 40% son inferiores a la meta establecida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aed") }, {"long_answer": "El Plan prevé que los indicadores seleccionados para monitorizar la Atención Primaria se publiquen antes de que finalice 2025, como paso previo a la elaboración del primer informe del SNS sobre su situación, cuyos resultados se publicarían posteriormente. Fijar primero los indicadores permite que todas las comunidades recojan la información de forma homogénea. Fin de 2026 corresponde a la publicación de los resultados, fin de 2027 es el horizonte final del Plan y fin de 2024 es anterior a su periodo de vigencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977af4") }, {"long_answer": "Para integrar la participación comunitaria en la toma de decisiones de las políticas de Atención Primaria y Comunitaria, el Plan propone crear mecanismos de participación y canales de comunicación estables entre los órganos decisores y la comunidad, de forma que la ciudadanía pueda aportar sus necesidades y propuestas. Las consultas esporádicas sin canales formales no garantizan una participación real, la delegación total en asociaciones externas desvincula la participación de la toma de decisiones y eliminar las consultas comunitarias va en contra del enfoque del Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977af6") }, {"long_answer": "La actualización del contenido y la metodología de los planes de gestión anuales de los centros de salud busca impulsar la autonomía de gestión de los equipos de Atención Primaria y establecer un marco común de evaluación que permita comparar resultados entre centros y territorios. Las opciones que plantean reducir la participación de los profesionales, centralizar la gestión en el Ministerio de Sanidad o eliminar la evaluación de los planes son contrarias a este objetivo, que apuesta por la descentralización y la gestión participativa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b00") }, {"long_answer": "En el modelo colaborativo entre Atención Primaria y Salud Mental, el profesional de salud mental realiza intervenciones breves individuales y grupales, participa en la formación de los equipos de Atención Primaria, ofrece consultoría sobre casos y actúa de enlace entre ambos niveles. Este modelo mejora la resolución de los problemas de salud mental comunes desde el primer nivel y evita derivaciones innecesarias. No se limita a la atención en crisis hospitalarias, ni solo a la formación sin atención directa, ni a tareas de gestión administrativa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b01") }, {"long_answer": "El Plan establece como resultado esperado para 2026 que el 100% de las Comunidades Autónomas tengan implantados programas colaborativos entre Atención Primaria y Salud Mental, de modo que todas cuenten con este modelo de atención compartida para los problemas de salud mental más frecuentes. Las opciones que hablan de un 50% de comunidades con programas en desarrollo, de solo un 30% o de ninguna comunidad no se corresponden con la meta, que pretende la extensión del modelo a todo el territorio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b02") }, {"long_answer": "Además de la implantación en todas las Comunidades Autónomas, el Plan fija como objetivo que para 2027 al menos el 60% de las áreas sanitarias cuenten con programas colaborativos entre Atención Primaria y Salud Mental, lo que supone extender el modelo a la mayor parte del territorio de cada comunidad. Un 90% supera la meta fijada, mientras que el 40% y el 20% son inferiores a ella, por lo que ninguna de estas cifras se corresponde con el objetivo establecido en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b04") }, {"long_answer": "El Plan fija que para 2027 al menos el 80% de las Comunidades Autónomas tengan implantado un sistema de comunicación bidireccional entre las farmacias comunitarias y los profesionales de los centros de salud. Esta comunicación facilita la coordinación en el seguimiento farmacoterapéutico, la detección de problemas relacionados con los medicamentos y la adherencia, especialmente en pacientes polimedicados. Los porcentajes del 70%, el 50% y el 90% no se corresponden con la meta recogida en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b09") }, {"long_answer": "La pandemia de COVID-19 puso de manifiesto la vulnerabilidad de la cadena de suministro farmacéutica, muy concentrada en pocas empresas situadas fuera de la Unión Europea, sobre todo en la fabricación de materias primas y principios activos y de medicamentos genéricos, lo que provocó problemas de abastecimiento. Por eso la Estrategia apuesta por la autonomía estratégica. No hubo un aumento de la producción local que garantizara la autosuficiencia, ni un exceso de diversificación de proveedores o de materias primas almacenadas; el problema fue precisamente el contrario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b13") }, {"long_answer": "La medicina personalizada de precisión se basa en integrar datos genéticos, clínicos, ambientales, socioeconómicos y otros datos relevantes del paciente para adaptar la prevención, el diagnóstico y el tratamiento a sus características individuales. Por eso no se apoya en desarrollos genéricos estandarizados ni en el uso exclusivo de medicamentos tradicionales, que aplican el mismo abordaje a todos los pacientes. Aunque las terapias avanzadas celulares pueden formar parte de ella, la medicina de precisión no se reduce exclusivamente a este tipo de terapias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b16") }, {"long_answer": "La Estrategia contempla que, si se superase la tasa de referencia del gasto farmacéutico, el Estado, las Comunidades Autónomas y la industria evalúen la situación y adopten medidas de mejora que contribuyan a la sostenibilidad financiera del Sistema Nacional de Salud, en un marco de corresponsabilidad. Aumentar el precio de los medicamentos incrementaría el gasto, reducir la inversión en innovación perjudicaría el desarrollo del sector y limitar la producción de genéricos iría en contra de su papel en la sostenibilidad del sistema."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b17") }, {"long_answer": "La Estrategia propone un sistema de evaluación de la eficiencia de las tecnologías sanitarias y de fijación de precios de los medicamentos en el que se separen claramente las funciones de evaluación, negociación y gestión, para garantizar la transparencia, la independencia técnica de la evaluación y la ausencia de conflictos de interés. Integrar todas las funciones en una única unidad, hacer depender la evaluación de quienes negocian con la industria o eliminar la participación pública en la fijación de precios irían en contra de estos principios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b1a") }, {"long_answer": "En la gobernanza de la Estrategia de la Industria Farmacéutica, la Comisión técnica interministerial se encarga de preparar las reuniones del órgano de nivel superior, coordinar las actuaciones de los distintos ministerios y establecer los recursos necesarios para avanzar en la ejecución de las medidas. No delega el seguimiento en la industria, ya que la gobernanza es pública, ni se limita a una reunión anual informativa, y tampoco gestiona la comercialización de medicamentos, que no forma parte de sus funciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b24") }, {"long_answer": "La Estrategia considera fundamental la evaluación clínica y económica de los medicamentos, porque aporta la base técnica para decidir el precio y la financiación pública y para controlar el crecimiento del gasto farmacéutico, priorizando aquellos fármacos que aportan valor terapéutico real. Esta evaluación no se sustituye por decisiones comerciales de la industria, no se limita a los medicamentos nuevos y no depende exclusivamente de organismos internacionales, aunque se coordine con la evaluación europea de tecnologías sanitarias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b2b") }, {"long_answer": "Según los datos de contexto de la Estrategia, se estima que el volumen global de medicamentos, medido en unidades consumidas, crecerá en torno a un 2,30% anual entre 2023 y 2028. Este crecimiento moderado en volumen contrasta con el mayor crecimiento del mercado en valor, de entre un 5 y un 8% anual, impulsado sobre todo por la entrada de medicamentos innovadores de alto precio. Las cifras del 10% y del 0,50% tampoco corresponden al dato recogido en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b31") }, {"long_answer": "El Plan INNVIERTE tiene como objetivo prioritario impulsar la inversión en el sector biomédico, especialmente en proyectos de desarrollo de tratamientos avanzados, movilizando capital público y privado para que la innovación llegue a fases de desarrollo clínico y a los pacientes. No busca concentrar la producción farmacéutica en un único centro nacional, ni reducir la inversión pública en investigación clínica, ni obligar a una reducción drástica del gasto farmacéutico, que serían objetivos ajenos a un instrumento de inversión."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b33") }, {"long_answer": "Dentro de la inversión en I+D de la industria farmacéutica en España en 2022, el ámbito más relevante fue la investigación clínica, es decir, los ensayos clínicos, que concentran la mayor parte del gasto en investigación del sector y en los que España ocupa una posición destacada en Europa. La investigación básica tiene un peso menor en la inversión de la industria. La fabricación y la comercialización internacional no son ámbitos de I+D en sentido estricto, sino actividades productivas y comerciales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b34") }, {"long_answer": "La Estrategia recoge que, en el periodo 2023-2028, se espera que el mercado farmacéutico mundial crezca en valor a un ritmo medio anual de entre el 5 y el 8%, impulsado sobre todo por los medicamentos innovadores, como los de oncología, inmunología o las terapias avanzadas. Este crecimiento es superior al del volumen de unidades consumidas. Un crecimiento inferior al 2%, superior al 10% o el estancamiento total no se corresponden con las previsiones recogidas en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b35") }, {"long_answer": "El Sistema Nacional de Salud es el principal cliente de la industria farmacéutica en España, ya que financia la mayor parte de los medicamentos dispensados en farmacias y utilizados en los hospitales, con un gasto que crece año tras año. Esta relación explica la necesidad de equilibrar innovación, acceso y sostenibilidad. El SNS no compite con la industria en la producción de genéricos, no es el único responsable de la innovación, que también depende de la industria y del sistema de ciencia, y no es solo un regulador sin relación de compra."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b3d") }, {"long_answer": "España es el principal foco europeo de ensayos clínicos con medicamentos y, a escala mundial, solo la superan Estados Unidos y China en número de ensayos, gracias a la calidad de sus centros, la agilidad de la autorización y la experiencia de sus investigadores. Por eso es falso que ocupe la última posición dentro de la Unión Europea, que no participe en ensayos internacionales o que se limite a ensayos con medicamentos genéricos; la mayoría de los ensayos que acoge son de medicamentos innovadores e internacionales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b3e") }, {"long_answer": "Para que la industria farmacéutica contribuya a la sostenibilidad del Sistema Nacional de Salud, la Estrategia plantea integrar la innovación, la producción, el acceso de los pacientes a los medicamentos y el control del gasto, de forma que los avances terapéuticos lleguen a la población sin comprometer la viabilidad del sistema. Concentrar el gasto solo en medicamentos innovadores de alto coste, reducir la producción nacional aumentando las importaciones o limitar la producción a unos pocos medicamentos esenciales irían en contra de esa visión integrada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b42") }, {"long_answer": "La Estrategia muestra el compromiso del Estado con el sector biomédico a través de inversiones sin precedentes mediante programas como INNVIERTE, orientado a la inversión en empresas innovadoras, y TERAFRONT, sociedad público-privada para el desarrollo de terapias avanzadas. Ambos instrumentos pretenden que la investigación se traduzca en productos que lleguen a los pacientes. La disminución de fondos para investigación clínica, la focalización solo en genéricos o la suspensión de programas público-privados son contrarios a lo que plantea la Estrategia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b43") }, {"long_answer": "En investigación y desarrollo, la Estrategia busca incrementar la financiación, reforzar las estructuras de soporte a la investigación clínica y preclínica y promover la medicina personalizada de precisión, para que España mantenga y mejore su posición en innovación biomédica. Reducir la investigación para centrarse en la producción masiva, concentrarla únicamente en el sector privado sin colaboración pública o limitar la formación en I+D contradicen el planteamiento de la Estrategia, que apuesta por la colaboración público-privada y por el refuerzo del sistema investigador."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b44") }, {"long_answer": "La Regla de Gasto y la comunicación europea sobre la política fiscal condicionan la Estrategia nacional en 2023-2024, porque obligan a contener el crecimiento del gasto público, incluido el farmacéutico. Por ello hacen necesario priorizar a la vez el acceso oportuno a los medicamentos y el control del gasto farmacéutico. Estas reglas no permiten eliminar los controles presupuestarios ni aumentar libremente el gasto, no eximen a las Comunidades Autónomas de su responsabilidad en el gasto y tampoco prohíben invertir en medicamentos innovadores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b50") }, {"long_answer": "Para garantizar la igualdad en el acceso al diagnóstico molecular, la Estrategia plantea incluir en la cartera común de servicios del SNS los biomarcadores necesarios para utilizar un medicamento en el momento en que ese medicamento se incorpora a la financiación, de forma que cualquier paciente pueda acceder a la prueba con independencia de dónde viva. Fomentar la competencia de laboratorios privados sin regulación, reducir la inversión pública en genética o suspender el intercambio de datos genómicos entre comunidades aumentaría las desigualdades."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b56") }, {"long_answer": "La Estrategia promueve la investigación en Atención Primaria impulsando la realización de ensayos clínicos en este nivel asistencial, creando unidades de investigación clínica en Atención Primaria y favoreciendo colaboraciones públicas y privadas, ya que gran parte de los pacientes con enfermedades crónicas se atienden allí. Limitar la investigación a hospitales de referencia, disminuir la inversión en ensayos en Atención Primaria o centralizarla en un único centro nacional irían en contra del objetivo de acercar la investigación clínica a la población."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b58") }, {"long_answer": "La participación de España en asociaciones europeas de investigación como ERDERA, centrada en enfermedades raras, y OH-AMR, dedicada a la resistencia a los antimicrobianos desde el enfoque Una sola salud, busca potenciar la presencia española en la investigación clínica y preclínica en áreas alineadas con las prioridades de la Estrategia. Consolidar una investigación exclusivamente nacional, evitar la colaboración público-privada o reducir la inversión en investigación biomédica son contrarios al sentido de estas alianzas internacionales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b5a") }, {"long_answer": "Entre las acciones previstas para las estructuras de soporte a la investigación clínica y preclínica, la Estrategia incluye reforzar la cohesión territorial y dotar de medios materiales y humanos a los centros de investigación, para que todas las Comunidades Autónomas puedan participar en ensayos y proyectos en condiciones adecuadas. Disminuir la participación autonómica, cerrar las unidades con baja producción o trasladar la mayoría de los ensayos al ámbito privado aumentarían las desigualdades territoriales que la Estrategia pretende corregir."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b5b") }, {"long_answer": "La Estrategia prevé mesas de diálogo con los agentes implicados en la realización de ensayos clínicos, como promotores, centros, investigadores y comités de ética, para resolver las dificultades técnicas que surgen en la práctica y adaptar los procesos a la digitalización y al Reglamento Europeo de ensayos clínicos. No pretenden promover la desregulación ni la entrada urgente de medicamentos sin garantías, ni limitar la participación del Estado en la investigación clínica, ni coordinar exclusivamente la compra pública."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b60") }, {"long_answer": "En el desarrollo de las Unidades de Investigación Clínica del SNS, la Estrategia prioriza garantizar una dedicación mínima a la investigación clínica independiente, es decir, no promovida por la industria, y a los medicamentos de interés estratégico para el sistema sanitario. Así se protege la investigación que responde a necesidades del SNS y no solo a intereses comerciales. Externalizar ensayos a otros países, reducir el número de ensayos o dedicarse exclusivamente a medicamentos genéricos no se corresponde con este planteamiento.", "option_1": "Garantizar una dedicación mínima a la investigación clínica independiente y a medicamentos de interés estratégico"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b6b") }, {"long_answer": "El programa IMPaCT, Infraestructura de Medicina de Precisión asociada a la Ciencia y la Tecnología, impulsado por el Instituto de Salud Carlos III, busca transformar la toma de decisiones clínicas mediante el uso de grandes volúmenes de datos, genómicos, clínicos y de otro tipo, adaptados a las características individuales de cada paciente. No se limita al desarrollo de terapias génicas para enfermedades raras, no pretende reducir la presencia territorial de la medicina de precisión, sino extenderla, y no es un instrumento de gestión del presupuesto público de I+D."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b6e") }, {"long_answer": "TERAFRONT es una sociedad mercantil con participación pública y privada creada para desarrollar terapias avanzadas desde las fases clínicas precoces hasta su comercialización, de modo que los avances de la investigación española en este campo lleguen a los pacientes y generen valor en el propio país. No tiene como objetivo fabricar medicamentos genéricos de bajo coste, ni regular la producción de principios activos en laboratorios públicos, ni gestionar la distribución nacional de medicamentos hospitalarios, que son funciones ajenas a su finalidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b6f") }, {"long_answer": "La compra pública de innovación en salud está dirigida a desarrollar soluciones para necesidades clínicas no cubiertas que todavía no están disponibles en el mercado, de forma que la administración actúa como cliente que impulsa el desarrollo de productos o servicios innovadores. No pretende externalizar la producción farmacéutica a empresas extranjeras, ni limitar la innovación a productos ya establecidos, que es justo lo contrario de su finalidad. Promover la competencia entre proveedores tradicionales corresponde a la compra pública ordinaria, no a la de innovación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b72") }, {"long_answer": "En el ámbito de la formación en I+D+i, la Estrategia atribuye a la Agencia Española de Medicamentos y Productos Sanitarios el papel de proporcionar asesoría científico-regulatoria a los investigadores y empresas, formar a los agentes implicados en el desarrollo de medicamentos e incentivar el reposicionamiento terapéutico de fármacos ya existentes. Su función no se reduce a autorizar la comercialización de medicamentos, ni a capacitar solo a enfermeras en la práctica clínica habitual, ni a regular la formación de los técnicos de laboratorio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b74") }, {"long_answer": "La Reserva Estratégica basada en Capacidades Nacionales de Producción Industrial (RECAPI) tiene como propósito garantizar el suministro de productos esenciales y permitir la rápida movilización de la capacidad de producción industrial en situaciones de alta demanda, como emergencias sanitarias similares a la pandemia de COVID-19. No pretende centralizar en España toda la producción farmacéutica europea, ni dedicarse exclusivamente a exportar principios activos, ni limitar la producción nacional, lo que debilitaría la autonomía estratégica que busca reforzar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a8f") }, {"long_answer": "Según los datos de actividad recogidos en el Plan, la consulta en el centro sanitario es la modalidad con mayor número de consultas anuales en Medicina Familiar y Comunitaria, ya que la atención presencial sigue siendo la forma principal de contacto con la Atención Primaria. La teleconsulta ha aumentado desde la pandemia, pero continúa por detrás de la consulta presencial. La consulta domiciliaria tiene un volumen mucho menor y se reserva sobre todo a pacientes inmovilizados, y la consulta grupal es minoritaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a91") }, {"long_answer": "Entre las opciones planteadas, la enfermedad cerebrovascular es la principal causa de muerte entre las mujeres en España según los datos que recoge el informe, mientras que en los hombres la primera causa es la enfermedad isquémica del corazón. Esta diferencia por sexo es un dato clásico de la estadística de defunciones según causa de muerte. El cáncer de pulmón es una causa creciente en mujeres, pero no la primera, y los accidentes de tráfico tienen un peso mucho menor en la mortalidad global femenina."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a95") }, {"long_answer": "El Marco Estratégico para la Atención Primaria y Comunitaria se organiza en estrategias identificadas con letras, y la Estrategia F es la dedicada a impulsar la formación y la investigación en Atención Primaria. La Estrategia A se refiere al compromiso y liderazgo del Consejo Interterritorial con la Atención Primaria, la Estrategia C a mejorar la calidad de la atención y la coordinación con los demás ámbitos asistenciales y la Estrategia D a reforzar la orientación comunitaria, la promoción de la salud y la prevención."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a98") }, {"long_answer": "Según los datos del Plan, la tasa de hospitalizaciones potencialmente evitables por patologías agudas sensibles a los cuidados de Atención Primaria es de 31,0 por 10.000 habitantes. Este indicador incluye ingresos por procesos como infecciones urinarias, deshidratación o neumonías, que podrían evitarse con una atención primaria accesible y resolutiva, y se utiliza como medida indirecta de su efectividad. Las cifras de 50,3 y 76,2 por 10.000 y la de 10,8 por 1.000 habitantes no corresponden al dato de patologías agudas recogido en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aa0") }, {"long_answer": "En el Marco Estratégico de Atención Primaria y Comunitaria, la Estrategia C es la dirigida a mejorar la calidad de la atención y la coordinación con el resto de ámbitos asistenciales, servicios e instituciones, incluida la continuidad con la atención hospitalaria y la coordinación sociosanitaria. La Estrategia A se centra en el compromiso y liderazgo del Consejo Interterritorial, la Estrategia B en la política presupuestaria y de recursos humanos y la Estrategia E en el uso de las tecnologías de la información y la comunicación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aa5") }, {"long_answer": "Para hacer frente a la fuga de talento, el Plan contempla incentivar el retorno a la Atención Primaria de los profesionales que trabajan en otros ámbitos asistenciales, como urgencias u hospitales, junto con otras medidas de fidelización como la estabilidad laboral y el desarrollo profesional. Reducir el salario, limitar las oportunidades de crecimiento profesional o desincentivar la estabilidad laboral provocarían el efecto contrario, aumentando el abandono de la Atención Primaria y agravando el déficit de profesionales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aa8") }, {"long_answer": "Antes de 2027, el Plan prevé incorporar al modelo de gestión integral de la demanda criterios comunes para la modalidad de atención no presencial, de forma que la consulta telefónica o telemática se utilice de manera homogénea, segura y adecuada a cada situación en todas las Comunidades Autónomas. No se pretende reducir la atención presencial, priorizar únicamente a los pacientes crónicos ni eliminar la atención telefónica, sino ordenar las distintas modalidades de atención para mejorar la accesibilidad y la calidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aaa") }, {"long_answer": "Para mejorar el acceso al sistema sanitario de las personas sin hogar, el Plan señala como documento fundamental las recomendaciones para la mejora del acceso y el cuidado de la salud de estas personas, que abordan barreras como la falta de empadronamiento, de tarjeta sanitaria o de domicilio, y proponen circuitos adaptados. Un protocolo de exclusión sanitaria, un manual para evitar la atención no presencial o una guía para limitar recursos en zonas urbanas serían contrarios al objetivo de equidad del Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aab") }, {"long_answer": "La puesta en marcha de las recomendaciones para mejorar la atención a las personas sin hogar corresponde a las Comunidades Autónomas, que tienen las competencias en la gestión de la asistencia sanitaria, en coordinación con el Ministerio de Sanidad, que impulsa y coordina las recomendaciones a nivel estatal. No depende solo del Ministerio, que no gestiona directamente los servicios, ni de los centros de Atención Primaria sin apoyo externo, ya que se requiere coordinación con servicios sociales, ni de entidades privadas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aac") }, {"long_answer": "En la actualización anual del mapa de situación de la I+D en Atención Primaria, la información referida a personas, como investigadores o responsables de grupos, se presenta desglosada por sexo, siguiendo el enfoque de género que aplica el Plan a todos sus indicadores para detectar posibles desigualdades entre mujeres y hombres en la carrera investigadora. Presentarla agrupada sin desgloses impediría ese análisis, incluir solo datos de hombres sería discriminatorio y excluir a los profesionales investigadores dejaría el mapa sin su contenido principal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aae") }, {"long_answer": "Para medir el éxito del sistema de identificación de colaboradores en investigación en 2026 y 2027, el Plan utiliza el número de consultas realizadas anualmente a través de esta utilidad, ya que refleja en qué medida los profesionales la usan para encontrar personas o grupos con intereses afines. El número de proyectos internacionales aprobados, el total de profesionales de Atención Primaria o las publicaciones de cada investigador miden otros aspectos y no dependen directamente del uso de esta herramienta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aaf") }, {"long_answer": "El seguimiento del número de estancias formativas ofertadas y realizadas se presenta desglosado por sexo y señalando cuáles han sido realizadas por profesionales de instituciones distintas a la que oferta la estancia, porque el objetivo es fomentar la colaboración y el intercambio entre grupos de investigación con perspectiva de género. Por eso son incorrectas las opciones que excluyen las estancias de personas externas, que las limitan a la misma institución o que ignoran las diferencias por sexo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ab2") }, {"long_answer": "El aumento de la investigación cooperativa en la Acción Estratégica en Salud se refleja en el incremento del número de grupos liderados por profesionales con actividad clínica en Atención Primaria que obtienen financiación dentro de las redes cooperativas. Este indicador muestra si la Atención Primaria gana peso real en las estructuras de investigación en red. La reducción de proyectos cooperativos o de grupos emergentes indicaría un retroceso, y el número total de concursos públicos generales no mide la investigación cooperativa en Atención Primaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977abf") }, {"long_answer": "En el ámbito de la investigación cooperativa, el número de grupos liderados por personas con actividad clínica en Atención Primaria que reciben financiación en redes se presenta además desglosado por sexo, para analizar si existen diferencias entre mujeres y hombres en el liderazgo de la investigación. Las publicaciones sin distinción de sexo no cumplen con el enfoque de género del Plan, y los datos económicos por comunidad o las remuneraciones de los investigadores no forman parte de este indicador."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ac3") }, {"long_answer": "En el seguimiento de los indicadores de investigación en Atención Primaria, toda la información referida a personas se presenta desglosada por sexo, de acuerdo con el principio de igualdad de género que el Plan aplica de forma transversal. Este desglose permite detectar posibles brechas en la participación, el liderazgo o la financiación de la investigación. Por eso son incorrectas las opciones que afirman que no se detalla ninguna variable sociodemográfica, que solo se recoge información profesional o que se ignoran los datos de sexo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ac6") }, {"long_answer": "La formación avanzada en telemonitorización no forma parte de los tres niveles de formación en orientación comunitaria dirigida a los profesionales de Atención Primaria, ya que pertenece al ámbito de la atención digital y no al trabajo comunitario. Los niveles de esta formación son la acción comunitaria para la salud, la equidad en salud con el curso Aprendiendo con el pueblo gitano y la educación para la salud grupal sobre estilos de vida, todos ellos centrados en la intervención con grupos y comunidades."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ac9") }, {"long_answer": "El Plan fija como meta que en diciembre de 2027 el 100% de las Comunidades Autónomas enlacen desde la Historia de Salud Digital a herramientas de recomendación de activos para la salud, coincidiendo con el final de su periodo de vigencia. Estas herramientas permiten al profesional recomendar recursos comunitarios durante la consulta. Las fechas de diciembre de 2025 y diciembre de 2026 corresponden a hitos intermedios de otras acciones del Plan, y diciembre de 2028 queda fuera del periodo 2025-2027."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977acb") }, {"long_answer": "El módulo específico que se desarrollará en el mapa de I+D en Atención Primaria durante 2026-2027 servirá para facilitar la búsqueda e identificación de personas o grupos de investigación con intereses afines, favoreciendo la colaboración y la creación de redes entre profesionales de distintos centros y comunidades. No se trata de un sistema para registrar citas médicas digitales, para monitorizar el uso de las teleconsultas en cada comunidad ni para evaluar la formación en competencias comunitarias, que son cuestiones ajenas a la investigación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977acf") }, {"long_answer": "La meta del Plan para diciembre de 2027 es que en cada Instituto de Investigación Sanitaria haya al menos un 5% de participación de profesionales de Atención Primaria o un mínimo de 40 personas investigadoras de este ámbito, para asegurar su presencia real en las estructuras de investigación biomédica. Una participación del 50% en proyectos europeos, una reducción del 15% de las cargas asistenciales o duplicar el número de grupos de investigación no son las metas fijadas para esta acción."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977adb") }, {"long_answer": "La actualización de la Cartera Básica Común de Atención Primaria para incluir los servicios de atención comunitaria tiene como finalidad que las Comunidades Autónomas adecúen sus servicios para mejorar la atención comunitaria, de forma que actividades como la educación para la salud grupal o la intervención comunitaria tengan un reconocimiento homogéneo en todo el SNS. No se busca reducir la oferta de servicios para ahorrar costes, establecer nuevos criterios de exclusión de pacientes ni centralizar la atención en los hospitales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977add") }, {"long_answer": "Las encuestas dirigidas exclusivamente a gestores hospitalarios no son un mecanismo de evaluación participada de las Estrategias de Salud Comunitaria, porque la evaluación participada implica a la ciudadanía, a los profesionales de Atención Primaria y a otros agentes comunitarios, no solo a gestores de otro nivel asistencial. Sí forman parte de este proceso los indicadores comunes consensuados en el Grupo de Trabajo de Salud Comunitaria, las evaluaciones participadas con los agentes implicados y la difusión de los resultados a la población y a los profesionales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977adf") }, {"long_answer": "En relación con la teleconsulta, el Plan busca reducir las barreras derivadas de la brecha digital en los colectivos vulnerables y las personas mayores, que pueden tener menos acceso a dispositivos o menos competencias digitales, para que la atención no presencial no genere desigualdades. Excluir a estos colectivos de la modalidad no presencial, ofrecerles teleconsulta solo en horario reducido o imponerla como obligatoria en todas las visitas no garantiza la equidad, ya que la modalidad debe adaptarse a las necesidades de cada persona."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ae2") }, {"long_answer": "El mapa actualizado de situación de la I+D en Atención Primaria tiene como propósito visibilizar la investigación que se realiza en este nivel asistencial, identificar sinergias entre grupos y centros y optimizar los recursos disponibles, evitando duplicidades y favoreciendo la colaboración. No pretende centralizar todos los proyectos en Madrid, limitar la investigación a las áreas urbanas ni eliminarla en zonas con poca población, lo que iría en contra de la cohesión territorial que persigue el Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ae3") }, {"long_answer": "Dentro de sus Estrategias de Salud Comunitaria, las Comunidades Autónomas promoverán la formación práctica en competencias y habilidades en salud comunitaria dirigida a los profesionales, para que puedan aplicar en su trabajo diario herramientas como el mapeo de activos, la intervención grupal o la participación comunitaria. La formación exclusiva en atención hospitalaria, los cursos de técnicas quirúrgicas avanzadas o los seminarios de gestión financiera solo para médicos no guardan relación con la orientación comunitaria de la Atención Primaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aee") }, {"long_answer": "En la acción del Plan dedicada a la monitorización de la Atención Primaria, el indicador 2 corresponde a la publicación del resultado de los indicadores antes de que finalice 2026, una vez que previamente se han seleccionado y publicado los indicadores que se van a utilizar. Este orden permite elaborar el primer informe del SNS con datos homogéneos de todas las comunidades. Los indicadores 1, 3 y 4 se refieren a otros hitos de la acción y no a la publicación de estos resultados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977af0") }, {"long_answer": "Antes de 2026, la Oficina Ejecutiva del Marco Estratégico de Atención Primaria y Comunitaria debe desarrollar un procedimiento para identificar, seleccionar y evaluar prácticas innovadoras y buenas prácticas en este ámbito, con el fin de difundirlas y facilitar que se extiendan a otros centros y comunidades. Capacitar a los profesionales en cuidados paliativos, reducir el gasto farmacéutico o elaborar informes financieros para las Comunidades Autónomas no son el objetivo de este procedimiento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977af2") }, {"long_answer": "En el análisis de necesidades de las zonas rurales más despobladas, el Plan prevé publicar antes de 2026 un documento de consenso con criterios específicos comunes, que sirva de referencia a las Comunidades Autónomas para reorganizar recursos e inversiones según las características de estas zonas, como la dispersión y el envejecimiento. Un plan de inversión en infraestructuras, un informe de evaluación económica o unas recomendaciones para la atención urgente pueden derivarse de ese análisis, pero no son el documento que establece el Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977af3") }, {"long_answer": "El Plan establece como meta que el 100% de las Comunidades Autónomas más afectadas por la despoblación hayan realizado la evaluación de necesidades específicas para reorganizar sus recursos e inversiones en Atención Primaria, aplicando los criterios comunes consensuados. La meta abarca a todas estas comunidades porque son las que más dificultades tienen para garantizar el acceso en el medio rural. Las opciones que hablan del 50%, del 75% o de que ninguna ha realizado la evaluación no se corresponden con el objetivo fijado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977af7") }, {"long_answer": "El Plan fija como objetivo que antes de 2027 al menos el 10% de los profesionales de Atención Primaria reciban formación en gestión, para reforzar las competencias necesarias en un modelo que apuesta por una mayor autonomía de gestión de los centros de salud y por la participación de los profesionales en la toma de decisiones. Los porcentajes del 50%, el 5% y el 30% no se corresponden con la meta recogida en el documento para esta acción formativa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977af8") }, {"long_answer": "En el marco de la coordinación sociosanitaria, la definición de perfiles incluye a las personas que necesitan una atención sanitaria y social integrada, teniendo en cuenta múltiples factores como la dependencia, la cronicidad, la situación social, el apoyo familiar o la vulnerabilidad. No se limita a los pacientes hospitalizados por enfermedades crónicas ni a las personas mayores de 80 años, ya que la necesidad sociosanitaria puede darse a cualquier edad, y no incluye a personas sin necesidades sociales, que no requieren este tipo de atención."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977afa") }, {"long_answer": "El Plan fija como meta que en 2027 el 100% de las Comunidades Autónomas tengan implantada la interoperabilidad de la historia clínica digital entre la Atención Primaria y la atención hospitalaria, de modo que la información clínica esté disponible para los profesionales de ambos niveles. Esto favorece la continuidad asistencial, evita duplicidades de pruebas y mejora la seguridad del paciente. Los porcentajes del 90%, el 75% y el 50% no se corresponden con la meta, que abarca a todas las comunidades."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977afc") }, {"long_answer": "Para asegurar una atención integral en la atención familiar en el hogar, el Plan considera fundamental la coordinación con la atención hospitalaria, por ejemplo con unidades de hospitalización a domicilio o de cuidados paliativos, y con la Estrategia estatal para un nuevo modelo de cuidados en la comunidad, que integra los recursos sociales. Limitarse a actividades de Atención Primaria sin apoyo externo, colaborar solo con hospitales privados o eliminar la colaboración interinstitucional impediría dar respuesta a las necesidades complejas de las personas atendidas en su domicilio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977afe") }, {"long_answer": "El Plan establece como objetivo que antes de 2026 el 100% de las Comunidades Autónomas tengan implantado un sistema que permita identificar a los pacientes en situación de vulnerabilidad, de forma que los equipos de Atención Primaria puedan adaptar la atención y priorizar a quienes tienen más riesgo por motivos sociales, económicos o de salud. Esta identificación es clave para avanzar en equidad. Los porcentajes del 80%, el 60% y el 50% no se corresponden con la meta, que alcanza a todas las comunidades."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b05") }, {"long_answer": "En la optimización de la terapia farmacológica de los pacientes polimedicados, los farmacéuticos de Atención Primaria revisan los regímenes farmacoterapéuticos para detectar interacciones, duplicidades o medicamentos inadecuados, resuelven dudas de los profesionales sanitarios y se coordinan con las farmacias comunitarias para el seguimiento del paciente. Su papel no se reduce a dispensar medicamentos con receta, no administran tratamientos sin supervisión médica y no realizan solo funciones administrativas sin contacto con la actividad clínica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b07") }, {"long_answer": "El Plan fija como resultado esperado para 2027 un incremento del 30% en el número de Comunidades Autónomas con modelos de coordinación farmacoterapéutica centrados en la Atención Primaria, que integran la actuación de médicos, enfermeras, farmacéuticos de Atención Primaria y farmacias comunitarias en el seguimiento de los tratamientos. Disminuir la coordinación, mantener las cifras actuales sin cambios o reducir la participación de la farmacia comunitaria iría en contra de este objetivo de mejora del uso de los medicamentos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b0b") }, {"long_answer": "Las reformas de la regulación de medicamentos incluidas en el Plan de Recuperación, Transformación y Resiliencia se centran en incrementar la competencia, por ejemplo favoreciendo genéricos y biosimilares, y en facilitar el acceso a nuevos tratamientos, junto con la sostenibilidad del sistema y la racionalización del consumo de medicamentos. No buscan reducir la inversión pública en I+D, eliminar la financiación privada del sector ni fomentar exclusivamente la industria de genéricos, ya que la Estrategia pretende equilibrar innovación, acceso y sostenibilidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b0c") }, {"long_answer": "La Estrategia de la Industria Farmacéutica se articula en torno a ejes básicos que son la investigación y la innovación, la autonomía industrial o estratégica, el acceso de los pacientes a los medicamentos y la sostenibilidad del Sistema Nacional de Salud. Estos ejes reflejan el equilibrio entre el desarrollo del sector y el interés sanitario. Las demás opciones mezclan objetivos parciales o ajenos a la Estrategia, como la reducción de costes como eje, la eliminación de los genéricos o la homologación internacional, que no constituyen sus ejes vertebradores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b0d") }, {"long_answer": "El Ministerio de Cultura y Deporte no forma parte del Comité Interministerial que gobierna la Estrategia de la Industria Farmacéutica, ya que sus competencias no guardan relación con el sector del medicamento. El Comité, presidido por el Ministerio de Sanidad, cuenta con vocalías de los ministerios con competencias relacionadas con el sector, como Hacienda, por su papel en el gasto y la fijación de precios, Ciencia, Innovación y Universidades, por la investigación, e Industria y Turismo, por la política industrial y la capacidad productiva."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b0e") }, {"long_answer": "Según la Estrategia, la Secretaría de Estado de Sanidad coordina la gobernanza interministerial y se encarga del seguimiento y la evaluación de la Estrategia y de sus actuaciones, actuando como impulsora técnica del Comité Interministerial. No toma por sí sola las decisiones finales sobre el precio de los medicamentos, que siguen su propio procedimiento, ni gestiona exclusivamente la financiación externa y privada, y mucho menos ejecuta actividades comerciales o de marketing de la industria, que son ajenas a una administración pública."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b18") }, {"long_answer": "Tras la creación del nuevo sistema de evaluación, la resolución final sobre la financiación y el precio de los medicamentos seguirá correspondiendo al Ministerio de Sanidad, previo acuerdo de la Comisión Interministerial de Precios de los Medicamentos (CIPM), en la que participan otros ministerios y representantes de las Comunidades Autónomas. El nuevo sistema refuerza la evaluación técnica, pero no traslada la decisión al Ministerio de Hacienda sin intervención sanitaria, ni a organizaciones privadas, ni a las propias compañías farmacéuticas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b19") }, {"long_answer": "Dentro del sistema de evaluación y financiación, la Comisión Delegada del Gobierno para Asuntos Económicos (CDGAE) se encarga de aprobar las directrices de evaluación y las reglas aplicables a la prestación farmacéutica, a propuesta conjunta de los ministerios de Sanidad y de Hacienda, dada la repercusión económica de estas decisiones. No evalúa los aspectos científicos de los medicamentos, que corresponden a organismos técnicos, no realiza compras centralizadas y tampoco expide licencias de producción, que son competencia de la autoridad sanitaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b1f") }, {"long_answer": "La Estrategia plantea analizar el gasto farmacéutico al menos una vez al año, para conocer su evolución y las causas de su crecimiento y poder adoptar medidas a tiempo si se aleja de la tasa de referencia. Un análisis solo una vez por legislatura o cada cinco años sería demasiado espaciado para detectar desviaciones, y realizarlo solo cuando el gasto supere el presupuesto inicial impediría anticiparse a los problemas, que es precisamente lo que pretende el seguimiento periódico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b21") }, {"long_answer": "Para evitar que el sistema farmacéutico se oriente únicamente por la oferta tecnológica de la industria, la Estrategia propone que las necesidades de salud de la población se expresen de forma pública, continua y estructurada, de manera que guíen las prioridades de investigación, desarrollo y financiación. Invertir exclusivamente en empresas privadas, producir solo en el ámbito local sin influencia externa o centrarse únicamente en reducir costes sin considerar las necesidades no responde a este objetivo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b22") }, {"long_answer": "La Estrategia considera prioritaria la inversión en cronicidad por el impacto global creciente de las enfermedades crónicas en la salud pública, ligado al envejecimiento de la población y a la multimorbilidad, y por los elevados costes asociados a su manejo a lo largo de muchos años. Estas enfermedades no son de baja prevalencia, sino muy frecuentes, y la prioridad no se justifica por la facilidad para estudiar enfermedades infecciosas ni por un supuesto ahorro derivado del tratamiento de las enfermedades agudas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b23") }, {"long_answer": "Dentro de la Estrategia de la Industria Farmacéutica, la autonomía estratégica busca garantizar una cadena de suministro de medicamentos resiliente, sólida y ecosostenible, reduciendo la dependencia exterior en materias primas y principios activos que puso de manifiesto la pandemia de COVID-19. No pretende reducir la diversidad de actores de la industria, fomentar exclusividades comerciales sin competencia ni centralizar toda la producción en el sector público, sino reforzar las capacidades productivas en España y en Europa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b2d") }, {"long_answer": "Según los datos de la Estrategia, el 98,20% del gasto público en medicamentos y productos sanitarios en 2023 correspondió a las Comunidades Autónomas, ya que son ellas las que gestionan la asistencia sanitaria, incluida la prestación farmacéutica en farmacias y hospitales, tras el traspaso de competencias. El resto corresponde a otras administraciones como las mutualidades o el Estado. Los porcentajes del 75%, el 60% y el 85% infravaloran el peso que tienen las comunidades en este gasto según el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b30") }, {"long_answer": "La Estrategia incluye una línea de acción dirigida a completar la incorporación de biomarcadores y pruebas genéticas a la cartera de servicios, para que la medicina personalizada de precisión llegue a todos los pacientes en condiciones de equidad y los tratamientos dirigidos puedan utilizarse con el diagnóstico molecular adecuado. Impulsar la producción local de genéricos, establecer un sistema nacional de distribución o crear centros exclusivos para terapias avanzadas son actuaciones distintas que no se refieren a la incorporación de biomarcadores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b39") }, {"long_answer": "El Plan para fomentar el uso de medicamentos genéricos y biosimilares busca mejorar el acceso de la población a los tratamientos y contribuir a la sostenibilidad del sistema sanitario, ya que estos medicamentos tienen la misma eficacia y seguridad que los de referencia a un precio menor, lo que libera recursos para financiar la innovación. Disminuir el uso de genéricos, excluir los biosimilares o concentrar la producción en medicamentos originales sería contrario a este plan y aumentaría el gasto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b3b") }, {"long_answer": "El Programa PROFARMA, impulsado por la Administración General del Estado, evalúa y clasifica a las compañías farmacéuticas según su actividad industrial, su inversión en I+D y su contribución a la economía, y su reconocimiento tiene efectos en aspectos como la fiscalidad. Por ello la Estrategia lo vincula a optimizar la fiscalidad y el reconocimiento del sector. No regula la producción de vacunas de ARN mensajero, no coordina exclusivamente las cadenas de suministro de genéricos y no pretende reducir la inversión en investigación básica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b3c") }, {"long_answer": "En materia de financiación y desarrollo, la Estrategia busca estimular el uso y el desarrollo de herramientas financieras especializadas en biomedicina, como fondos de capital riesgo, préstamos o instrumentos público-privados, que permitan a las empresas innovadoras financiar las largas y costosas fases de desarrollo de medicamentos. Excluir al sector privado de la I+D+i, reducir el número de proyectos para ahorrar costes o centralizar todos los recursos en investigación clínica son medidas contrarias a lo que plantea la Estrategia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b3f") }, {"long_answer": "Según los datos recogidos en la Estrategia, la industria farmacéutica española invirtió en 2022 alrededor de 1.400 millones de euros en investigación y desarrollo, lo que la sitúa como uno de los sectores industriales con mayor inversión en I+D del país. Una parte importante de esta cantidad se destina a investigación clínica, es decir, a ensayos clínicos. Las cifras de 500 y 800 millones de euros infravaloran esta inversión, mientras que 5.000 millones de euros la sobreestima claramente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b46") }, {"long_answer": "La Estrategia considera esencial una gobernanza integral que una la acción pública y la privada, implicando a los distintos ministerios, a las Comunidades Autónomas y a la industria, para que el sector farmacéutico contribuya a la competitividad y al desarrollo económico del país sin perder de vista el interés sanitario. Reducir la acción pública a una regulación básica, limitar la innovación para evitar riesgos o externalizar completamente la producción debilitaría tanto la competitividad como la autonomía estratégica que persigue la Estrategia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b52") }, {"long_answer": "La Estrategia prevé crear fórmulas regulatorias que permitan reconocer nuevas indicaciones de medicamentos que ya están fuera del periodo de protección sin que ello penalice su precio de financiación, para incentivar que se investiguen y se incorporen a la ficha técnica usos que ya se aplican o que tienen evidencia. Penalizar automáticamente el precio desincentivaría esa investigación, y no se plantea impedir la inclusión de indicaciones en la ficha técnica ni limitar la financiación a solicitudes de laboratorios sin ánimo de lucro."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b54") }, {"long_answer": "La reforma de la financiación pública en I+D recogida en la Estrategia, alineada con la Ley de la Ciencia, tiene como objetivo que la financiación pública en investigación y desarrollo alcance el 1,25% del PIB en 2030, con un crecimiento progresivo y estable de los recursos. Mantenerla en un 0,5% del PIB supondría un nivel muy inferior al objetivo, la meta no se refiere a que la financiación privada alcance el 5% del PIB y tampoco se plantea reducir la financiación pública para favorecer la iniciativa privada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b64") }, {"long_answer": "La Estrategia prevé publicar guías técnicas metodológicas sobre evaluación económica y beneficio clínico para que sirvan de referencia común en los análisis económicos, en la valoración del valor terapéutico añadido y en la negociación de precios, con criterios claros, transparentes y a la vez flexibles. Estas guías no eliminan la necesidad de evaluar antes de financiar, sino que la refuerzan, no trasladan la aprobación de medicamentos a organismos europeos y no dejan la evaluación en manos exclusivas de expertos privados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b67") }, {"long_answer": "La Estrategia considera la colaboración público-privada fundamental para el avance de la I+D+i biomédica, porque permite acelerar el desarrollo de innovaciones y aprovechar de forma conjunta los recursos, las infraestructuras y el conocimiento de los centros públicos y de las empresas. Por ello no la considera un obstáculo para la eficiencia o la equidad, ni la limita a proyectos preclínicos, ya que también es esencial en los ensayos clínicos, ni propone evitarla en nombre de la independencia científica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b70") }, {"long_answer": "Para fomentar la colaboración entre los Organismos Públicos de Investigación, el sector académico y la industria farmacéutica, la Estrategia propone planes de matching, es decir, encuentros y herramientas para que los distintos agentes se conozcan mejor, identifiquen intereses comunes y faciliten la transferencia de conocimiento hacia proyectos de desarrollo. La exclusividad industrial sin acceso público, la reducción de proyectos conjuntos o la externalización completa de la investigación académica al sector privado irían en contra de esta colaboración equilibrada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b75") }, {"long_answer": "La futura Ley de Industria se plantea como un instrumento para promover ecosistemas industriales, favorecer la internacionalización de las empresas y proteger la base industrial estratégica del país, en la que se incluye el sector farmacéutico por su importancia para la autonomía sanitaria. No pretende privatizar el sector sanitario público, eliminar las ayudas financieras al sector ni reducir la inversión en tecnologías farmacéuticas avanzadas, medidas que debilitarían precisamente la capacidad industrial que la ley busca reforzar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b77") }, {"long_answer": "ENISA, Empresa Nacional de Innovación, es una entidad pública que concede préstamos participativos para financiar proyectos innovadores y de crecimiento de pymes y startups, incluidas las del sector farmacéutico y biotecnológico. Su papel en la Estrategia es facilitar el acceso a financiación a empresas jóvenes con potencial innovador. No impone restricciones regulatorias, no se dedica a facilitar fusiones de grandes empresas y tampoco gestiona la propiedad intelectual de los medicamentos, que corresponde a otros organismos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b7e") }, {"long_answer": "La Mesa de Trabajo para el aumento de las capacidades productivas incluirá a las principales organizaciones empresariales del sector farmacéutico, con el objetivo de identificar los recursos estratégicos y las capacidades de fabricación disponibles en España y detectar dónde es necesario reforzarlas. Excluir a los socios privados, contar solo con organismos internacionales o limitarse a los laboratorios de genéricos impediría tener una visión completa del tejido productivo, que es lo que se busca con este espacio de colaboración."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b80") }, {"long_answer": "La Estrategia de Industria y Autonomía Industrial definirá los sectores estratégicos, los retos a los que se enfrentan y las transformaciones que se desean alcanzar en un periodo determinado, sirviendo de marco para orientar las políticas industriales, entre ellas las del sector farmacéutico. No contempla excluir al sector farmacéutico del plan industrial, cerrar fábricas nacionales sin alternativas ni limitarse a atraer inversión extranjera sin control, ya que su finalidad es reforzar la autonomía y la capacidad industrial del país."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b82") }, {"long_answer": "Las medidas para mejorar el acceso a instrumentos financieros en el sector farmacéutico buscan mejorar la coordinación interna entre los organismos públicos que los gestionan y facilitar la financiación a startups y pymes, que son las que más dificultades tienen para financiar el desarrollo de sus innovaciones. Incrementar las barreras de acceso, concentrar los recursos solo en las grandes empresas o limitar el acceso a la financiación pública sería contrario al objetivo de impulsar la innovación en todo el tejido empresarial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b83") }, {"long_answer": "La Estrategia orientada a la regulación y a la autonomía estratégica busca crear un marco regulador que apoye la investigación y el desarrollo de tecnologías sanitarias y que permita que los avances lleguen a los pacientes de forma segura y ágil. Reducir la regulación para producir sin control comprometería la calidad y la seguridad, desentenderse de la innovación sanitaria en favor de lo comercial contradice el interés público, y fomentar exclusivamente la importación de medicamentos aumentaría la dependencia exterior que se quiere reducir.", "option_1": "Crear un marco regulador de apoyo a la investigación y a las tecnologías sanitarias que permita que lleguen a los pacientes"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b89") }, {"long_answer": "El Plan de acción para la prevención del suicidio señala que la conducta suicida no puede considerarse propiamente una enfermedad, sino una manifestación de un sufrimiento emocional profundo, en la que influyen factores psicológicos, sociales, biológicos y ambientales. Aunque se asocia con frecuencia a trastornos mentales, también puede darse en personas sin ellos, por lo que es falso que ocurra solo en personas sin enfermedad mental. No presenta siempre síntomas físicos claros y no se diagnostica únicamente en hospitales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b8f") }, {"long_answer": "En las personas mayores, la soledad no deseada y las pérdidas significativas, como la viudedad, la pérdida de autonomía, de salud o de roles sociales, son factores que aumentan el riesgo de suicidio, sobre todo cuando se acompañan de dolor crónico, dependencia o depresión. Por el contrario, la participación en grupos sociales activos actúa como factor protector, al igual que una buena salud física sin enfermedades crónicas. Un alto nivel educativo no se considera un factor que aumente el riesgo de suicidio en este grupo de edad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b92") }, {"long_answer": "Los familiares y personas allegadas tienen un papel clave en la prevención y el acompañamiento de la conducta suicida, por lo que el Plan recomienda que reciban formación para ofrecer apoyo emocional, reconocer las señales de alerta y disponer de un plan claro sobre cómo y dónde pedir ayuda en caso de crisis. Limitarse a dar información científica sin apoyo emocional, evitar la cercanía con la persona afectada o reducir su papel a los cuidados físicos no responde a las necesidades de quien está en riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b98") }, {"long_answer": "Uno de los objetivos del Plan de acción para la prevención del suicidio es mejorar la disponibilidad, la oportunidad y la calidad de la información sobre la conducta suicida, para conocer su magnitud real, identificar grupos de riesgo y planificar intervenciones eficaces. La desinformación, la reducción de la conciencia pública o el secretismo en torno a los pacientes con conducta suicida aumentan el estigma y dificultan la prevención, por lo que son contrarios a los objetivos del Plan, que promueve hablar del suicidio de forma responsable."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b9f") }, {"long_answer": "La prevención del suicidio requiere un enfoque multisectorial porque el suicidio es un fenómeno complejo en el que intervienen factores sanitarios, sociales, económicos, educativos y culturales, de modo que ningún sector por sí solo puede abordarlo. Por eso el Plan implica a sanidad, servicios sociales, educación, empleo, justicia, medios de comunicación y ciudadanía. La implicación de varios sectores no tiene como fin aumentar la burocracia ni limitar la participación ciudadana, y es falso que solo el sector salud pueda intervenir eficazmente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977baa") }, {"long_answer": "En niños menores de 2 meses, la guía recomienda realizar la antisepsia de la piel con clorhexidina al 2% en solución acuosa, dejándola secar completamente durante 3 a 5 minutos antes de la punción, ya que en esta edad la piel es más inmadura y permeable y los preparados alcohólicos aumentan el riesgo de irritación y quemaduras químicas. No se emplea la clorhexidina alcohólica como en adultos, la povidona yodada debe dejarse secar y no es la opción indicada en esta edad, y prescindir de la antisepsia aumentaría la contaminación de las muestras."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bac") }, {"long_answer": "Una vez realizada la antisepsia, no se debe volver a palpar el punto de punción, porque se contaminaría la zona y aumentaría el riesgo de falsos positivos en el hemocultivo. Si es imprescindible palpar, se debe utilizar un guante estéril nuevo o volver a desinfectar la piel antes de pinchar. Palpar con un guante ya usado sin desinfectar, hacerlo de forma sistemática para localizar mejor la vena o palpar sin guantes son prácticas incorrectas que comprometen la asepsia de la extracción."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bbd") }, {"long_answer": "Cuando se utiliza un sistema de extracción con vacío, se recomienda llenar primero el frasco aerobio, porque el aire que contiene el tubo de la palomilla pasaría al primer frasco y, si este fuese el anaerobio, se alteraría el ambiente necesario para el crecimiento de las bacterias anaerobias. Llenar primero el anaerobio solo se recomienda cuando la extracción se realiza con jeringa. El orden sí importa, por lo que no deben llenarse simultáneamente ni elegirse según las bacterias que se esperan encontrar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bbf") }, {"long_answer": "Al retirar la aguja tras la extracción de hemocultivos, la guía sugiere no colocar algodón ni otros materiales no estériles sobre la aguja en ese momento, porque podrían contaminar la muestra si todavía queda sangre por transferir a los frascos o si la aguja entra en contacto con ellos. La compresión del punto de punción debe hacerse después, con material adecuado. No es correcto considerar que ocluir con una gasa sea una práctica sin riesgo, ni que dependa del tamaño de la aguja o de que la extracción sea pediátrica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bc2") }, {"long_answer": "Dentro del laboratorio, el mejor método de almacenaje de los hemocultivos son los equipos automatizados de incubación y lectura continua, incluidos los equipos satélite cuando el laboratorio principal no está disponible de forma inmediata, ya que permiten incubar las muestras sin demora y detectar precozmente el crecimiento bacteriano. Los hemocultivos no deben refrigerarse a 4 ºC, porque se reduce la viabilidad de algunos microorganismos. Las estufas convencionales sin automatización y las cámaras anaerobias no son el método recomendado para su conservación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bc4") }, {"long_answer": "Un buen registro enfermero tras la extracción de hemocultivos debe incluir el nombre completo del paciente, la fecha, el número de historia clínica, la hora de la toma y el número de secuencia de las muestras, porque estos datos permiten identificar correctamente cada frasco e interpretar los resultados, por ejemplo al distinguir una bacteriemia verdadera de una contaminación. Registrar solo el nombre y la fecha resulta insuficiente, la hora y los síntomas no identifican al paciente y los datos del laboratorio o del médico solicitante no sustituyen a la identificación de las muestras."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bc5") }, {"long_answer": "Explicar al paciente la técnica y la finalidad del hemocultivo mejora su colaboración y su comprensión del procedimiento, reduce la ansiedad y favorece que permanezca quieto durante la extracción, lo que aumenta la seguridad y facilita mantener la técnica aséptica. La información no acorta necesariamente el procedimiento, no exime del uso de guantes ni de las medidas de asepsia y tampoco sustituye al consentimiento del paciente, sino que forma parte de él y del respeto a su autonomía."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bc7") }, {"long_answer": "Según el Plan Nacional contra el Radón, la presidencia del Comité encargado de su coordinación y seguimiento corresponde al Ministerio de Sanidad, en coherencia con el enfoque de protección de la salud pública del Plan, ya que la exposición al radón en interiores es la segunda causa de cáncer de pulmón tras el tabaco. El Consejo de Seguridad Nuclear, el Ministerio para la Transición Ecológica y el Reto Demográfico y la Federación Española de Municipios y Provincias tienen competencias relacionadas con la protección radiológica, el territorio o la gestión local, pero no ocupan la presidencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bc8") }, {"long_answer": "De las fuentes naturales de radiación ionizante, la más relevante para la población general es el radón y sus descendientes, que suponen aproximadamente la mitad de la dosis media que recibe una persona. El radón es un gas que procede del uranio presente en el terreno y se acumula en el interior de los edificios, donde se inhala. La radiación cósmica, la radiación gamma exterior procedente del suelo y la radiación de los materiales de construcción contribuyen a la dosis, pero en una proporción claramente inferior."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bc9") }, {"long_answer": "El tabaquismo potencia de forma sinérgica el riesgo de cáncer de pulmón asociado a la exposición al radón, de modo que el riesgo de una persona fumadora expuesta es mucho mayor que la simple suma de ambos riesgos por separado. Por eso la mayoría de los cánceres de pulmón atribuibles al radón se producen en fumadores y exfumadores, y el Plan recomienda combinar la reducción de la exposición con la prevención del tabaquismo. Es falso que el tabaco no influya, que disminuya el efecto del radón o que eleve el umbral de riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bcd") }, {"long_answer": "El radón 222 es un gas noble radiactivo de origen natural, incoloro, inodoro e insípido, que procede de la desintegración del radio 226 en la cadena del uranio y es moderadamente soluble en agua, por lo que también puede encontrarse en aguas subterráneas. Al no tener color ni olor no puede detectarse con los sentidos y su presencia solo se conoce mediante mediciones, lo que justifica las campañas de medida en viviendas y lugares de trabajo. Por ello son incorrectas las opciones que lo describen como coloreado o con olor."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bdf") }, {"long_answer": "La reglamentación vigente sobre protección frente a la radiación natural, incorporada al ordenamiento español a partir de la Directiva 2013/59/Euratom, establece para la exposición externa a radiación gamma procedente de materiales de construcción en recintos cerrados un nivel de referencia de 1 mSv al año adicional a la exposición exterior. La cifra de 300 Bq/m³ corresponde al nivel de referencia de concentración de radón en el aire interior, no a la radiación gamma. Los valores de 6 y 10 mSv al año no son los establecidos para los materiales de construcción."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977be4") }, {"long_answer": "A nivel mundial, la principal razón por la que las enfermedades bucodentales no se tratan en etapas tempranas es que el tratamiento no es asequible para gran parte de la población y no está cubierto por la mayoría de los sistemas sanitarios, lo que retrasa la consulta hasta que aparecen dolor o complicaciones. Las enfermedades bucodentales, como la caries o la enfermedad periodontal, son de las más prevalentes del mundo, la caries inicial puede diagnosticarse sin gran dificultad técnica y el problema no es la falta de interés de los profesionales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977be7") }, {"long_answer": "Según el Plan de ampliación de la cartera de salud bucodental, el modelo mayoritario en las Comunidades Autónomas para la asistencia bucodental infantil es el modelo mixto, en el que la atención básica se presta tanto con medios públicos como mediante dentistas privados habilitados y financiados por el sistema, como ocurre en los programas tipo PADI. El modelo exclusivamente público existe en algunas comunidades, pero no es el mayoritario. El modelo de reintegro de gastos o el puramente privado sin financiación pública no son los predominantes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bee") }, {"long_answer": "La valoración económica del Plan de ampliación de la cartera común de servicios de salud bucodental estima un gasto total de 45.585.460 euros para homogeneizar y ampliar la cartera en todo el SNS, sumando el coste de las distintas prestaciones y grupos de población priorizados. Las cifras de 30.860.737, 8.406.463 y 686.332 euros son inferiores al total y pueden corresponder a partidas parciales o a colectivos concretos, pero no al gasto global estimado para la ampliación.", "option_1": "45.585.460 euros", "option_2": "30.860.737 euros", "option_3": "686.332 euros", "option_4": "8.406.463 euros"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bf0") }, {"long_answer": "En el modelo de provisión mixta de la atención bucodental infantil, la atención básica se retribuye mediante pago por capitación, es decir, una cantidad fija anual por cada niño asignado al dentista, con independencia de los actos que se le realicen, lo que incentiva la prevención. El pago por acto se reserva habitualmente para tratamientos especiales o complejos no incluidos en la atención básica. El pago a tanto alzado sin relación con el número de pacientes y el pago único anual fijo por dentista no son los mecanismos utilizados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bf6") }, {"long_answer": "Para medir la cobertura en la población infantojuvenil se utiliza el número de niños atendidos en relación con la población diana, es decir, el porcentaje de niños y adolescentes con derecho a la prestación que efectivamente la han recibido. Este indicador refleja el grado de acceso real al servicio. El número total de citas o de tratamientos de ortodoncia completados mide actividad, no cobertura, y el número de dentistas públicos contratados es un indicador de recursos, no de la población atendida.", "option_4": "Número de dentistas públicos contratados"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bf7") }, {"long_answer": "La ampliación de la cartera común de servicios de salud bucodental prioriza a la población infantojuvenil de 0 a 14 años inclusive, a la que se ofrecen actuaciones preventivas, como selladores y aplicaciones de flúor, y tratamientos de la caries y de otros problemas de la dentición. Este grupo de edad se prioriza porque las intervenciones tempranas son más eficaces y evitan problemas en la edad adulta. Los rangos de 0 a 17 años, de 6 a 15 años y de 4 a 12 años no coinciden con la población priorizada en el Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bf8") }, {"long_answer": "El plan de ampliación de la cartera de salud bucodental recomienda que la visita odontológica de la mujer embarazada se realice preferentemente durante el primer trimestre, para poder valorar el estado de salud oral, dar educación sanitaria precoz y tratar a tiempo los problemas que el embarazo puede agravar, como la gingivitis gestacional. Limitarla al tercer trimestre retrasa la prevención y coincide con la etapa de mayor incomodidad para la gestante. El momento del parto no es un contexto adecuado para una revisión dental. Tampoco es cierto que se desaconseje la atención odontológica en el embarazo: al contrario, la gestante es uno de los grupos prioritarios de la cartera común."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bf9") }, {"long_answer": "Para estimar el impacto presupuestario de incluir a las personas con enfermedades neuromusculares en la cartera bucodental, el plan utiliza una prevalencia estimada en adultos del 0,12%, un valor coherente con que se trate de un conjunto de enfermedades raras o poco frecuentes de base genética o adquirida. Cifras como el 0,5%, el 1,5% o el 5% sobrestimarían de forma notable la población afectada, propia de enfermedades frecuentes, y no corresponden al dato utilizado por el documento para calcular el número de personas beneficiarias y el coste de la ampliación de la cartera en este grupo prioritario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bfc") }, {"long_answer": "El Grupo de Trabajo de Salud Bucodental se constituyó en 2021 en el seno del Consejo Interterritorial con el objetivo de definir una cartera común de servicios de salud bucodental homogénea y equitativa para los grupos prioritarios (población infantil y juvenil, embarazadas, personas con discapacidad, personas con procesos oncológicos de cabeza y cuello, entre otros), reduciendo las desigualdades entre comunidades autónomas. No pretendía impulsar un sistema privado de atención dental, sino reforzar la prestación pública. Tampoco su finalidad era recortar el gasto ni eliminar las carteras complementarias autonómicas, que pueden seguir existiendo por encima de la cartera común."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bfd") }, {"long_answer": "El análisis internacional incluido en el plan muestra que Suecia ofrece una cobertura pública prácticamente universal y gratuita de la atención bucodental para la población infantil y juvenil, con un modelo consolidado de odontología pública preventiva, lo que la sitúa como referente europeo. España, por el contrario, ha tenido históricamente una cobertura pública limitada y desigual entre comunidades, motivo precisamente del plan de ampliación. Italia y Grecia presentan modelos con mucha mayor dependencia del gasto privado y del pago directo por parte de las familias, por lo que no destacan por su cobertura universal en la infancia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bff") }, {"long_answer": "Para evaluar la efectividad de las medidas dirigidas a la gestante, el plan propone un indicador de cobertura: el número de embarazadas atendidas en las unidades de salud bucodental dividido entre la estimación de la población de embarazadas. Así se mide qué proporción de la población diana accede realmente a la prestación. Los implantes y las prótesis dentales no forman parte de la cartera de la embarazada, que se centra en la valoración, la educación sanitaria y el tratamiento preventivo y básico, por lo que no sirven como indicador. El número de urgencias odontológicas mide actividad asistencial aguda, pero no la cobertura del programa preventivo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c06") }, {"long_answer": "La concentración de radón en el interior de los edificios depende principalmente del contenido en uranio 238 del sustrato geológico, ya que el radón 222 es un gas radiactivo que procede de la cadena de desintegración de este elemento. Por eso las zonas con rocas graníticas, ricas en uranio, presentan los niveles más altos. El plomo no genera radón: de hecho, es uno de los productos finales estables de la cadena. El tipo de roca superficial influye solo en la medida en que contiene uranio y condiciona la permeabilidad, y el agua subterránea puede transportar radón, pero ninguno de estos dos es el factor determinante principal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c0e") }, {"option_3": "Existe un efecto sinérgico (submultiplicativo) que incrementa significativamente el riesgo en fumadores", "long_answer": "El Libro del Radón recoge que entre el tabaco y la exposición a radón existe un efecto sinérgico de tipo submultiplicativo: el riesgo combinado es mayor que la suma de ambos riesgos, aunque algo menor que su producto. Esto hace que en los fumadores la exposición a radón incremente de forma muy importante el riesgo absoluto de cáncer de pulmón, y que la mayor parte de los cánceres atribuibles al radón se produzcan en fumadores o exfumadores. Es falso que no exista interacción, que el radón afecte solo a no fumadores (en quienes es la primera causa de cáncer de pulmón, pero no la única población afectada) o que reduzca el riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c12") }, {"long_answer": "Galicia es la comunidad autónoma con mayor porcentaje de su territorio clasificado como zona de actuación prioritaria por radón, debido a la abundancia de rocas graníticas ricas en uranio en su sustrato geológico. Le siguen en importancia otras zonas con sustrato granítico como áreas de Extremadura, de Castilla y León o de la sierra de Madrid, pero en proporción de territorio afectado ninguna alcanza a Galicia. Madrid y Extremadura tienen zonas concretas con niveles elevados, sin llegar a esa extensión, y Cataluña presenta un porcentaje de territorio afectado mucho menor."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c19") }, {"question": "Según la consulta a expertos recogida en el Libro del Radón, ¿cuál es la situación en la Unión Europea respecto a los protocolos de vigilancia sanitaria de los trabajadores expuestos a radón?", "long_answer": "La consulta a expertos realizada para el Libro del Radón puso de manifiesto que en la Unión Europea no existe ningún protocolo específico y obligatorio de vigilancia sanitaria para los trabajadores expuestos a radón; las actuaciones se centran en la medición, la reducción de la exposición y la protección radiológica, y la vigilancia de la salud se aplica de forma heterogénea. Por tanto, no hay un protocolo común europeo obligatorio. Tampoco se recomienda aumentar la frecuencia de radiografías de tórax, que no son útiles como cribado y suponen radiación adicional, ni se aplica sin más el protocolo de los trabajadores expuestos a radiaciones en instalaciones nucleares."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c1c") }, {"long_answer": "En trabajadores expuestos a radón que fuman, la medida de prevención primaria más eficaz es la deshabituación tabáquica, facilitada por los empleadores y mediante programas específicos, porque el tabaco y el radón actúan de forma sinérgica sobre el riesgo de cáncer de pulmón y abandonar el tabaco reduce de forma muy importante ese riesgo combinado. Las mascarillas no son la medida de elección frente a un gas presente en el ambiente; la prioridad es reducir la concentración de radón en el lugar de trabajo. La tomografía de baja dosis es una medida de cribado, es decir, de prevención secundaria, y la reducción de jornada no es la recomendación principal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c1f") }, {"long_answer": "La revisión sistemática del Libro del Radón no identificó ningún estudio que evaluara los beneficios o los riesgos de programas de vigilancia sanitaria o de cribado específicos para trabajadores expuestos a radón; las recomendaciones se basan, por tanto, en la extrapolación de la evidencia sobre cribado de cáncer de pulmón en población de alto riesgo y en el consenso de expertos. No es cierto que exista abundante evidencia a favor de un cribado anual, ni que haya estudios contradictorios que impidan recomendar, ni que se haya demostrado un beneficio específico en exfumadores: simplemente, la evidencia directa en este colectivo no existe."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c25") }, {"long_answer": "El documento propone que la vigilancia específica de síntomas y signos precoces de cáncer de pulmón en trabajadores expuestos a radón la realicen neumólogos y personal facultativo con entrenamiento específico, ya que requiere interpretar de forma experta la clínica, las pruebas de imagen y los hallazgos sospechosos, y decidir el circuito diagnóstico. La enfermería general colabora en la educación sanitaria, la deshabituación tabáquica y el seguimiento, pero no es la responsable de esta vigilancia clínica especializada. Tampoco se propone que la asuman médicos sin formación específica en este riesgo, ni los técnicos en radiología, cuya función es la realización técnica de las pruebas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c2a") }, {"long_answer": "La desfibrilación de doble secuencia está indicada en la parada cardiorrespiratoria con ritmo desfibrilable (fibrilación ventricular o taquicardia ventricular sin pulso) que persiste o es refractaria tras tres desfibrilaciones estándar correctamente realizadas. En estos casos se utilizan dos monitores desfibriladores para administrar dos descargas casi consecutivas con distinto vector. No está indicada en cualquier parada ni en los ritmos no desfibrilables (asistolia o actividad eléctrica sin pulso), en los que la descarga no aporta beneficio. Además, precisa disponer de dos monitores desfibriladores, por lo que no puede plantearse cuando no se dispone de ellos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c2b") }, {"long_answer": "En la desfibrilación de doble secuencia las dos descargas deben administrarse de forma secuencial y muy próxima, con un intervalo inferior a un segundo entre ambas, de manera que actúen sobre el miocardio prácticamente en el mismo periodo refractario y con dos vectores distintos. Intervalos de tres o cinco segundos ya no se consideran doble secuencia, sino dos descargas independientes, y pierden el efecto buscado. Esperar dos minutos correspondería al intervalo habitual entre ciclos de RCP y análisis del ritmo, no al tiempo entre las dos descargas de la técnica. Tampoco se recomienda la descarga exactamente simultánea por el riesgo de dañar los equipos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c2e") }, {"long_answer": "Durante las tres primeras desfibrilaciones estándar se utiliza la posición anterolateral habitual: un parche bajo la clavícula derecha, a la derecha del esternón, y el otro en la línea axilar del lado izquierdo a la altura del quinto espacio intercostal, sobre el ápex cardíaco. Así la corriente atraviesa la mayor masa ventricular posible. Si la fibrilación persiste, en la doble secuencia se añade un segundo juego de parches en posición anteroposterior. Colocar un electrodo en la espalda baja, en las extremidades o en la línea media esternal y lateral derecha no sitúa el corazón entre ambos parches y reduce la eficacia de la descarga."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c32") }, {"long_answer": "El protocolo establece que una sola persona maneje ambos monitores desfibriladores y realice las dos descargas de forma secuencial. De este modo se controla mejor el intervalo entre descargas, que debe ser inferior a un segundo, se evitan descoordinaciones y se garantiza la seguridad del resto del equipo, que debe estar separado del paciente. Que dos personas pulsen cada una un monitor dificulta la sincronización y aumenta el riesgo de error. No es una función reservada exclusivamente al médico, sino a la persona del equipo designada y entrenada, y tampoco corresponde al personal de soporte vital básico, ya que exige manejo de monitores manuales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c37") }, {"long_answer": "La persona que maneja los desfibriladores debe anunciar en voz alta la doble descarga para asegurar que nadie toca al paciente, pulsar el primer monitor y, a continuación, anunciar y pulsar el segundo, con una diferencia aproximada de un segundo. Esta secuencia combina seguridad y eficacia. Esperar diez segundos entre descargas anula el efecto de la doble secuencia. Pulsar ambos de forma estrictamente simultánea no es lo recomendado, porque puede dañar los equipos y no es lo que define la técnica secuencial. Nunca debe omitirse el aviso previo, ya que es una medida esencial de seguridad para el equipo que atiende la parada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c39") }, {"long_answer": "Comunicar la parada cardiorrespiratoria a la Central de Comunicaciones antes de plantear la doble secuencia permite activar precozmente los recursos necesarios para disponer de un segundo monitor desfibrilador, que suele llegar con otra unidad asistencial, ya que la técnica exige dos equipos. Si no se solicita a tiempo, cuando la fibrilación resulte refractaria no habrá segundo monitor disponible. No se trata de pedir fármacos específicos, porque la técnica no los requiere, ni de comunicar datos estadísticos, que pueden registrarse después. Tampoco hace falta una autorización médica para administrar descargas múltiples, ya que la indicación está protocolizada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c48") }, {"long_answer": "El objetivo de la inmunización con nirsevimab es prevenir la enfermedad de las vías respiratorias inferiores causada por el virus respiratorio sincitial en neonatos y lactantes durante su primera temporada de VRS, y en determinados niños con factores de riesgo hasta su segunda temporada, reduciendo bronquiolitis, hospitalizaciones e ingresos en UCI. No está indicado en adultos mayores, para quienes existen vacunas específicas. Tampoco es un tratamiento de la bronquiolitis ya establecida, sino un anticuerpo monoclonal de uso profiláctico. Aunque pueda tener efectos indirectos, su finalidad no es reducir la transmisión comunitaria en la población general, sino proteger al lactante inmunizado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c4a") }, {"long_answer": "Las recomendaciones para la temporada 2024-2025 incluyen como población diana a los prematuros de menos de 35 semanas de edad gestacional, también los menores de 29 semanas, que deben recibir nirsevimab antes de cumplir los 12 meses de edad si no lo recibieron al nacer o al inicio de la temporada. Los prematuros de 35 semanas o más se inmunizan como el resto de lactantes según su fecha de nacimiento, no por su prematuridad. No se restringe a quienes tienen displasia broncopulmonar, que es otro grupo de riesgo independiente. Y la indicación no depende de haber nacido después de la temporada, sino de la edad gestacional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c4f") }, {"long_answer": "Durante la primera temporada de implantación, la 2023-2024, la cobertura de inmunización con nirsevimab en los recién nacidos durante la temporada alcanzó aproximadamente el 92%, una cifra muy elevada que se asoció a una reducción importante de las hospitalizaciones por VRS en menores de seis meses. Este dato sirvió de base para mantener y ampliar la estrategia en la temporada siguiente. Las cifras del 50% o del 75% infravaloran claramente la aceptación lograda. El 88% se aproxima, pero no es el dato de cobertura en recién nacidos durante la temporada que recoge el documento de actualización."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c54") }, {"long_answer": "En los lactantes nacidos durante la temporada de VRS, de octubre a marzo, se recomienda administrar nirsevimab de forma precoz, preferiblemente en las primeras 24 a 48 horas de vida, aprovechando la estancia en la maternidad, porque el riesgo de enfermedad grave es máximo en los primeros meses y en plena circulación del virus. Esperar a los seis meses los dejaría desprotegidos en el periodo más vulnerable. No administrarlo contradice la estrategia, ya que son precisamente la población diana prioritaria. Y como se trata de una medida preventiva, no debe reservarse para cuando aparezcan síntomas, momento en el que ya no evita la infección."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c57") }, {"long_answer": "La estrategia para la temporada 2024-2025 mantiene como medida principal la inmunización pasiva del lactante con nirsevimab, que se recomienda independientemente de que la madre haya recibido o no la vacuna frente al VRS durante el embarazo. La vacuna materna no se incluyó como estrategia poblacional del SNS en esa temporada, y por eso no se plantea sustituir la inmunización infantil por la vacunación de la gestante. Tampoco se recomienda la vacunación materna limitada a casos de alto riesgo como alternativa al anticuerpo monoclonal. Con ello se busca una protección homogénea de todos los lactantes de la población diana."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c5d") }, {"long_answer": "Los lactantes de la población diana nacidos fuera de la temporada de VRS, entre abril y septiembre, deben recibir nirsevimab al comienzo de la temporada, idealmente en octubre, de forma que tengan niveles protectores de anticuerpos durante todo el periodo de máxima circulación del virus. Esperar a que cumplan seis meses no tiene sentido, ya que la indicación se establece por la temporada y no por la edad. No administrarlo los dejaría sin protección en su primera temporada. Tampoco se limita a los que ingresan en UCI, porque el objetivo es precisamente prevenir esas formas graves de la enfermedad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c5f") }, {"long_answer": "Nirsevimab es un anticuerpo monoclonal de semivida prolongada, diseñado para que una única dosis proporcione protección durante al menos cinco meses, es decir, una temporada completa de VRS de otoño e invierno. Esta característica es la que permite administrarlo una sola vez al nacer o al inicio de la temporada. Una protección de solo un mes o de dos semanas correspondería a anticuerpos de semivida corta, como palivizumab, que requiere dosis mensuales. Una protección de dos años no es real: en los niños con riesgo que siguen siendo vulnerables en su segunda temporada se administra una nueva dosis antes de que comience."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c62") }, {"long_answer": "En la primera temporada de VRS la dosis de nirsevimab depende del peso: los lactantes de menos de 5 kg reciben 50 mg por vía intramuscular y los de 5 kg o más reciben 100 mg. Por tanto, un lactante de menos de 5 kg debe recibir 50 mg. La dosis de 100 mg corresponde a los lactantes de 5 kg o más en su primera temporada, o a los niños de menos de 10 kg en su segunda temporada. La de 200 mg, en dos inyecciones de 100 mg, es la de los niños de 10 kg o más en su segunda temporada. La dosis de 25 mg no está contemplada en las recomendaciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c63") }, {"question": "En un lactante en su primera temporada de VRS que se somete a cirugía cardíaca con circulación extracorpórea cuando han pasado más de 90 días desde que recibió nirsevimab, ¿qué dosis adicional se recomienda?", "long_answer": "Cuando un lactante en su primera temporada se somete a cirugía cardíaca con circulación extracorpórea, se pierde parte del anticuerpo circulante, por lo que se recomienda una dosis adicional en cuanto esté estable. Si han transcurrido más de 90 días desde la primera dosis, la dosis adicional es de 50 mg independientemente del peso, ya que los niveles residuales son menores y se busca completar la protección hasta el final de la temporada. Si la cirugía ocurre dentro de los 90 días, la dosis adicional se ajusta al peso (50 o 100 mg). La de 200 mg corresponde a la segunda temporada, y no administrar dosis adicional dejaría al lactante insuficientemente protegido."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c67") }, {"long_answer": "El Marco Estratégico para los Cuidados de Enfermería 2025-2027 adopta un concepto amplio de cuidado profesional: el conjunto de actuaciones que realizan enfermeras y enfermeros para promover la vida y la salud y apoyar a las personas con carencia de autonomía, ejercido con autonomía y responsabilidad propias. Esta definición reconoce la enfermería como disciplina con cuerpo de conocimiento propio. No se limita al tratamiento de enfermedades, ya que incluye promoción, prevención y acompañamiento. Tampoco reduce el cuidado a ayudas basadas en pautas médicas sin autonomía, ni lo restringe al hospital bajo supervisión médica, ya que se presta en todos los ámbitos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c68") }, {"question": "Según la Ley de Ordenación de las Profesiones Sanitarias (LOPS), ¿qué competencias corresponden a los Diplomados universitarios en Enfermería?", "long_answer": "El artículo 7 de la Ley 44/2003, de Ordenación de las Profesiones Sanitarias, atribuye a los Diplomados universitarios en Enfermería la dirección, evaluación y prestación de los cuidados de enfermería orientados a la promoción, mantenimiento y recuperación de la salud, así como a la prevención de enfermedades y discapacidades. Esta definición reconoce la autonomía de la profesión en su ámbito de competencia. Por ello es incorrecto afirmar que sus funciones sean exclusivamente asistenciales bajo orden médica, que se limiten a la gestión de servicios sin atención directa o que se reduzcan a la investigación y la docencia, que son funciones complementarias de la enfermera."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a87") }, {"long_answer": "El Plan de Acción de Atención Primaria y Comunitaria 2025-2027 establece que, durante el primer trimestre de 2025, se consensúe con los actores participantes la metodología de seguimiento y evaluación, de manera que el sistema de indicadores y los responsables de su recogida queden definidos desde el principio y la evaluación sea compartida. El plan no propone simplificarlo eliminando indicadores complejos, ni externalizar la evaluación a empresas privadas, ya que el seguimiento se realiza en el marco del Ministerio de Sanidad y las comunidades autónomas. Ignorar los indicadores de accesibilidad sería contrario al propio plan, que considera la accesibilidad una de sus prioridades."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a8a") }, {"long_answer": "El plan propone desarrollar un modelo común en el SNS para calcular las necesidades de recursos humanos en Atención Primaria que tenga en cuenta la morbilidad atendida, los resultados en salud y las características sociodemográficas de la población, superando el criterio clásico basado solo en el número de tarjetas sanitarias. Así se pretende asignar profesionales según la complejidad y las necesidades reales. No se basa en el nivel económico de los profesionales de cada región, ni únicamente en la densidad de población, que no refleja la carga asistencial, ni en la capacidad tecnológica disponible, que es un recurso complementario pero no determina las plantillas necesarias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a8c") }, {"long_answer": "En su línea 3, el plan contempla renovar las infraestructuras y el equipamiento de los centros de Atención Primaria de forma acorde con la actualización de la cartera de servicios que realicen las comunidades autónomas, con el fin de aumentar la capacidad resolutiva de los equipos y permitir incorporar nuevas pruebas y procedimientos en el propio centro de salud. No se plantea cancelar las actualizaciones, que son necesarias para mantener la calidad asistencial, ni trasladar a los profesionales a nuevos centros urbanos, lo que perjudicaría la accesibilidad en el medio rural. Tampoco se limita al equipamiento tecnológico dejando de lado los edificios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a93") }, {"question": "Según los datos del Plan de Acción de Atención Primaria y Comunitaria, ¿cuántas consultas anuales se atienden en los servicios de urgencias de Atención Primaria?", "long_answer": "Según los datos de actividad recogidos en el plan, los servicios de urgencias de Atención Primaria atienden alrededor de 33,6 millones de consultas al año (33.608.094), una cifra muy inferior a la de la actividad ordinaria de los centros de salud en medicina de familia, pediatría y enfermería. Las cifras de 385, 213 o 144 millones son órdenes de magnitud propios de la actividad ordinaria programada y a demanda, no de la atención urgente, que representa solo una parte menor del total de consultas de Atención Primaria. Conocer este volumen ayuda a dimensionar los dispositivos de atención continuada y urgente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a97") }, {"long_answer": "Los datos del plan muestran que la mayoría de las personas con problemas de salud mental son atendidas en Atención Primaria, y que el profesional que con más frecuencia las atiende es el médico de familia, puerta de entrada al sistema y responsable del seguimiento de los trastornos mentales comunes como la ansiedad o la depresión leve. Por eso el plan insiste en reforzar la colaboración entre Atención Primaria y Salud Mental. Psicólogos, psiquiatras y enfermeras especialistas en salud mental atienden sobre todo los casos derivados o de mayor complejidad, por lo que, en volumen de pacientes atendidos, no superan al médico de familia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a9c") }, {"long_answer": "El plan destaca la potenciación de la figura del administrativo de salud, o gestor sanitario, como la medida que ha permitido optimizar más del 75% de los procedimientos administrativos en Atención Primaria, liberando tiempo de médicos y enfermeras para tareas clínicas al asumir gestiones como citas, informes, bajas o derivaciones. La digitalización es un apoyo importante, pero no es la medida a la que el plan atribuye este resultado. Contratar exclusivamente médicos no resuelve la carga burocrática, sino que la mantiene en profesionales clínicos, y reducir las consultas no es una medida de optimización administrativa, sino que limitaría la accesibilidad de la población."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aa3") }, {"long_answer": "La línea 1 del plan incluye medidas para fomentar la longitudinalidad, es decir, que cada persona sea atendida de forma continuada por el mismo médico de familia y la misma enfermera a lo largo del tiempo, lo que se asocia a menos hospitalizaciones, menos urgencias, mejor control de las enfermedades crónicas e incluso menor mortalidad. Incentivar la rotación frecuente de profesionales o eliminar el seguimiento longitudinal irían en dirección contraria, rompiendo la relación de confianza y el conocimiento acumulado del paciente. Centralizar la atención en la Atención Especializada contradice el enfoque del plan, que sitúa a la Atención Primaria como eje del sistema."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aa6") }, {"long_answer": "Para asegurar la equidad en el acceso, el plan propone adecuar las modalidades de atención (presencial, telefónica, telemática y domiciliaria) a las necesidades de la población y, al mismo tiempo, reducir la brecha digital en los grupos vulnerables, como personas mayores o en situación de exclusión, para que la atención no presencial no genere nuevas desigualdades. Implantar exclusivamente la atención presencial en centros urbanos excluiría a la población rural y renunciaría a las ventajas de la no presencial. Eliminar todas las modalidades no presenciales iría contra la accesibilidad, y limitar el acceso de las personas mayores sería discriminatorio y contrario a la equidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ab0") }, {"option_4": "No se desglosa ninguna información sobre las personas", "long_answer": "En el seguimiento de las convocatorias competitivas y no competitivas específicas para investigación en Atención Primaria, el plan establece que se recoja la información de las personas convocadas desglosada por sexo y por tipo de convocatoria, lo que permite analizar la perspectiva de género en el acceso a la financiación y comparar ambos tipos de convocatoria. No se consideran solo las competitivas ni solo las no competitivas, ya que la medida incluye ambas modalidades para favorecer tanto la investigación consolidada como el inicio de nuevos investigadores. Y afirmar que no se desglosa información contradice el indicador definido en el propio plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ab3") }, {"long_answer": "En el programa de intensificación de la actividad investigadora de la Acción Estratégica en Salud, el indicador definido es la tasa de éxito anual, calculada como la relación entre el número de profesionales de Atención Primaria a los que se concede financiación y el número de los que la solicitan. Este indicador permite valorar si la convocatoria facilita realmente que los profesionales liberen tiempo asistencial para investigar. El número de solicitudes ignoradas, el número de proyectos no competitivos o el porcentaje de proyectos rechazados sin evaluación no son indicadores contemplados ni reflejan el éxito de la convocatoria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ab5") }, {"long_answer": "El plan establece el seguimiento anual del porcentaje de investigadores de Atención Primaria integrados en los Institutos de Investigación Sanitaria y lo vincula con la acreditación de estos institutos por el Instituto de Salud Carlos III, de modo que la incorporación de profesionales de primaria se convierta en un criterio para mantener dicha acreditación. Con ello se incentiva que los institutos, tradicionalmente muy hospitalarios, integren grupos de Atención Primaria. No se pretende asignar fondos exclusivamente a hospitales, ni reducir el apoyo a la investigación en primaria, ni eliminar su componente investigador, que es justo lo que el plan quiere reforzar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ab7") }, {"long_answer": "Para valorar la internacionalización de la investigación en Atención Primaria, el plan monitoriza el porcentaje de proyectos europeos concedidos que cuentan con profesionales de Atención Primaria en sus equipos de investigación. Este indicador mide de forma directa la participación efectiva de primaria en convocatorias competitivas internacionales. El número de proyectos presentados sin inclusión de profesionales de primaria no informa sobre su participación, el porcentaje de proyectos rechazados por falta de equipos multidisciplinares no es un indicador definido y el número de colaboraciones no europeas no corresponde al ámbito al que se refiere la medida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ab8") }, {"long_answer": "El mapa de situación de la I+D en Atención Primaria no se limita a datos de producción o económicos, sino que incluye información sobre los recursos de apoyo metodológico disponibles y las infraestructuras de investigación existentes en los centros de salud, junto con los grupos y la actividad investigadora. Esto permite detectar dónde faltan unidades de apoyo y planificar recursos. Por tanto, es incorrecto que se limite a datos económicos sin análisis metodológico, que incluya solo datos hospitalarios, ya que su objeto es precisamente la Atención Primaria, o que ignore los grupos de investigación reconocidos, que forman parte de la información recogida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ab9") }, {"long_answer": "El plan prevé convocatorias específicas para Atención Primaria tanto competitivas como no competitivas, acompañadas de apoyo metodológico, con el fin de favorecer que los profesionales se inicien en la investigación y que los grupos emergentes puedan consolidarse. Las no competitivas facilitan el primer contacto con la investigación y las competitivas impulsan proyectos de mayor envergadura. Por ello es incorrecto que solo se contemplen convocatorias no competitivas, que se trate de convocatorias externas sin apoyo metodológico, cuando este apoyo es un elemento clave de la medida, o que se abran exclusivamente a hospitales universitarios, lo que excluiría a la propia Atención Primaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ac2") }, {"long_answer": "El plan establece un calendario en dos fases para las modalidades de atención no presencial: antes de 2026, las comunidades autónomas deben presentar los resultados de la evaluación de su implantación, y antes de 2027 deben incorporarse criterios comunes consensuados en el SNS a partir de esa evaluación. Así se garantiza que la atención telefónica y telemática se ordene con criterios de calidad y equidad. No se trata de un plazo en 2028 sin seguimiento previo ni de 2030 sin indicadores, ya que el plan tiene horizonte 2025-2027, y afirmar que no hay plazo claro contradice los hitos fijados en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ac4") }, {"long_answer": "El plan fija como resultado esperado que el 100% de las comunidades autónomas hayan publicado su Estrategia de Salud Comunitaria antes de diciembre de 2027, coincidiendo con el final de su periodo de vigencia, 2025-2027. Así se da un margen suficiente para que cada comunidad elabore su estrategia con participación de profesionales, ayuntamientos y ciudadanía. Diciembre de 2025 y de 2026 son hitos intermedios demasiado tempranos para exigir a todas las comunidades la publicación, y diciembre de 2028 queda fuera del horizonte temporal del plan, por lo que no puede ser el plazo establecido."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aca") }, {"long_answer": "La actualización anual del mapa de situación de la I+D en Atención Primaria tiene como objetivo aportar información que permita una planificación eficiente de los recursos de investigación y dar visibilidad a la actividad investigadora que se realiza en primaria, a menudo poco reconocida. Con ello se identifican grupos, líneas y necesidades de apoyo. La evaluación de la brecha digital en colectivos vulnerables y el seguimiento del acceso a la atención no presencial pertenecen a la línea de accesibilidad del plan, y la medición de la satisfacción del paciente es un indicador de calidad percibida, no el objetivo de este mapa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ad0") }, {"long_answer": "En la línea de accesibilidad, el plan prevé evaluar antes de 2026 la implantación de la modalidad de atención no presencial en las comunidades autónomas, es decir, cómo se están utilizando la consulta telefónica y la telemática, con qué criterios y con qué resultados, como paso previo para consensuar criterios comunes. La satisfacción del paciente en Atención Primaria es un aspecto distinto de calidad percibida. La formación de profesionales en salud comunitaria corresponde a la línea de orientación comunitaria, y la actualización de la cartera básica común es otra medida del plan, sin relación directa con esta evaluación de la atención no presencial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ad1") }, {"long_answer": "Para la atención sanitaria a personas sin hogar, el plan fija como resultado esperado en 2027 que al menos el 50% de las comunidades autónomas hayan puesto en marcha al menos el 30% de las recomendaciones consensuadas, una meta realista que mide la implantación progresiva. Erradicar el sinhogarismo en el 100% de las comunidades excede las competencias sanitarias y no es un objetivo medible del plan. Prestar la atención exclusivamente mediante teleconsulta sería contraproducente en una población con importantes barreras de acceso digital, y la publicación semestral de un informe sobre sinhogarismo no es el indicador definido en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ad5") }, {"long_answer": "El plan prevé incluir en la Historia Clínica Digital Interoperable del SNS un conjunto mínimo consensuado de condicionantes sociales y del contexto familiar, como la situación de convivencia, las personas cuidadoras o la situación socioeconómica, ya que estos determinantes influyen en la salud y deben estar accesibles para todos los profesionales que atienden a la persona. Limitarla a indicadores clínicos, a datos administrativos y económicos o a datos biométricos y constantes vitales no responde al objetivo de la medida, que es incorporar la dimensión social y comunitaria a la información clínica compartida entre niveles asistenciales y comunidades autónomas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ad6") }, {"long_answer": "El Plan de Capacitación en Salud Comunitaria prevé una formación en formato de cursos online, acreditados y gratuitos para los profesionales de Atención Primaria, con el fin de llegar a todos los equipos del territorio, facilitar la conciliación con la actividad asistencial y garantizar el reconocimiento de la formación. No se dirige exclusivamente a médicos, ya que la salud comunitaria es una tarea de todo el equipo, con un papel destacado de la enfermería. Los talleres presenciales de pago y los cursos de especialización en universidades privadas no se corresponden con la formación prevista, que es pública, accesible y gratuita."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ade") }, {"long_answer": "El indicador de proceso de la formación en salud comunitaria es el número de profesionales formados por las comunidades autónomas y por el Ministerio de Sanidad, desglosado por nivel y modalidad de formación, ya que permite conocer el alcance real del Plan de Capacitación y su distribución territorial. El porcentaje de pacientes que usan teleconsulta corresponde a la línea de accesibilidad, el número de proyectos de I+D aprobados pertenece a la línea de investigación y el porcentaje de herramientas digitales usadas en Atención Primaria se relaciona con la transformación digital, por lo que ninguno de ellos mide la formación en salud comunitaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ae1") }, {"long_answer": "La acción prevista para lograr un modelo común de cálculo de necesidades de recursos humanos en Atención Primaria consiste en basarlo en la morbilidad atendida, los resultados en salud y las características sociodemográficas de la población, de forma que las plantillas se ajusten a la carga de trabajo y la complejidad reales de cada zona. Fijar un número de profesionales igual con independencia del territorio ignoraría las diferencias de envejecimiento, dispersión o vulnerabilidad. Asignar los recursos por criterio político carece de base técnica, y determinar las necesidades por los años de experiencia de los profesionales no guarda relación con las necesidades de salud de la población."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ae9") }, {"long_answer": "En el sistema de indicadores del plan, el indicador 11 es el que recoge el número de centros de salud acreditados por la Iniciativa para la Humanización de la Asistencia al Nacimiento y la Lactancia (IHAN) en cada comunidad autónoma, en relación con la medida de promoción y apoyo a la lactancia materna desde Atención Primaria, incluida en el abordaje de la obesidad infantil. La acreditación IHAN garantiza que el centro aplica prácticas basadas en la evidencia para proteger, promover y apoyar la lactancia. Los indicadores 1, 7 y 12 corresponden a otras medidas del plan y no miden la acreditación IHAN de los centros de salud."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977afb") }, {"long_answer": "El plan impulsa la atención familiar en el hogar desde Atención Primaria con el objetivo de proporcionar cuidados adecuados en el domicilio a las personas que lo necesitan, como pacientes inmovilizados, con enfermedades crónicas avanzadas o al final de la vida, y de garantizar la longitudinalidad de la atención por su equipo de referencia, médico de familia y enfermera. Reducir las visitas domiciliarias y centralizar la atención en los hospitales, o limitarla a equipos hospitalarios, iría en contra de ese objetivo. Disminuir el papel de la enfermería sería contrario al plan, que reconoce a la enfermera como figura clave en la atención domiciliaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b03") }, {"long_answer": "La comunicación bidireccional entre las farmacias comunitarias y los centros de salud o consultorios tiene como finalidad mejorar el uso racional y seguro de los medicamentos mediante la coordinación entre farmacéuticos, médicos y enfermeras, por ejemplo para comunicar problemas relacionados con la medicación, interacciones, duplicidades o dificultades de adherencia, especialmente en pacientes polimedicados. No persigue aumentar la venta de medicamentos sin receta, ni reducir la comunicación entre profesionales, que es justo lo que se quiere reforzar. Tampoco pretende centralizar la prescripción en los hospitales, lo que alejaría la atención farmacoterapéutica de la comunidad y de la Atención Primaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b08") }, {"long_answer": "Entre los recursos de apoyo digital, el plan menciona el Plan de Transformación Digital de Atención Primaria, que incluye herramientas como cuadros de mando para la gestión y la evaluación de la actividad, y la teleconsulta como modalidad de atención, con el objetivo de mejorar la eficiencia, la accesibilidad y la gestión de los equipos. No se trata de una aplicación móvil exclusiva para pacientes crónicos, ni de un software privativo sin acceso público, ya que se basa en la interoperabilidad dentro del SNS. Tampoco es un sistema de gestión solo para hospitales, puesto que va dirigido específicamente a la Atención Primaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b0a") }, {"long_answer": "La Estrategia de la Industria Farmacéutica señala que en las fases iniciales del desarrollo de medicamentos predominan los financiadores públicos, porque son etapas con menor inversión relativa pero con gran incertidumbre sobre el éxito, poco atractivas para el capital privado que busca un retorno más seguro. Los inversores privados, como business angels y fondos de capital riesgo, suelen intervenir cuando el proyecto ha mostrado resultados preliminares. Las organizaciones filantrópicas participan, pero no de forma exclusiva ni mayoritaria, y las grandes compañías especializadas en comercialización entran sobre todo en las fases clínicas avanzadas, mediante adquisiciones o licencias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b12") }, {"long_answer": "La resistencia a los antimicrobianos tiene como consecuencia directa para la salud pública mundial un aumento de la morbilidad y la mortalidad por infecciones difíciles de tratar y un incremento de los costes sanitarios, y pone en riesgo avances médicos como la cirugía compleja, los trasplantes o la quimioterapia, que dependen de antibióticos eficaces. Por eso la Estrategia la considera un área estratégica. No reduce el gasto farmacéutico ni controla infecciones, sino al contrario. Tampoco mejora la eficacia de los antibióticos convencionales, que es precisamente lo que se pierde, ni disminuye las enfermedades emergentes, cuyo riesgo aumenta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b1d") }, {"option_1": "Horizonte 2024-2028, con enfoque integrado y sostenible", "long_answer": "La Estrategia de la Industria Farmacéutica se plantea con un horizonte temporal 2024-2028, con una visión integrada que abarca investigación, producción, acceso y sostenibilidad del sistema, y sostenible a medio plazo. Este periodo permite desplegar medidas regulatorias, de financiación y de política industrial que necesitan varios años para dar resultados. Un plazo inferior a un año sería insuficiente para cambios de esta envergadura. El periodo 2021-2022 es anterior a la propia aprobación de la Estrategia, y un horizonte a 2035 sin revisión intermedia no corresponde al documento, que además prevé mecanismos de seguimiento y gobernanza."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b26") }, {"long_answer": "La Estrategia insiste en que sus medidas, construidas sobre una alianza entre actores públicos y privados, solo serán efectivas si se convierten en acciones tangibles, sostenibles en el tiempo y beneficiosas para la sociedad, es decir, si mejoran el acceso a los medicamentos, la salud de la población y el tejido industrial y científico. No pueden orientarse exclusivamente a la rentabilidad empresarial, porque el eje de la Estrategia son las necesidades en salud. Atender solo demandas individuales sin priorizar comprometería la sostenibilidad, e imponer medidas sin consenso contradice la base de colaboración sobre la que se construye la Estrategia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b27") }, {"long_answer": "Uno de los objetivos principales de la Estrategia de la Industria Farmacéutica 2024-2028 es impulsar la autonomía estratégica de España y de la Unión Europea en medicamentos, reforzando la capacidad de investigación y producción y las cadenas de suministro, y a la vez garantizar la sostenibilidad del Sistema Nacional de Salud. Reducir el empleo en la industria es contrario a su propósito, que valora el empleo cualificado que genera el sector. Eliminar los genéricos iría contra la sostenibilidad y el acceso, ya que la Estrategia los promueve, y cancelar la colaboración público-privada contradice su modelo de alianza."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b2c") }, {"long_answer": "Dentro de la línea relativa a la mejora de la financiación y la fijación de precios de los medicamentos, la Estrategia incluye la creación de un sistema para la evaluación eficiente de tecnologías sanitarias, que permita valorar el valor terapéutico añadido y el impacto económico de forma rigurosa, previsible y ágil, sirviendo de base a las decisiones de precio y financiación. El desarrollo de vacunas de ARNm, el impulso de la autonomía estratégica mediante cadenas de suministro y la promoción de la medicina personalizada de precisión son medidas de otras líneas de la Estrategia, relacionadas con la investigación, la producción o las áreas terapéuticas prioritarias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b2e") }, {"long_answer": "La Estrategia propone superar el modelo tradicional de relación proveedor-cliente entre la industria y las instituciones públicas, en el que la Administración se limita a comprar medicamentos, y avanzar hacia dinámicas virtuosas integradas, en las que industria, sistema sanitario, academia y Administración colaboran en investigación, producción, acceso y sostenibilidad. Por tanto, mantener exclusivamente el modelo proveedor-cliente es lo contrario de lo que plantea. Separar estrictamente la innovación privada del control público rompería esa colaboración, y centralizar toda la producción en el sector público no forma parte de la Estrategia, que se basa en la alianza público-privada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b2f") }, {"long_answer": "El Ministerio de Agricultura no formó parte del grupo de trabajo interministerial que elaboró la Estrategia de la Industria Farmacéutica, que reunió a los ministerios con competencias directas en el sector: el Ministerio de Sanidad, por su responsabilidad en la regulación, la financiación y el acceso a los medicamentos; el Ministerio de Ciencia, Innovación y Universidades, por la investigación y la innovación biomédica; y el Ministerio de Industria y Turismo, por la política industrial y la capacidad productiva. Agricultura puede tener relación con el medicamento veterinario, pero no participó en la elaboración de esta Estrategia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b32") }, {"long_answer": "La Estrategia prioriza favorecer el acceso de los pacientes a los medicamentos innovadores, de forma equitativa y en tiempos adecuados, compatibilizándolo con la sostenibilidad del sistema mediante una evaluación rigurosa de su valor. No plantea disminuir su uso por el coste, sino gestionar ese coste con instrumentos de evaluación y financiación. Tampoco propone invertir exclusivamente en genéricos, que se promueven como complemento para liberar recursos, y no pretende eliminar el reposicionamiento terapéutico fuera del periodo de protección, sino al contrario, ya que lo considera una vía eficiente para obtener nuevas indicaciones de fármacos ya conocidos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b36") }, {"long_answer": "Cuando la Estrategia habla de priorización en inversiones inter e intra sectoriales se refiere a asignar los recursos públicos con criterios que equilibren el acceso a los medicamentos y el gasto farmacéutico, dentro del sector sanitario y respecto a otros sectores, para que la incorporación de innovaciones no comprometa la sostenibilidad del SNS. No significa reducir la inversión pública para dejar paso solo a la privada, ni invertir exclusivamente en biosimilares, que son una herramienta más de eficiencia. Tampoco implica eliminar la financiación de determinadas terapias, sino decidir de forma transparente y basada en el valor qué se financia y con qué prioridad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b37") }, {"long_answer": "Las necesidades en salud de la población son uno de los elementos tractores de la Estrategia de la Industria Farmacéutica: las medidas de investigación, producción y acceso se orientan a dar respuesta a esas necesidades, junto con la seguridad y la autonomía estratégica. Por eso es incorrecto plantear como motor únicamente el desarrollo económico, que es un objetivo importante pero no exclusivo. Reducir el gasto hospitalario sin control no es un elemento tractor, sino que podría comprometer la calidad asistencial, y la exportación exclusiva de productos farmacéuticos dejaría de lado el abastecimiento y las necesidades del propio sistema sanitario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b3a") }, {"long_answer": "En la gobernanza de la Estrategia, la Alianza para la Estrategia es el espacio que conecta al Comité Interministerial con los agentes públicos y privados del sector, como comunidades autónomas, industria, profesionales, pacientes y academia, para debatir y orientar las políticas hacia necesidades y soluciones concretas. El Consejo de Innovación Farmacéutica, la Mesa Nacional de Investigación y el Comité de Control de Medicamentos no son los órganos que describe la Estrategia para esta función de encuentro entre el Comité Interministerial y el conjunto de actores del ecosistema farmacéutico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b4b") }, {"long_answer": "La Estrategia contempla mecanismos de financiación acelerada que permiten financiar de forma provisional o condicionada determinados medicamentos con necesidad médica no cubierta, cuando aún existe incertidumbre sobre su beneficio, con la obligación de revisar posteriormente la decisión a la luz de los nuevos datos de efectividad y de uso real. Por tanto, no elimina la revisión posterior, que es un elemento esencial del modelo. Tampoco se aplica solo a genéricos y biosimilares, que no presentan esta incertidumbre, sino sobre todo a medicamentos innovadores, y no se plantea como un mecanismo condicionado a una aprobación europea previa distinta de la autorización de comercialización."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b4c") }, {"long_answer": "La reforma del procedimiento de inclusión de nuevos medicamentos en la financiación pública busca, entre otros objetivos, mejorar la evaluación económica para que la fijación de precios sea más eficiente, es decir, que el precio se relacione con el valor terapéutico añadido y el impacto presupuestario. Reducir costes de fabricación mediante externalización no es materia de este procedimiento. Eliminar la evaluación del beneficio clínico adicional iría contra la base de la evaluación de tecnologías sanitarias, y unificar totalmente los procedimientos con otros países de la UE no es posible, ya que la decisión de precio y financiación sigue siendo competencia nacional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b4d") }, {"option_3": "Comisión Delegada del Gobierno para Asuntos Económicos (CDGAE)", "option_2": "Comisión Interministerial de Precios de los Medicamentos (CIPM)", "long_answer": "Según la Estrategia, los criterios que definen la financiación pública de medicamentos se aprueban por la Comisión Delegada del Gobierno para Asuntos Económicos (CDGAE), que establece el marco general de criterios en el que después decide el Comité Interministerial de Precios de Medicamentos. La CIPM aplica esos criterios a cada medicamento concreto al fijar precio y condiciones de financiación, pero no los aprueba. El Consejo Interterritorial del SNS es un órgano de coordinación con las comunidades autónomas y no aprueba estos criterios, y el Ministro de Sanidad dirige la política farmacéutica, pero los criterios generales requieren el acuerdo de la CDGAE."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b4e") }, {"long_answer": "Para aumentar la transparencia y la sostenibilidad del sistema de precios, la Estrategia propone introducir una contabilidad real del uso de los medicamentos y publicar métricas de utilización, de forma que las decisiones de precio y financiación puedan revisarse con datos del uso real y del impacto económico. Fijar precios sin revisiones periódicas impediría adaptarlos a la evidencia y al mercado. Excluir los biosimilares del sistema de precios de referencia reduciría la competencia y la eficiencia, y prohibir la participación de la industria en la evaluación económica es contrario al diálogo que promueve la Estrategia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b51") }, {"long_answer": "El sistema nacional de información de consumo de medicamentos tiene como objetivo facilitar la toma de decisiones con información actualizada sobre consumo y costes, desagregada por centro sanitario y por comunidad autónoma, incluyendo el ámbito hospitalario, lo que permite evaluar la eficiencia, comparar entre territorios y revisar las decisiones de financiación. No se limita a las farmacias comunitarias privadas, ya que debe recoger todo el consumo financiado. No pretende evitar la competencia entre comunidades, sino generar transparencia y comparabilidad, y no está concebido para generar datos exclusivamente para la industria, sino para la planificación y la gestión pública."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b59") }, {"long_answer": "La Estrategia señala que España participará en la red de laboratorios de referencia de la Unión Europea (EURLabs) para productos sanitarios de diagnóstico in vitro de alto riesgo, una figura creada por el Reglamento europeo de productos sanitarios para diagnóstico in vitro, que verifica el funcionamiento de estos productos y los lotes antes de su comercialización. Su función no es regular la comercialización de medicamentos, que corresponde a las agencias reguladoras, ni financiar ensayos clínicos con participación privada. Tampoco se limita a implementar dispositivos médicos en hospitales privados, ya que actúa en todo el mercado europeo de diagnóstico in vitro."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b5e") }, {"option_3": "Excluir la participación de investigadores externos", "long_answer": "El marco regulatorio nacional para el uso secundario de datos sanitarios, en línea con el Espacio Europeo de Datos Sanitarios, debe garantizar la transparencia en el acceso, la facilidad de uso para investigadores e innovadores y el pleno respeto a la protección de los datos personales, de modo que la información generada en el sistema sanitario pueda utilizarse para investigación, innovación y políticas públicas con seguridad jurídica. Limitar el acceso a empresas privadas sin supervisión pública vulneraría las garantías. Excluir a los investigadores externos impediría aprovechar los datos, y restringir su uso a la evaluación económica dejaría fuera la investigación clínica y la salud pública."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b5f") }, {"long_answer": "Para reforzar la ciberseguridad en la investigación clínica, la Estrategia propone adoptar estándares comunes y compatibles entre todos los actores implicados, como promotores, centros, comités y Administración, para proteger los datos de los ensayos clínicos y garantizar su integridad y confidencialidad sin frenar la digitalización. Cerrar las bases de datos a terceros impediría la colaboración necesaria en la investigación. Volver al papel limitaría la eficiencia y no garantiza mayor seguridad, y delegar la protección de datos en empresas privadas sin supervisión iría contra el marco de protección de datos y de seguridad que exige la normativa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b61") }, {"question": "Respecto a la estrategia de mejora en financiación y precio, ¿qué papel tiene la Comisión Interministerial de Precios de los Medicamentos (CIPM)?", "long_answer": "La Estrategia prevé reforzar el papel de la Comisión Interministerial de Precios de los Medicamentos (CIPM) mediante criterios más claros y análisis terapéuticos y económicos más rigurosos para fijar precios y condiciones de financiación, incluidos los de genéricos y biosimilares, aumentando así la previsibilidad y la transparencia de sus decisiones. No se pretende que apruebe precios sin criterios técnicos, que sería lo contrario a lo que se propone. La CIPM no gestiona la distribución de medicamentos en las farmacias, que es una actividad logística y comercial, y eliminar la evaluación económica restaría rigor y eficiencia a las decisiones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b65") }, {"long_answer": "En la compra pública de medicamentos, la Estrategia propone promover la concurrencia entre proveedores, la sostenibilidad y la incorporación de criterios de autonomía estratégica, como la seguridad del suministro o la producción en la UE, sin generar cargas administrativas innecesarias. Así se pretende evitar desabastecimientos y no depender únicamente del precio. Una compra única centralizada sin participación autonómica no respeta el reparto de competencias. Comprar solo por el precio más bajo favorece la concentración de proveedores y el riesgo de desabastecimiento, y las negociaciones secretas sin criterios publicados son contrarias a la transparencia que exige la contratación pública."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b66") }, {"long_answer": "Para mejorar la predictibilidad y la transparencia en el acceso a nuevos medicamentos, la Estrategia propone un sistema claro con reglas y criterios predefinidos para las decisiones de financiación y precio, de forma que las compañías y la sociedad conozcan de antemano cómo se valorarán los medicamentos y en qué plazos. Permitir cambios arbitrarios por parte de los gestores generaría inseguridad jurídica y retrasos. Reducir la publicación de las decisiones disminuiría la transparencia, y fijar precios máximos sin criterios clínicos desvincularía el precio del valor terapéutico, que es el eje de la evaluación de tecnologías sanitarias."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b68") }, {"long_answer": "La elaboración de contratos tipo con cláusulas armonizadas para la investigación en el SNS tiene como objetivo reducir los tiempos y costes de administración en la puesta en marcha de los estudios, evitando negociaciones distintas en cada centro, y asegurar la transparencia en la publicación de los resultados. Esto hace a España más competitiva para atraer ensayos clínicos. No busca garantizar el mayor beneficio económico para las entidades públicas, sino agilizar y homogeneizar los procedimientos. Tampoco persigue proteger la propiedad intelectual exclusiva de la industria ni asegurar la exclusividad comercial de los medicamentos, cuestiones que se regulan por otras vías."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b6a") }, {"long_answer": "CERTERA, la plataforma de terapias avanzadas integrada en el Sistema Español de Ciencia, Tecnología e Innovación, actúa como estructura en red que facilita alianzas estratégicas con el sector industrial y promueve la incorporación continua de nuevas entidades, conectando las capacidades de investigación y producción académicas con la industria para trasladar las terapias avanzadas a la práctica clínica. No es un simple financiador de proyectos industriales, ni centraliza la producción de medicamentos de terapias avanzadas en un único lugar, ya que funciona como red de centros. Tampoco supervisa los ensayos clínicos nacionales, función que corresponde a la AEMPS y los comités de ética."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b6c") }, {"long_answer": "El despliegue de la taxonomía genómica de resistencias antimicrobianas busca caracterizar de forma precoz, mediante herramientas genómicas, los genotipos microbiológicos responsables de resistencias clínicamente relevantes, también a nivel individual, lo que permite orientar el tratamiento antibiótico y mejorar la vigilancia epidemiológica. No se centra en desarrollar nuevos antibióticos de origen natural, que es un objetivo de investigación distinto. Tampoco pretende limitar la genómica a la investigación básica, sino incorporarla a la práctica clínica y a la salud pública, y no tiene que ver con imponer controles a los medicamentos sin prescripción."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b6d") }, {"long_answer": "El programa INNVIERTE, gestionado por el Centro para el Desarrollo Tecnológico y la Innovación (CDTI), realiza coinversiones público-privadas de capital riesgo en empresas tecnológicas e innovadoras, incluidas biotecnológicas y farmacéuticas, para favorecer su capitalización y crecimiento en fases en las que es difícil obtener financiación privada. No pretende que el Estado asuma la propiedad pública total de empresas privadas, sino participar junto a inversores privados. Tampoco promueve exclusivamente la investigación básica sin vínculo con el mercado, ya que su finalidad es llevar la innovación al mercado, ni consiste en fundar corporaciones farmacéuticas públicas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b71") }, {"long_answer": "La Estrategia propone conectar los centros académicos y las entidades basadas en el conocimiento, como universidades, institutos de investigación sanitaria y spin-offs, con organizaciones de desarrollo y fabricación por contrato (CDMOs) y de investigación por contrato (CROs) especializadas, para que los descubrimientos puedan avanzar en el desarrollo preclínico y las fases clínicas tempranas. No se limita a las grandes farmacéuticas internacionales, ni se dirige solo a instituciones públicas sin participación privada, ya que precisamente busca la colaboración entre ambos sectores. Tampoco pretende conectar laboratorios comerciales para la venta directa, que no corresponde a las fases de desarrollo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b7c") }, {"long_answer": "La Alianza de Medicamentos Críticos, impulsada por la Comisión Europea, tiene como finalidad reforzar las capacidades de fabricación en la Unión Europea y diversificar las cadenas de suministro de los medicamentos considerados críticos, para garantizar su disponibilidad y reducir la dependencia de terceros países y el riesgo de desabastecimiento. No pretende centralizar la compra de todos los medicamentos en Europa, ya que la compra sigue siendo mayoritariamente nacional. Concentrar la producción en un único Estado miembro aumentaría la vulnerabilidad, y eliminar la coordinación en emergencias sanitarias sería contrario a su objetivo de resiliencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b86") }, {"long_answer": "El intento previo de suicidio es el factor de riesgo aislado más importante para predecir la conducta suicida: las personas que ya han realizado un intento tienen un riesgo muy superior de repetirlo y de fallecer por suicidio, especialmente en los meses siguientes, por lo que el Plan insiste en su seguimiento precoz tras el alta. Las enfermedades crónicas, la edad avanzada y el consumo de sustancias son también factores de riesgo reconocidos, pero su capacidad predictiva por separado es menor que la del antecedente de intento autolítico, que es el predictor individual más potente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b8e") }, {"long_answer": "El Plan considera a las personas con discapacidad en situación de vulnerabilidad frente al suicidio por las dificultades de accesibilidad a todos los entornos (sanitario, social, laboral, educativo) y por estar expuestas a más factores de exclusión, como el aislamiento, la discriminación o la dependencia, que incrementan el sufrimiento y reducen los factores protectores. La menor esperanza de vida no es el motivo que se señala. Recibir más apoyo social o tener mejor acceso a tratamientos médicos serían factores protectores, no de vulnerabilidad, y además no reflejan la realidad de barreras que describe el Plan para este colectivo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b90") }, {"long_answer": "El Plan describe en adolescentes y jóvenes un aumento del sufrimiento emocional y de la conducta suicida en los últimos años, y subraya la necesidad de crear espacios saludables, seguros y libres de violencia, como el entorno escolar y el digital, donde se prevengan el acoso y otras formas de violencia y se favorezca la detección precoz. Por eso no puede afirmarse que presenten alta resiliencia y bajo riesgo. Tampoco es cierto que la incidencia de trastornos mentales sea escasa en este grupo, ni que el consumo de sustancias psicoactivas sea bajo, ya que ambos son factores de riesgo relevantes en esta etapa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b91") }, {"long_answer": "La posvención, es decir, las intervenciones dirigidas a familiares y allegados tras un suicidio, es una parte esencial de la prevención, porque las personas en duelo por suicidio tienen mayor riesgo de sufrimiento intenso, de trastornos mentales y de conducta suicida. Los grupos de apoyo y el acompañamiento ayudan a manejar el duelo y a disminuir la intensidad del sufrimiento. Por ello es falso que sea irrelevante para prevenir nuevas conductas suicidas. Tampoco se basa únicamente en el tratamiento farmacológico de los familiares, y no se limita a evitar la comunicación en redes sociales, aunque una comunicación responsable forma parte de la prevención."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b96") }, {"long_answer": "El objetivo principal del Plan de Acción para la Prevención del Suicidio es reducir y prevenir la conducta suicida en la población, prestando especial atención a los grupos en situación de vulnerabilidad, como personas con intentos previos, adolescentes y jóvenes, personas mayores, personas con discapacidad o en riesgo de exclusión. Para ello combina medidas de sensibilización, detección precoz, atención, seguimiento y posvención. Eliminar el consumo de medicamentos en la población general no es un objetivo del Plan. Tampoco se basa exclusivamente en la terapia farmacológica, ya que el abordaje es multidisciplinar, ni su finalidad es aumentar la vigilancia en redes sociales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b99") }, {"long_answer": "La creación, dentro de la Red Estatal de Vigilancia en Salud Pública, de un sistema específico para la conducta suicida tiene como finalidad ofrecer la información necesaria para la toma de decisiones en prevención, recopilando datos de persona, lugar y tiempo sobre intentos y suicidios consumados que permitan identificar grupos de riesgo, tendencias y agregaciones. No pretende reforzar únicamente la atención hospitalaria, sino orientar la prevención en todos los niveles. Tampoco se limita a estadísticas nacionales sin intervención local, ya que la información debe servir a las comunidades autónomas, ni registra solo las defunciones, porque incluye también la conducta suicida no mortal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b9c") }, {"long_answer": "Para medir la mejora en el registro y seguimiento de la conducta suicida, el Plan utiliza como indicador el porcentaje de comunidades autónomas que colaboran con profesionales encargados del registro de los datos sobre conducta suicida, ya que la calidad del sistema de información depende de que cada comunidad disponga de personas responsables de recoger y notificar esos datos. El porcentaje de proyectos de investigación publicados mide la actividad investigadora, el porcentaje de hospitales que atienden urgencias psiquiátricas se refiere a la oferta asistencial y el porcentaje de llamadas a líneas telefónicas evalúa los servicios de ayuda, pero ninguno mide el registro."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b9d") }, {"long_answer": "El Plan considera fundamental la adecuación presupuestaria y una financiación suficiente y estable para garantizar la ejecución de sus acciones y su mejora continua, ya que medidas como el refuerzo de profesionales, los programas de seguimiento tras un intento, la formación o los sistemas de vigilancia requieren recursos. No deja de ser relevante aunque existan profesionales formados, porque estos necesitan estructuras y tiempo para aplicar lo aprendido. Tampoco afecta solo a las campañas de sensibilización, sino al conjunto del Plan, y no depende exclusivamente de organismos internacionales, ya que la financiación corresponde fundamentalmente al Estado y a las comunidades autónomas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a89") }, {"long_answer": "Entre las medidas para mejorar las condiciones laborales y la motivación de los profesionales de Atención Primaria, el plan propone ofrecer mayor flexibilidad en los horarios y en la organización del trabajo, lo que favorece la conciliación, hace más atractivos los puestos y contribuye a fidelizar a los profesionales. Eliminar la flexibilidad horaria tendría el efecto contrario sobre la motivación y la retención del talento. La reducción de la jornada laboral no es la medida que propone el plan, que se centra en la organización y la flexibilidad, y la contratación exclusiva de personal temporal aumentaría la precariedad y rompería la longitudinalidad de la atención."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a8d") }, {"long_answer": "Según los datos de 2022 recogidos en el plan, el gasto destinado a Atención Primaria supuso aproximadamente el 14,14% del gasto sanitario público, una proporción que se considera insuficiente frente a las recomendaciones de reforzar este nivel asistencial y que motiva la propuesta de vincular el crecimiento del presupuesto de primaria al del gasto sanitario total. Porcentajes del 25,7% o del 32,5% estarían en línea con los objetivos reivindicados para primaria, pero no reflejan el dato real. Un 8,9% infravaloraría el peso actual de la Atención Primaria en el gasto sanitario público."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a90") }, {"long_answer": "Los datos del plan indican que alrededor del 76,2% de las personas con diabetes mellitus atendidas en Atención Primaria presentan un control adecuado, definido por una hemoglobina glicosilada inferior al 7,5%. Este indicador de resultado refleja la calidad del seguimiento de la diabetes en los centros de salud, en el que la enfermería tiene un papel central mediante la educación diabetológica y el seguimiento periódico. Las cifras del 50,5% o del 68,8% infravaloran el control alcanzado, y la del 80,1% lo sobrestima respecto al dato que recoge el documento para este indicador."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a92") }, {"long_answer": "Según los datos de percepción ciudadana recogidos en el plan, solo en torno al 20,6% de los pacientes consiguen cita con su médico de Atención Primaria el mismo día o al día siguiente de solicitarla, lo que pone de manifiesto un problema de accesibilidad y demoras que el plan pretende abordar mediante la mejora de la organización, la gestión de la demanda y el refuerzo de las plantillas. Porcentajes como el 33,9%, el 50,3% o el 71,8% reflejarían una accesibilidad mucho mejor que la real y no se corresponden con el dato que justifica las medidas de accesibilidad del plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a94") }, {"long_answer": "Según los datos de percepción ciudadana del plan, alrededor del 82,2% de las personas que han acudido a la consulta médica presencial de Atención Primaria la califican como buena o muy buena, lo que muestra una alta valoración de la atención recibida cuando se accede a ella, a pesar de los problemas de demora en la obtención de cita. Las cifras del 50,3%, el 69% o el 75,8% infravaloran esta percepción positiva y no corresponden al dato recogido en el documento. Esta buena valoración contrasta con la peor percepción de la accesibilidad, que es uno de los ejes de mejora del plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a96") }, {"long_answer": "Según los datos que recoge el plan, procedentes de la Encuesta Europea de Salud en España, el sedentarismo en el tiempo libre afecta a alrededor del 40,3% de las mujeres, frente a aproximadamente un 32,3% de los hombres, lo que muestra una diferencia de género relevante para orientar las intervenciones de promoción de la actividad física desde Atención Primaria y la comunidad. El 32,3% corresponde por tanto a los hombres y no a las mujeres. Las cifras del 15,5% y del 23,3% infravaloran claramente la frecuencia de sedentarismo en la población femenina española."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977a9f") }, {"long_answer": "Los datos de actividad recogidos en el plan muestran que la media de consultas ordinarias anuales por habitante en Pediatría de Atención Primaria es de 4,73, una frecuentación que refleja el seguimiento del Programa de Salud Infantil, con sus revisiones y vacunaciones, además de la atención a los procesos agudos propios de la infancia. Las cifras de 5,11 y 6,25 sobrestiman esta frecuentación, y la de 3 consultas por habitante la infravalora respecto al dato del documento. Conocer esta cifra es útil para dimensionar las plantillas de pediatría y enfermería pediátrica en los centros de salud."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aa2") }, {"long_answer": "La línea 9 del plan, dedicada a la investigación en Atención Primaria, propone fortalecerla mediante convocatorias competitivas específicas para profesionales de primaria y la promoción de la investigación cooperativa en red, que permite a los grupos de distintos centros y comunidades colaborar y alcanzar tamaños muestrales y capacidad suficientes. Evitar las convocatorias o reducir el apoyo metodológico y financiero debilitaría la investigación en primaria, cuando el plan pretende justo lo contrario. Concentrar la investigación solo en los hospitales perpetuaría el desequilibrio actual, que deja sin respuesta muchas preguntas relevantes para la práctica en el primer nivel asistencial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aa7") }, {"long_answer": "Antes de 2026, el plan prevé evaluar si las medidas implantadas consiguen reducir las barreras derivadas de la brecha digital en las personas en situación de vulnerabilidad y en las personas mayores, para que el desarrollo de la atención no presencial y de los servicios digitales no excluya a quienes tienen más dificultades de acceso. No se propone suspender las modalidades de atención telefónica y online, que mejoran la accesibilidad para muchas personas. Desarrollar aplicaciones exclusivas para jóvenes no responde al problema de la brecha digital, y la dispersión de servicios sin criterios comunes es precisamente lo que el plan quiere evitar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aad") }, {"long_answer": "El sistema para identificar potenciales colaboradores entre distintas áreas sanitarias y comunidades autónomas tiene como propósito potenciar sinergias entre investigadores de Atención Primaria y fortalecer líneas de investigación con equipos multidisciplinares, de manera que grupos pequeños o aislados puedan unirse a otros con intereses comunes y abordar proyectos de mayor alcance. No pretende minimizar las colaboraciones internacionales, que el plan también promueve. Tampoco busca reducir el número de equipos de investigación ni concentrar la investigación en un único centro, ya que el objetivo es ampliar y conectar la actividad investigadora distribuida por el territorio."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aba") }, {"long_answer": "La participación de investigadores clínicos de Atención Primaria en la Acción Estratégica en Salud se evalúa mediante el incremento del número de grupos de investigación que incluyen profesionales de primaria en su equipo, desglosado por comunidad autónoma y por sexo, lo que permite valorar tanto la extensión territorial como la perspectiva de género. La exclusión de profesionales de primaria sería lo contrario de lo que se pretende fomentar. El número de puestos administrativos creados no mide la participación investigadora, y la reducción de sesiones clínicas no guarda relación con este indicador ni con los objetivos de la línea de investigación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977abb") }, {"long_answer": "Las medidas para reducir las barreras digitales en el acceso a la atención sanitaria priorizan a los colectivos en situación de vulnerabilidad y a las personas de edad avanzada, ya que son quienes tienen más dificultades para utilizar herramientas como la cita online, la teleconsulta o la carpeta de salud, y por tanto quienes podrían quedar excluidos de la atención no presencial. Los adultos jóvenes urbanos y los profesionales sanitarios experimentados suelen disponer de buenas competencias digitales, por lo que no son el foco de estas medidas. Los niños en edad escolar acceden a la atención a través de sus familias y no constituyen el colectivo prioritario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977abe") }, {"long_answer": "La actualización anual del mapa de situación de la I+D en Atención Primaria se realiza en el Instituto de Salud Carlos III, el organismo público de investigación que gestiona la Acción Estratégica en Salud y coordina gran parte de la investigación biomédica del SNS, por lo que dispone de la información y las estructuras necesarias para elaborar y mantener ese mapa. No lo elabora el Ministerio de Sanidad de forma aislada, sino en colaboración con el ISCIII y las comunidades autónomas. Tampoco corresponde a organismos sin relación con la sanidad ni a centros privados de investigación, ya que se trata de una herramienta de planificación pública."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ac1") }, {"long_answer": "Para evaluar la promoción de consultas y colaboraciones entre investigadores en 2026 y 2027, el ISCIII utiliza como indicadores el número de consultas realizadas y el número de estancias formativas llevadas a cabo por profesionales de distintas instituciones, ya que reflejan directamente el intercambio de conocimiento y la movilidad de los investigadores de Atención Primaria. El número de proyectos internacionales rechazados no mide la colaboración. El total de publicaciones sin evaluación no se relaciona con esta medida concreta, y el número de sesiones clínicas organizadas es una actividad asistencial y docente, no un indicador de colaboración investigadora."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977acd") }, {"option_3": "Agencia Española de Medicamentos y Productos Sanitarios (AEMPS)", "long_answer": "Las convocatorias para redes de investigación cooperativa específicas, como las redes orientadas a resultados en salud en las que participan grupos de Atención Primaria, se realizan dentro de la Acción Estratégica en Salud, el programa de financiación de la investigación biomédica que gestiona el Instituto de Salud Carlos III. El Ministerio de Sanidad impulsa el plan, pero no es quien publica estas convocatorias de redes. La AEMPS es la agencia reguladora de medicamentos y productos sanitarios y no financia redes de investigación cooperativa, y RedETS es la red de agencias de evaluación de tecnologías sanitarias, sin función de convocatoria de redes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ace") }, {"long_answer": "La tasa de éxito anual de la convocatoria de intensificación de la actividad investigadora de la Acción Estratégica en Salud para profesionales de Atención Primaria se mide como el número de profesionales a los que se concede financiación dividido entre el total de profesionales de primaria que la solicitan. Así se valora si la convocatoria permite efectivamente a los profesionales liberar tiempo asistencial para investigar. El número de proyectos presentados mide la demanda pero no el éxito, y el número de congresos y el porcentaje de participantes en cursos de salud comunitaria corresponden a otros ámbitos del plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ad4") }, {"long_answer": "El Ministerio de Sanidad ofrece Localiza Salud, un mapa de recursos comunitarios para la salud que permite a la ciudadanía y a los profesionales localizar actividades y recursos de su entorno, como grupos de caminata, talleres o asociaciones, que favorecen la salud y el bienestar. Es una herramienta clave de la recomendación de activos para la salud desde Atención Primaria. No es una plataforma de telemonitorización avanzada ni un registro nacional de profesionales de primaria, y tampoco tiene relación con la certificación profesional, ya que su función es dar visibilidad a los recursos comunitarios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ae0") }, {"long_answer": "En la Línea 1, dentro de la atracción y fidelización del talento en Atención Primaria, el plan contempla la monitorización de las ofertas de empleo con un seguimiento anual, de manera que se conozca qué plazas se ofertan, en qué condiciones y con qué grado de cobertura, y puedan adoptarse medidas para hacerlas más atractivas, especialmente en las plazas de difícil cobertura. Reducir las horas de formación especializada empeoraría la preparación de los profesionales. Eliminar sin excepción todos los contratos temporales no es la acción planteada, e incentivar la salida masiva de jóvenes a otros ámbitos es precisamente lo contrario de fidelizar el talento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ae5") }, {"long_answer": "Según el Acuerdo 1411 del Consejo Interterritorial del SNS, el resultado esperado para 2026 es que al menos el 40% de las comunidades autónomas hayan implantado programas de detección temprana de la violencia de género en Atención Primaria utilizando el instrumento estandarizado común. Se trata de un objetivo intermedio que busca extender progresivamente la detección precoz homogénea en todo el SNS. Los porcentajes del 60%, el 80% y el 90% no corresponden a la meta fijada para ese año, ya que el plan plantea una implantación progresiva del instrumento en las distintas comunidades autónomas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ae6") }, {"long_answer": "El Grupo Motor de formadoras y formadores en violencia de género del SNS está integrado por profesionales de Atención Primaria, de Salud Mental y de la atención al embarazo, parto y puerperio, ya que son los ámbitos en los que es más frecuente la detección y el abordaje de la violencia de género y en los que la formación específica tiene mayor impacto. Restringirlo solo a Atención Primaria o solo a Salud Mental dejaría fuera ámbitos esenciales como la atención obstétrica, en la que el embarazo es un periodo de especial riesgo. Los médicos hospitalarios y farmacéuticos no son los perfiles que definen este grupo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ae7") }, {"long_answer": "El plan prevé que en 2026 el Grupo Motor de formadoras y formadores del SNS en violencia de género cuente con 120 profesionales, que actuarán como multiplicadores de la formación en sus comunidades autónomas y centros, siguiendo un modelo de formación de formadores que permite extender la capacitación a un gran número de profesionales. Las cifras de 60 y 80 no alcanzan el objetivo fijado, y la de 200 lo supera, por lo que ninguna corresponde a la meta establecida para ese año en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ae8") }, {"long_answer": "En el marco del Plan Estratégico Nacional para la Reducción de la Obesidad Infantil, desde Atención Primaria se propone promover y apoyar la lactancia materna siguiendo las recomendaciones de la Iniciativa para la Humanización de la Asistencia al Nacimiento y la Lactancia (IHAN), ya que la lactancia materna es un factor protector frente al exceso de peso en la infancia. Imponer la lactancia artificial en casos complejos contradice estas recomendaciones, que priorizan el apoyo a la lactancia materna. Reducir los programas de lactancia iría en contra del objetivo, y la IHAN se aplica tanto en hospitales como en centros de salud."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aeb") }, {"long_answer": "En materia de gobernanza, el plan prevé consensuar en el Consejo Interterritorial del SNS, antes de 2027, recomendaciones que vinculen el crecimiento del gasto sanitario público total con el incremento presupuestario destinado a Atención Primaria, de forma que primaria no pierda peso en el conjunto del gasto sanitario y pueda reforzarse progresivamente. Los nuevos criterios para acreditar centros de salud no son la medida de gobernanza a la que se refiere esta acción. Un plan de reducción de plantillas iría en contra del refuerzo de la Atención Primaria, y las estrategias de reducción del gasto farmacéutico corresponden a otros ámbitos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aec") }, {"long_answer": "El resultado esperado de las recomendaciones del Consejo Interterritorial sobre la vinculación entre el gasto sanitario público y el presupuesto de Atención Primaria es que el 100% de las comunidades autónomas implementen el acuerdo, ya que se trata de una medida estructural de financiación cuyo objetivo es garantizar que todas destinen a primaria un crecimiento presupuestario acorde con el del gasto total. Las metas del 80%, el 50% o el 20% supondrían aceptar que parte del territorio quedara fuera de la medida, lo que generaría desigualdades entre comunidades contrarias a la equidad que persigue el plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aef") }, {"long_answer": "Para finales de 2027, el plan establece como resultado esperado la evidencia de la existencia de un entorno público en el que se presenten los indicadores de Atención Primaria y se pueda realizar benchmarking, es decir, comparar los resultados entre territorios y centros para aprender de las mejores prácticas y favorecer la transparencia y la rendición de cuentas. Un informe preliminar en 2026 o una plataforma digital en 2025 no son el resultado fijado para este indicador, y afirmar que no está definido contradice el plan, que establece claramente este entorno público como meta al final de su periodo de vigencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977af1") }, {"long_answer": "El plan fija que, para 2027, al menos el 80% de las comunidades autónomas hayan evaluado las necesidades de salud de su población a nivel de Zona Básica de Salud, ya que conocer las necesidades en ese nivel territorial permite planificar los recursos de forma ajustada y orientar la actividad comunitaria según los determinantes y problemas de salud de cada zona. Un 30% o un 50% supondrían una meta poco ambiciosa para el horizonte del plan, y un 100% no es el porcentaje establecido para este indicador, que deja cierto margen dada la complejidad de realizar este análisis en todas las zonas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977af5") }, {"long_answer": "El plan establece que, antes de 2026, el 100% de las comunidades autónomas hayan realizado un mapeo de los canales de comunicación existentes entre los órganos decisores y la comunidad, como paso necesario para favorecer la participación ciudadana en la planificación y la gestión de la Atención Primaria y la salud comunitaria. Se trata de una acción básica de diagnóstico, por lo que se espera que la lleven a cabo todas las comunidades. Los porcentajes del 75%, el 50% o el 20% supondrían que una parte del territorio no dispondría de esa información de partida para impulsar la participación comunitaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977af9") }, {"long_answer": "El plan establece que el 100% de las comunidades autónomas publiquen una hoja de ruta para la implantación del marco de coordinación sociosanitaria antes del 31 de diciembre de 2027, coincidiendo con el final de su periodo de vigencia, 2025-2027. Este marco busca coordinar los servicios sanitarios y sociales para atender a personas con necesidades complejas, como la dependencia o la cronicidad avanzada. Las fechas de 2024 y 2025 son anteriores o coinciden con el inicio del plan, por lo que no permitirían su elaboración, y la de 2026 no es el plazo fijado para que todas las comunidades la publiquen."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977afd") }, {"long_answer": "En el contexto de la mejora de la continuidad asistencial y la gestión de casos, el plan define como paciente vulnerable a la persona con mayor riesgo por su estado de salud, su red social, su edad o factores sociales y económicos, que requiere un seguimiento coordinado entre niveles asistenciales y servicios sociales, frecuentemente liderado por la enfermera gestora de casos. No se limita a pacientes con enfermedades terminales, ya que incluye personas con cronicidad compleja, fragilidad o exclusión social. Tampoco se restringe a pacientes jóvenes sin apoyo social, y no puede referirse a personas sin patologías ni necesidades asistenciales, que no requieren gestión de casos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977aff") }, {"long_answer": "En el modelo de colaboración entre Atención Primaria y Salud Mental, el médico o médica de familia mantiene el papel de principal responsable del tratamiento del paciente, con el apoyo y asesoramiento de los profesionales de salud mental, a través de interconsultas, sesiones conjuntas o consultoría. Así se garantiza la longitudinalidad y una atención integral que tiene en cuenta también la salud física y el contexto familiar. No se limita a suministrar medicamentos ni a derivar casos de forma pasiva, ya que participa activamente en el diagnóstico y el seguimiento, y no carece de responsabilidad en el manejo clínico, sino que la asume directamente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b06") }, {"long_answer": "El plan prevé que, para 2027, el número de comunidades autónomas que cuentan con modelos de optimización de la terapia farmacológica con participación de los farmacéuticos de Atención Primaria aumente al menos un 50%, con el objetivo de mejorar la seguridad y la adecuación del tratamiento, especialmente en pacientes polimedicados y con enfermedades crónicas. Un incremento del 20% sería una meta inferior a la fijada. No prever incremento, o reducir estos modelos un 10%, contradice el impulso que el plan da a la participación de los farmacéuticos de primaria en la revisión y conciliación de la medicación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b0f") }, {"long_answer": "La Alianza para la Estrategia tiene como objetivo principal reunir a los agentes públicos y privados del ecosistema farmacéutico, como Administraciones, comunidades autónomas, industria, profesionales, pacientes y academia, para debatir y garantizar que las políticas se orienten a las necesidades de salud y a soluciones concretas. No busca centralizar la producción en grandes corporaciones, ya que el ecosistema incluye también pymes y centros de investigación. Tampoco pretende excluir a las comunidades autónomas, que tienen competencias clave en la gestión sanitaria, ni aumentar la burocracia, sino crear un espacio de diálogo y colaboración."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b10") }, {"long_answer": "La Estrategia considera las enfermedades raras un área terapéutica estratégica porque, aunque cada una afecta a pocas personas, en conjunto afectan a millones de personas en Europa, sufren con frecuencia un importante retraso diagnóstico y la mayoría carece de tratamiento específico, lo que genera una gran carga de enfermedad y sufrimiento. La cronicidad es un reto por su elevada prevalencia, no por la falta de tratamientos o el retraso diagnóstico. Las terapias avanzadas y la medicina personalizada de precisión son herramientas o enfoques terapéuticos, que pueden aplicarse precisamente a las enfermedades raras, pero no son el área definida por estos rasgos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b11") }, {"long_answer": "El reposicionamiento terapéutico consiste en encontrar nuevas indicaciones para medicamentos ya conocidos, autorizados o en desarrollo. Como ya se dispone de datos de seguridad, farmacocinética y fabricación, permite acelerar el acceso a tratamientos eficaces y reducir costes y tiempos de desarrollo frente a la investigación de nuevas moléculas, por lo que la Estrategia lo promueve, sobre todo en enfermedades raras. No se basa en invertir exclusivamente en nuevos descubrimientos moleculares, ya que parte de fármacos existentes. Tampoco elimina la colaboración entre academia e industria, sino que suele apoyarse en ella, ni se limita a los medicamentos genéricos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b14") }, {"long_answer": "La Estrategia describe las terapias avanzadas, como la terapia génica, la terapia celular y la ingeniería tisular, como revolucionarias porque actúan sobre las causas moleculares y celulares profundas de la enfermedad y pueden ofrecer curaciones duraderas o un control prolongado de enfermedades graves, muchas de ellas sin otra alternativa terapéutica. No es cierto que sean fáciles de producir ni de bajo coste: su fabricación es muy compleja y su precio elevado, lo que plantea retos de sostenibilidad. Tampoco se centran en enfermedades infecciosas, sino en cáncer, enfermedades raras o genéticas, y no se usan de forma masiva en patologías comunes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b15") }, {"long_answer": "Para garantizar la sostenibilidad del gasto farmacéutico, la Estrategia establece que su crecimiento no supere la tasa de referencia de crecimiento del PIB a medio plazo de la economía española prevista en la Ley Orgánica 2/2012, de Estabilidad Presupuestaria y Sostenibilidad Financiera, que es la regla de gasto de las Administraciones públicas. El crecimiento del gasto hospitalario no es un referente adecuado, ya que el gasto farmacéutico forma parte de él. La inflación prevista por el Banco Central Europeo y el crecimiento demográfico no son los indicadores fijados en el marco legal de estabilidad presupuestaria al que se remite la Estrategia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b1b") }, {"long_answer": "En la gobernanza de la Estrategia, las patronales del sector, como Farmaindustria o la Asociación Española de Medicamentos Genéricos (AESEG), participan principalmente a través de la comisión técnica interministerial y del Comité Mixto Ministerios-Industria, espacios de diálogo técnico y de coordinación entre la Administración y la industria. Su participación no se limita a las decisiones de financiación pública, que corresponden a los órganos competentes de la Administración. Tampoco se reduce a la promoción comercial, que no forma parte de la Estrategia, ni se canaliza a través de organismos internacionales de la UE, ya que se trata de una estrategia nacional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b1c") }, {"long_answer": "El eje transversal de la Estrategia de la Industria Farmacéutica es la orientación pública basada en las necesidades en salud de la población y en la seguridad nacional, que actúa como criterio común para todas las líneas de actuación: investigación, producción, acceso y sostenibilidad. No se trata de promover exclusivamente las terapias avanzadas, que son solo un área prioritaria entre otras. Tampoco es el aumento del apoyo a los genéricos, que es una medida concreta de sostenibilidad, ni la reducción de la participación del sector privado, cuando la Estrategia se basa precisamente en la alianza público-privada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b1e") }, {"long_answer": "La Estrategia considera que la colaboración entre academia e industria es clave en el desarrollo farmacéutico, porque los descubrimientos de universidades y centros de investigación necesitan la capacidad de desarrollo, producción y comercialización de la industria para llegar a los pacientes, y esta colaboración impulsa innovaciones y reposicionamientos terapéuticos. Por tanto, no son sectores independientes sin interacción. Tampoco se propone sustituir la innovación pública por la privada, ya que ambas son complementarias, y afirmar que la industria solo comercializa sin vinculación académica ignora el papel que desempeña en la investigación y en los ensayos clínicos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b20") }, {"long_answer": "El Comité Mixto Ministerios-Industria es el órgano de la gobernanza de la Estrategia encargado de coordinar su desarrollo entre el sector público, representado por los ministerios implicados, y la industria farmacéutica, a través de sus asociaciones, permitiendo el seguimiento conjunto de las medidas y la resolución de dificultades. No decide sobre precios sin considerar a la industria, ya que la fijación de precios corresponde a la Comisión Interministerial de Precios de los Medicamentos. Tampoco regula exclusivamente los genéricos ni gestiona la compra pública de medicamentos, que son competencias de otros órganos y Administraciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b25") }, {"question": "Según la gobernanza descrita en la Estrategia de la Industria Farmacéutica, ¿cuál de los siguientes ministerios NO participa en ella?", "option_2": "Ministerio de Sanidad", "long_answer": "El Ministerio de Cultura y Deporte no forma parte de la gobernanza de la Estrategia de la Industria Farmacéutica, ya que carece de competencias en materia de medicamentos, investigación biomédica o política industrial. En cambio, la Estrategia se articula en torno a los ministerios con responsabilidad directa en el sector: el Ministerio de Sanidad, competente en regulación, financiación y acceso a los medicamentos; el Ministerio de Ciencia, Innovación y Universidades, responsable de la investigación y la innovación; y el Ministerio de Industria y Turismo, encargado de la política industrial y del refuerzo de la capacidad productiva."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b28") }, {"long_answer": "Según la Estrategia, durante la pandemia de COVID-19 el sector farmacéutico demostró su carácter estratégico al desarrollar capacidades de fabricación y garantizar el suministro de medicamentos críticos, incluida la participación en la producción de vacunas y tratamientos, lo que puso de relieve la importancia de la autonomía estratégica. No disminuyó la producción, sino que tuvo que aumentarla para responder a la demanda. Tampoco redujo la inversión en I+D, que fue clave para el rápido desarrollo de vacunas, ni se centró exclusivamente en la exportación desatendiendo el mercado nacional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b29") }, {"long_answer": "El Comité Interministerial es el órgano encargado de gobernar la Estrategia de la Industria Farmacéutica y de realizar su seguimiento, coordinando a los ministerios implicados y velando por la ejecución de sus medidas, con el apoyo de la Alianza para la Estrategia como espacio de participación de los agentes públicos y privados. No regula exclusivamente la investigación clínica, que es solo una de las áreas de la Estrategia. Tampoco controla directamente el gasto farmacéutico de las comunidades autónomas, que tienen sus propias competencias de gestión, ni gestiona la producción de genéricos, que corresponde a las empresas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b2a") }, {"long_answer": "La Estrategia destaca que España es el cuarto mercado farmacéutico de la Unión Europea y el noveno a nivel mundial, lo que refleja su peso internacional como mercado y como destino de inversión, especialmente en investigación clínica. No es cierto que tenga el empleo directo más bajo de Europa, ya que la industria farmacéutica genera en España un volumen importante de empleo de calidad. Tampoco es el mayor exportador mundial de productos farmacéuticos, y afirmar que no participa en ensayos clínicos internacionales es falso, porque España es uno de los países líderes de Europa en número de ensayos clínicos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b38") }, {"long_answer": "La Estrategia impulsa un ecosistema farmacéutico integral que abarca la innovación, la producción, el acceso a los medicamentos y la sostenibilidad del sistema, entendiendo que estos elementos están interrelacionados: la investigación debe traducirse en producción y en acceso de los pacientes, de forma compatible con la sostenibilidad del SNS. Limitarse a la producción y la distribución dejaría fuera la investigación y el acceso. Considerar el acceso sin tener en cuenta la sostenibilidad pondría en riesgo el sistema público, y una investigación aislada sin integración con la producción es precisamente el modelo fragmentado que la Estrategia pretende superar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b40") }, {"long_answer": "El documento de la Estrategia se centra en el sector farmacéutico y lo presenta como un sector estratégico para la economía, la salud y la seguridad, pero no menciona ningún otro sector industrial concreto como el más fundamental para la economía. Por ello la opción correcta es que no se menciona específicamente otro sector. Los sectores automovilístico, energético o agroalimentario tienen un peso relevante en la economía española, pero la Estrategia no los compara ni los destaca como sectores fundamentales, ya que su objeto es exclusivamente la industria farmacéutica y su ecosistema."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b41") }, {"long_answer": "La Estrategia destaca que el empleo generado por la industria farmacéutica en España es de alta calidad, muy cualificado, con una elevada proporción de contratos indefinidos, y con una notable igualdad y diversidad, incluyendo una alta presencia de mujeres también en puestos de investigación y dirección. Por tanto, no es un empleo predominantemente no cualificado y temporal. Tampoco se centra en el personal administrativo, ya que una parte importante corresponde a investigación, producción y calidad, y es incorrecto afirmar que se concentra en la producción sin relación con la I+D, sector en el que la industria farmacéutica es una de las que más invierte."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b45") }, {"long_answer": "Según los datos de la Estrategia, en 2023 España exportó productos farmacéuticos por valor de unos 21.900 millones de euros e importó por valor de unos 24.800 millones, de modo que la balanza comercial fue ligeramente negativa, lo que pone de manifiesto la relevancia del sector exportador y, a la vez, cierta dependencia exterior que la Estrategia quiere reducir. Una balanza negativa de 50.000 millones no se corresponde con estos datos. La exportación no se limita a medicamentos genéricos ni existe ausencia de importaciones, y tampoco se ha bloqueado la importación, algo incompatible con el mercado único europeo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b47") }, {"long_answer": "El Reglamento (UE) 2021/2282 sobre evaluación de tecnologías sanitarias establece un marco común para la evaluación clínica conjunta a escala de la Unión, con un mecanismo único para que los desarrolladores presenten la información clínica una sola vez a nivel europeo, evitando duplicidades entre Estados. No regula los aspectos no clínicos, como los económicos, organizativos o éticos, que siguen siendo competencia nacional. Tampoco garantiza la financiación de los medicamentos en todos los Estados miembros, ya que cada país decide sobre precio y financiación, ni define los criterios económicos para fijar los precios, materia que queda fuera de su ámbito."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b48") }, {"option_2": "Realización de consultas científicas conjuntas con los desarrolladores", "long_answer": "Con el Reglamento europeo de evaluación de tecnologías sanitarias, la evaluación clínica pasa a realizarse de forma conjunta a escala de la UE, mientras que la evaluación de los aspectos no clínicos, como los económicos, el impacto presupuestario, los organizativos, éticos o sociales, queda regulada únicamente por las competencias nacionales, ya que está ligada a las decisiones de precio y financiación de cada Estado. La evaluación clínica, las consultas científicas conjuntas con los desarrolladores y la presentación de pruebas por parte de estos a escala europea son elementos regulados por el Reglamento y, por tanto, no son competencia exclusivamente nacional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b49") }, {"long_answer": "La Estrategia propone modificar el artículo 92 de la Ley de Garantías y Uso Racional de los Medicamentos para clarificar las reglas de pago y gratuidad aplicables al uso compasivo y a otros usos en situaciones especiales de medicamentos aún no autorizados, de modo que quede claro en qué condiciones el suministro es gratuito para el sistema y cuándo debe abonarse. No pretende permitir la financiación acelerada antes de la autorización, ya que la financiación requiere que el medicamento esté autorizado. Tampoco busca fijar precios fijos para genéricos y biosimilares, ni obligar a las compañías a ceder sus datos clínicos a la Administración."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b4a") }, {"long_answer": "Para mejorar la interacción entre las compañías farmacéuticas y la Administración en las fases tempranas, la Estrategia propone sistematizar el diálogo temprano (early dialogue), un procedimiento estructurado en el que las compañías pueden consultar a las autoridades sobre el diseño de los estudios y la evidencia que se requerirá para la evaluación y la financiación, lo que reduce la incertidumbre y agiliza el acceso. No se plantea crear un comité consultivo independiente ni otorgar subsidios a compañías en fase preclínica como mecanismo de interacción. Tampoco se propone eliminar los procesos de autorización, que son garantías de calidad, seguridad y eficacia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b4f") }, {"long_answer": "Fomentar el uso de medicamentos genéricos y biosimilares tiene como objetivo mejorar el acceso de los pacientes a tratamientos de eficacia y seguridad equivalentes a precios más bajos, y contribuir a la sostenibilidad del sistema sanitario, liberando recursos que pueden destinarse a la incorporación de medicamentos innovadores. Incrementar la exclusión de los genéricos de la financiación pública iría en contra de ese objetivo. Eliminar los incentivos a los biosimilares reduciría su penetración y la competencia, y centralizar toda la compra pública en un único organismo europeo no es una medida contemplada en la Estrategia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b53") }, {"long_answer": "Según la Estrategia, alrededor del 44% de la inversión en I+D de las compañías farmacéuticas en España se destina a proyectos realizados en colaboración con hospitales, institutos de investigación sanitaria y otros centros públicos, lo que muestra la estrecha relación entre la industria y el sistema sanitario y la fortaleza del SNS como entorno de investigación clínica. El 30% infravalora esta colaboración, mientras que el 60% y el 75% la sobrestiman respecto al dato recogido en el documento. Esta cifra refuerza la importancia de los hospitales públicos en el ecosistema de investigación farmacéutica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b55") }, {"long_answer": "En la Estrategia, la Acción Estratégica en Salud del Instituto de Salud Carlos III es el instrumento que coordina y financia las líneas prioritarias de investigación, incluidos la investigación clínica independiente y los programas preclínicos, en colaboración con los institutos de investigación sanitaria, las redes y las plataformas de apoyo. Su financiación no se dirige exclusivamente a la investigación preclínica privada, ya que es un programa público con convocatorias abiertas a centros del SNS y universidades. No evalúa biosimilares para su financiación, competencia de la Administración sanitaria, ni regula el precio de los medicamentos, que corresponde a la Comisión Interministerial de Precios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b57") }, {"long_answer": "La Estrategia destaca que España es un país de referencia en investigación clínica en fases tempranas y en ensayos first in human gracias a la calidad de los profesionales y de las infraestructuras del SNS, con unidades de fase I acreditadas y una regulación ágil, lo que la sitúa entre los países líderes de Europa en número de ensayos. Por tanto, no es cierto que su regulación sea rígida y limitada en este ámbito. Tampoco se excluye la participación del sector privado, que promueve la mayoría de estos ensayos, y la valoración internacional del ecosistema español es alta, no baja."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b5c") }, {"long_answer": "Para impulsar los ensayos clínicos descentralizados, la Estrategia incluye iniciativas como la monitorización remota de los pacientes, el consentimiento informado electrónico y la entrega a domicilio de los medicamentos en investigación, que reducen los desplazamientos, facilitan la participación de pacientes alejados de los grandes centros y mejoran la diversidad de las poblaciones incluidas. Limitar los ensayos a grandes hospitales urbanos es lo contrario de la descentralización. Eliminar la participación de la enfermería no tendría sentido, ya que es clave en el seguimiento de los participantes, y centralizar la inscripción en un único centro estatal tampoco corresponde a este modelo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b5d") }, {"long_answer": "La Estrategia de la Industria Farmacéutica define el Espacio Nacional de Datos en Salud como un sistema federado e interoperable con el Espacio Europeo de Datos de Salud, cuyo fin es facilitar el uso secundario de datos sanitarios de vida real para la investigación, la innovación y la toma de decisiones regulatorias y de salud pública. No es una base de datos exclusiva de hospitales privados, ya que integra información del conjunto del sistema; tampoco persigue únicamente acelerar la comercialización de medicamentos, ni tiene relación con el registro de donantes de órganos, que se gestiona por otras vías."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b62") }, {"long_answer": "La Estrategia propone revisar el porcentaje de aportación que la industria realiza sobre las ventas de medicamentos financiados por el SNS incorporando criterios adicionales, entre ellos el impacto ambiental y la huella de carbono de la producción, en coherencia con el objetivo de sostenibilidad medioambiental del sector. El coste del envase y del marketing no se plantea como criterio de modulación, el volumen de ventas ya es la base de cálculo de la aportación y no un criterio adicional, y la opinión de las asociaciones de pacientes no forma parte de este mecanismo económico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b63") }, {"long_answer": "Para los medicamentos que aún no tienen autorización de comercialización, la Estrategia prevé que su acceso y financiación se canalicen a través de los procedimientos regulados del Real Decreto 1015/2009 sobre medicamentos en situaciones especiales (uso compasivo, acceso a medicamentos no autorizados en España y uso fuera de ficha técnica), con las modificaciones que se introduzcan. No se plantea prohibir su uso, pues estos cauces existen precisamente para pacientes sin alternativas; tampoco se garantiza una financiación automática de todos ellos, ni se limita el acceso al uso compasivo sin evaluación ni seguimiento posterior."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b69") }, {"long_answer": "CERTERA, el Consorcio Estatal en Red para el desarrollo de Medicamentos de Terapias Avanzadas, está coordinado por el Instituto de Salud Carlos III, organismo que impulsa la investigación biomédica pública y que articula esta red de centros para acelerar el desarrollo académico de terapias avanzadas como CAR-T o terapias génicas. El Ministerio de Sanidad participa en la regulación y financiación de los medicamentos, pero no coordina el consorcio; el CDTI apoya la innovación empresarial, y la Comisión Europea actúa en el ámbito comunitario, no en la gestión de una red estatal española."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b73") }, {"long_answer": "El programa formativo dirigido a asociaciones y escuelas de pacientes sobre investigación y desarrollo de medicamentos incluye contenidos sobre el valor de compartir datos de salud para la investigación y su impacto en la mejora de la salud y la innovación, con el objetivo de fomentar una participación informada de los pacientes. No pretende capacitarles para prescribir medicamentos, competencia reservada a los profesionales habilitados; obviamente no enseña a fabricar terapias avanzadas de forma casera, y su enfoque no es meramente administrativo, ya que el uso de los datos es precisamente un eje central."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b7a") }, {"long_answer": "El Fondo de Coinversión (FOCO), gestionado por COFIDES, tiene como objetivo atraer y movilizar recursos de inversores extranjeros para coinvertir en proyectos productivos de empresas españolas en sectores estratégicos, entre ellos el farmacéutico, reforzando su capacidad industrial y su competitividad. No se concentra en empresas públicas, sino que se dirige principalmente a compañías privadas; no busca reducir la entrada de capital extranjero, sino justo lo contrario, y tampoco se limita a financiar investigación académica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b7d") }, {"long_answer": "La propuesta de Ley de Medicamentos Críticos de la Unión Europea pretende establecer medidas políticas que refuercen la producción en territorio europeo, la diversificación de proveedores y la transparencia de las cadenas de suministro de los medicamentos considerados críticos, con el fin de prevenir desabastecimientos. No contempla prohibir las exportaciones a terceros países, no favorece monopolios, ya que precisamente busca diversificar el suministro, y tampoco elimina las regulaciones sobre fabricación, sino que pretende incentivar la producción local."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b9e") }, {"long_answer": "El Plan de acción para la prevención del suicidio 2025-2027 establece que no todas las acciones se implantan a la vez: el Comité Institucional y el Comité Técnico priorizan qué medidas desarrollar en cada momento en función de su impacto previsto, la evidencia disponible y los recursos existentes. Por ello es incorrecto que todas las acciones se realicen simultáneamente sin jerarquía. Tampoco se limita a intervenciones hospitalarias, ya que abarca atención primaria, comunidad, educación y otros ámbitos, ni se dirige solo a la población general, puesto que contempla también grupos en situación de vulnerabilidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ba3") }, {"long_answer": "La restricción del acceso a medios letales, como determinados fármacos o lugares de riesgo (puentes, edificios elevados, vías férreas), es una intervención estructural con sólida evidencia en la prevención del suicidio, porque reduce la letalidad y gana tiempo en el momento de crisis. Las terapias individuales obligatorias sin seguimiento comunitario no constituyen una medida estructural ni están recomendadas; las campañas sin evidencia científica pueden ser ineficaces o incluso contraproducentes, y aumentar el uso de ansiolíticos en población general incrementaría la disponibilidad de medios potencialmente letales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ba7") }, {"long_answer": "La guía de práctica clínica sobre extracción de hemocultivos recomienda utilizar guantes estériles durante el procedimiento, ya que su uso se asocia a una menor tasa de contaminación de las muestras, especialmente si es necesario palpar de nuevo la vena tras la antisepsia de la piel. Los guantes no estériles, sean de látex o de nitrilo, no garantizan la ausencia de microorganismos en la zona de contacto y se asocian a más contaminaciones. No usar guantes es incorrecto, pues aumenta la contaminación y el riesgo de exposición del profesional a fluidos biológicos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ba9") }, {"long_answer": "En pacientes mayores de dos meses, la guía recomienda desinfectar la piel con clorhexidina al 2% en solución alcohólica aplicada mediante fricción y dejándola secar antes de la punción, ya que combina el efecto rápido del alcohol con la acción residual de la clorhexidina y ha demostrado menores tasas de contaminación que la povidona yodada. La povidona yodada al 10% es menos eficaz y requiere más tiempo de secado. El alcohol solo carece de efecto residual, y la clorhexidina acuosa al 1% no es la concentración ni la formulación recomendadas en este grupo de edad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bae") }, {"long_answer": "La guía desaconseja extraer hemocultivos a través de catéteres venosos periféricos insertados previamente, porque su conexión y su luz pueden estar colonizadas y aumentan la tasa de contaminación. Solo se acepta obtener la muestra de un catéter periférico en el mismo momento de su inserción, cuando aún no ha sido manipulado. Por ello es incorrecto hacerlo siempre para ahorrar punciones, limitarlo a la población pediátrica o permitirlo si la vía tiene menos de 24 horas, ya que el riesgo de contaminación aparece desde la primera manipulación del dispositivo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977baf") }, {"long_answer": "Cuando los hemocultivos se obtienen a través de un catéter venoso central, la guía recomienda no desechar la primera porción de sangre extraída, porque descartarla no reduce la contaminación de forma demostrada y, además, esa sangre refleja mejor la posible colonización del catéter, lo que es útil para diagnosticar bacteriemia asociada al mismo. Por tanto, son incorrectas las opciones que proponen descartar 5 o 10 ml de forma sistemática, así como la que limita el desecho a los pacientes críticos, ya que la recomendación es aplicable con independencia de la gravedad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bb2") }, {"long_answer": "En adultos, el lugar de elección para obtener hemocultivos es una vena antecubital de la extremidad superior mediante venopunción directa, porque permite un buen volumen de sangre, una antisepsia adecuada y menor riesgo de contaminación que los dispositivos ya insertados. Las venas del dorso de la mano son de menor calibre y dificultan obtener el volumen necesario. Las venas de las extremidades inferiores se asocian a mayor riesgo de contaminación y de complicaciones trombóticas, y los catéteres intravenosos permanentes aumentan la probabilidad de falsos positivos por colonización."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bb3") }, {"long_answer": "En adultos se recomienda extraer al menos dos sets de hemocultivos, cada uno formado por un frasco aerobio y otro anaerobio, obtenidos preferentemente de punciones distintas. Así aumenta la sensibilidad para detectar la bacteriemia y se facilita distinguir un verdadero patógeno de un contaminante de la piel, que suele aparecer en un solo set. Una única muestra es insuficiente e impide esa interpretación. Tres sets no son la norma rutinaria, aunque pueden valorarse en situaciones concretas como la endocarditis, y extraer una muestra por cada pico febril no es un criterio recomendado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bb5") }, {"long_answer": "El momento idóneo para extraer hemocultivos ante la sospecha de sepsis es antes de iniciar el tratamiento antibiótico, siempre que ello no retrase su administración, porque los antibióticos reducen de forma significativa la probabilidad de aislar el microorganismo causal. Extraerlos después de dos dosis o durante la infusión del antibiótico disminuye la rentabilidad diagnóstica y aumenta los falsos negativos. Por ello es incorrecto afirmar que el momento no influye en la calidad del hemocultivo, ya que la exposición previa al antibiótico condiciona claramente el resultado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bb6") }, {"long_answer": "La guía señala que no es necesario esperar un intervalo fijo de 20 o 30 minutos entre la primera y la segunda pareja de hemocultivos: en pacientes graves o con sospecha de sepsis pueden extraerse de forma simultánea o consecutiva, desde puntos de punción distintos, para no demorar el inicio del tratamiento antibiótico. Esperar siempre 30 minutos o al menos una hora no mejora la rentabilidad diagnóstica en la mayoría de bacteriemias y puede retrasar la antibioterapia. Tampoco existe una norma que obligue a esperar específicamente en la población pediátrica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bb7") }, {"long_answer": "Se recomienda obtener cada pareja de hemocultivos de un punto de punción diferente, porque si un contaminante cutáneo se introduce en una muestra es poco probable que se repita en otra obtenida de forma independiente, lo que ayuda a diferenciar contaminación de bacteriemia verdadera. Una única punción para todas las muestras impide esa interpretación aunque la técnica sea correcta. Cambiar de punto no depende de que existan signos de infección local, y el uso de guantes estériles nuevos no sustituye la ventaja diagnóstica de obtener las muestras de sitios distintos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bb8") }, {"long_answer": "Los hemocultivos deben obtenerse antes de iniciar el tratamiento antibiótico, ya que este reduce la probabilidad de crecimiento del microorganismo. En cambio, respecto a los antipiréticos, la guía no establece una recomendación clara, porque no hay evidencia de que su administración previa altere de forma relevante la rentabilidad del cultivo. Extraer las muestras después de los antipiréticos para mejorar la tolerancia no es un criterio basado en la evidencia, hacerlo tras iniciar el antibiótico aumenta los falsos negativos y afirmar que el momento no influye ignora el efecto conocido de los antibióticos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bbb") }, {"long_answer": "El tapón de goma de los frascos de hemocultivo no se considera estéril, aunque esté protegido por una tapa, por lo que debe desinfectarse antes de inocular la muestra. La guía recomienda hacerlo con una toallita estéril impregnada en clorhexidina al 2% en solución alcohólica, frotando unos 15 segundos y dejando secar, para reducir la contaminación. Es falso que no requiera desinfección, y esta no depende del sistema de extracción empleado. La aplicación de alcohol al 70% durante solo 5 segundos es insuficiente para garantizar una desinfección adecuada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bcc") }, {"long_answer": "La Agencia de Protección Ambiental de Estados Unidos (USEPA) ha utilizado tradicionalmente como nivel de acción para viviendas 4 picocurios por litro, que equivalen aproximadamente a 148 Bq/m³; por encima de esa concentración recomienda adoptar medidas de reducción del radón. El valor de 100 Bq/m³ corresponde al nivel de referencia preferente propuesto por la OMS, 300 Bq/m³ es el nivel de referencia de la normativa europea y española, y 200 Bq/m³ fue un nivel utilizado en antiguas recomendaciones europeas para viviendas de nueva construcción, no el de la USEPA."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bd0") }, {"long_answer": "Según las estimaciones recogidas en el Plan Nacional contra el Radón a partir de datos de la OMS, alrededor de un 4% de las muertes por cáncer de pulmón en España se atribuyen a la exposición residencial al radón, lo que lo sitúa como un factor de riesgo relevante tras el tabaco. Las cifras del 10%, 15% o 25% sobrestiman la fracción atribuible para el conjunto del país; la OMS sitúa globalmente el rango entre el 3% y el 14% según el país, y la proporción española se encuentra en la parte baja de ese intervalo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bd1") }, {"long_answer": "Galicia es una de las comunidades con mayor potencial de radón de España por su sustrato geológico granítico, rico en uranio y radio. Los datos recogidos en el Plan Nacional muestran que más del 20% de sus viviendas presentan concentraciones superiores a 200 Bq/m³, una proporción claramente mayor que la media nacional. Las opciones de menos del 5% o alrededor del 10% infravaloran el problema en esta comunidad, mientras que casi el 50% sobrestima la proporción de viviendas que superan ese umbral."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bd6") }, {"long_answer": "El eje estratégico de conocimiento e infraestructura básica del Plan Nacional contra el Radón tiene como finalidad conocer la magnitud real del problema, mediante la cartografía y las mediciones de radón, y garantizar la calidad y fiabilidad de dichas mediciones, base sobre la que se apoyan el resto de actuaciones. La reducción del radón en lugares de trabajo corresponde a otro eje específico; la concienciación pública pertenece al eje de comunicación, y la creación de instrumentos financieros para la rehabilitación se vincula al eje de edificación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bd7") }, {"long_answer": "Para reducir el radón en los edificios existentes, el Plan Nacional contempla, entre otras medidas, fomentar programas de formación dirigidos a los agentes de la construcción, como técnicos, arquitectos y empresas, para que sepan diagnosticar el problema y aplicar soluciones de mitigación. Limitar las medidas a edificios nuevos o a viviendas de construcción reciente es contradictorio con el objetivo de actuar sobre el parque existente. Eliminar el uso de materiales graníticos no es una acción del plan, ya que la principal fuente de radón en interiores es el terreno."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bd9") }, {"long_answer": "En el ámbito laboral, el Plan Nacional prevé formar a los inspectores de la Inspección de Trabajo y Seguridad Social para que puedan valorar adecuadamente el riesgo por radón en los centros de trabajo y comunicar al Consejo de Seguridad Nuclear las situaciones detectadas. Es incorrecto que no intervenga, ya que la ITSS vigila el cumplimiento de la normativa de prevención de riesgos laborales. No le corresponde realizar mediciones directas, que efectúan servicios y laboratorios acreditados, y las sanciones no se deciden solo en función del nivel de radón."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bdc") }, {"long_answer": "La humedad ambiental influye en la concentración de radón porque, cuando el suelo está saturado de agua, los poros quedan ocupados y se dificulta la migración y la exhalación del gas hacia la superficie, de modo que disminuye su paso al interior de los edificios. Por tanto, es falso que no tenga efecto. La disminución de la solubilidad del radón no es el mecanismo descrito, y la humedad no actúa aumentando la presión atmosférica; además, los aumentos de presión atmosférica tienden a reducir la exhalación por un mecanismo distinto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bdd") }, {"long_answer": "La Guía de Seguridad 11.2 del Consejo de Seguridad Nuclear recomienda, para los edificios de nueva construcción, adoptar como objetivo de diseño una concentración de 100 Bq/m³, más exigente que el nivel de referencia general de 300 Bq/m³, ya que en una obra nueva resulta técnica y económicamente sencillo incorporar medidas de protección. Los valores de 200 y 400 Bq/m³ no corresponden a este objetivo de diseño, y 300 Bq/m³ es el nivel de referencia para la concentración media anual en recintos cerrados, no el objetivo para nueva edificación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977be5") }, {"long_answer": "Según los datos recogidos en el Plan para la ampliación de la cartera común de servicios de salud bucodental, la enfermedad periodontal grave afecta aproximadamente al 10% de la población mundial, lo que la convierte en una de las principales causas de pérdida dental en adultos. El 25% y el 45% sobrestiman la prevalencia de la forma grave, y la cifra cercana al 45% se aproxima más a la proporción de población afectada por enfermedades bucodentales en general. Un 5% infravalora la magnitud de este problema."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977be9") }, {"long_answer": "El diagnóstico de situación del Plan muestra que el 71% de las comunidades autónomas incluyen en su cartera los tratamientos por traumatismos en incisivos y caninos permanentes, de modo que es la situación más frecuente aunque no universal. Por ello son incorrectas las opciones que afirman que todas o ninguna de las comunidades cubren estos tratamientos. El 29% corresponde precisamente a la proporción de comunidades que no los ofrecen, por lo que esa opción no describe la situación mayoritaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bef") }, {"long_answer": "En la atención bucodental a embarazadas, el diagnóstico de situación recogido en el Plan señala que la aplicación de flúor tópico se realiza en todas las comunidades autónomas excepto en una. Los consejos para preservar la salud oral del futuro bebé y la exploración clínica son prestaciones básicas que se ofrecen en todas las comunidades, por lo que no cumplen la condición de faltar en una sola. Las tartrectomías, en cambio, no tienen esa implantación casi universal en este colectivo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bf2") }, {"long_answer": "Según el diagnóstico de situación del Plan, las prestaciones de ortodoncia no se ofrecen en ninguna comunidad autónoma a las personas con discapacidad sensorial. En cambio, existen comunidades que sí las contemplan en determinados casos de discapacidad física o psíquica, y la maloclusión secundaria a malformaciones craneofaciales es precisamente una de las situaciones en las que la ortodoncia se presta en algunos territorios y se propone incorporar a la cartera común, por lo que estas opciones no son correctas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bf3") }, {"long_answer": "La finalidad del Plan para la ampliación de la cartera común de servicios de salud bucodental es reforzar la prevención y el tratamiento de los problemas bucodentales, con especial atención a los colectivos prioritarios: población infantil y juvenil, embarazadas, personas con discapacidad y personas con procesos oncológicos del territorio cervicofacial. No incluye tratamientos estéticos, que quedan excluidos de la financiación pública; tampoco se limita a urgencias dentales graves, ni se centra exclusivamente en prótesis o implantes, ya que el eje principal son las actuaciones preventivas y asistenciales básicas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bf4") }, {"long_answer": "Según la Encuesta de Presupuestos Familiares del INE de 2019 recogida en el Plan, la mayor parte del gasto total en salud bucodental en España corresponde al sector privado, es decir, lo financian directamente las familias, debido a la limitada cobertura de la cartera pública en esta área. Por ello es incorrecto afirmar que el gasto público sea mayoritario o que exista un equilibrio entre ambos. Tampoco es cierto que no existan datos, ya que la propia encuesta proporciona información detallada sobre este gasto de los hogares."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bfa") }, {"long_answer": "Para la valoración económica de la atención bucodental a personas con procesos oncológicos del territorio cervicofacial, el Plan asigna un 40% del gasto medio por persona, atendiendo a que estos pacientes requieren principalmente actuaciones preventivas y de tratamiento previas y posteriores a la radioterapia o la quimioterapia, pero no la totalidad de las prestaciones contempladas para otros colectivos. Los porcentajes del 100%, 70% y 25% no corresponden al criterio utilizado en el Plan para este grupo de población."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bfb") }, {"long_answer": "La cartera común de servicios de salud bucodental del SNS excluye expresamente, con carácter general, los tratamientos ortodóncicos, junto con los estéticos y los implantes, salvo las excepciones específicas que se contemplan para determinados colectivos, como las malformaciones craneofaciales. En cambio, la revisión bucodental, la aplicación de flúor tópico y el tratamiento de los procesos agudos odontológicos, como infecciones o extracciones, forman parte de las prestaciones incluidas en la atención bucodental básica, por lo que no pueden considerarse excluidas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c00") }, {"long_answer": "En la ampliación de la cartera común se garantiza que las personas con alteraciones conductuales severas que les impiden colaborar y mantener el autocontrol durante la atención dental reciban los tratamientos necesarios bajo sedación o anestesia general, siguiendo los protocolos establecidos y en el ámbito adecuado, normalmente hospitalario. Ofrecer ortodoncia gratuita no responde a esta necesidad. Limitarse a medidas preventivas domiciliarias dejaría sin tratar la patología existente, y negar cualquier tratamiento supondría una vulneración de la equidad que el Plan pretende corregir."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c01") }, {"long_answer": "Según la propuesta de cartera común, los equipos de salud bucodental de atención primaria realizan actividades diagnósticas, terapéuticas y preventivas, así como de promoción de la salud bucodental, dirigidas a la población asignada y con especial atención a los colectivos prioritarios. No se dedican solo a tratamientos complejos y quirúrgicos, que pueden requerir derivación a otros niveles; no gestionan ni financian clínicas privadas, y su actividad no se desarrolla exclusivamente en hospitales, sino en los centros de atención primaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c03") }, {"long_answer": "Los descendientes de vida corta del radón, como el polonio 218 y el polonio 214, se depositan en el epitelio bronquial y emiten partículas alfa. Estas partículas tienen una alta transferencia lineal de energía, depositan mucha energía en un recorrido muy corto y poseen una elevada eficacia biológica relativa, por lo que producen roturas del ADN difíciles de reparar en las células basales. Su capacidad de penetración es muy baja: no atraviesan la piel. No se dispersan por el sistema circulatorio, y su peligrosidad no se debe a una permanencia prolongada en el organismo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c05") }, {"long_answer": "El radón 222 apenas supone un riesgo directo porque su período de semidesintegración, de unos 3,8 días, es largo en comparación con el tiempo que permanece en los pulmones: la mayor parte del gas inhalado se exhala antes de desintegrarse. El daño procede de sus descendientes de vida corta, partículas sólidas que se depositan en el epitelio bronquial. Es falso que atraviese fácilmente los tejidos, ya que la radiación alfa apenas penetra; tampoco tiene baja capacidad de desintegración en el aire, y no es soluble de forma relevante en el tejido pulmonar.", "option_2": "Su período de semidesintegración (~3,8 días), largo respecto a su permanencia en el pulmón, por lo que se exhala casi completamente antes de desintegrarse", "option_4": "Su elevada solubilidad en el tejido pulmonar"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c08") }, {"long_answer": "Una limitación muy importante de los primeros estudios en mineros fue la falta de un ajuste adecuado por el consumo de tabaco y por la exposición a otros carcinógenos presentes en las minas, como arsénico, sílice o gases diésel, lo que dificultaba atribuir con precisión el exceso de cáncer de pulmón al radón y extrapolar el riesgo a la población general. Sí se realizaron seguimientos prolongados de las cohortes; la población estudiada era fundamentalmente masculina, no femenina, y en general se estimaron las exposiciones a radón, aunque con cierta imprecisión."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c10") }, {"long_answer": "Además del cáncer de pulmón, que es el único efecto con evidencia sólida, el Libro del Radón recoge que algunos estudios han sugerido una posible asociación entre la exposición a radón y otras patologías como el cáncer cerebral, el cáncer de esófago o la enfermedad pulmonar obstructiva crónica, aunque la evidencia es todavía limitada y no concluyente. El cáncer de próstata y el melanoma, la diabetes y la enfermedad de Parkinson, o la hipertensión y el asma infantil no figuran entre las patologías propuestas en relación con este gas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c14") }, {"long_answer": "En el estudio realizado en España con 248 mediciones en distintos lugares de trabajo, las mayores concentraciones de radón se registraron en el sector sanitario, probablemente por las características de algunos edificios, como plantas bajas o semisótanos con escasa ventilación y su ubicación en zonas de alto potencial. Los sectores turístico, administrativo público y educativo presentaron concentraciones inferiores en dicho estudio, aunque todos ellos deben evaluarse cuando se encuentran en zonas de actuación prioritaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c17") }, {"long_answer": "Cuando, a pesar de las medidas de reducción, la concentración de radón en un lugar de trabajo sigue por encima del nivel de referencia de 300 Bq/m³, el empleador debe estimar las dosis efectivas de los trabajadores y, si superan 6 mSv anuales, clasificarlos como trabajadores expuestos y aplicar las medidas de protección radiológica correspondientes, incluida la vigilancia dosimétrica y sanitaria. No es obligatorio cerrar el puesto de trabajo; limitarse a informar al trabajador es insuficiente, y reducir la jornada no es la actuación establecida por la normativa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c20") }, {"long_answer": "Según la publicación 137 de la ICRP, la dosis efectiva anual por radón se calcula multiplicando el tiempo de exposición en horas al año por el coeficiente de dosis, expresado en mSv por Bq·h·m⁻³, y por la concentración media anual de radón en Bq/m³. Se trata, por tanto, de un producto de los tres factores. Las demás fórmulas son incorrectas porque dividen la concentración por el tiempo, suman el tiempo en lugar de multiplicarlo o dividen el coeficiente por la concentración, lo que no tiene coherencia dimensional ni física."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c22") }, {"long_answer": "El historial dosimétrico individual de un trabajador clasificado como expuesto a radón debe conservarse hasta que este alcance los 75 años de edad y, en ningún caso, durante menos de 30 años desde el cese de la actividad que implicaba la exposición, según la normativa de protección radiológica. Así se garantiza disponer de la información durante todo el periodo de latencia del cáncer de pulmón. Los plazos de 10 o 5 años son claramente insuficientes, y la normativa no exige una conservación indefinida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c3b") }, {"long_answer": "La desfibrilación de doble secuencia está indicada en la parada cardiaca con ritmo desfibrilable, es decir, fibrilación ventricular o taquicardia ventricular sin pulso, cuando el ritmo persiste refractario a las descargas estándar. La asistolia y la actividad eléctrica sin pulso son ritmos no desfibrilables, en los que ninguna descarga está indicada. La bradicardia severa con pulso se trata con fármacos o marcapasos, y la parada por hipoxia, si cursa con ritmo no desfibrilable, requiere corregir la causa, no aplicar descargas dobles."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c3c") }, {"long_answer": "En la desfibrilación de doble secuencia, las dos descargas se administran de forma secuencial y muy próxima, con menos de un segundo aproximadamente entre ambas, para que el miocardio reciba dos vectores de corriente prácticamente consecutivos mientras persiste el efecto de la primera descarga. Un intervalo de 2 minutos corresponde al ciclo de reanimación entre análisis de ritmo, no a la separación entre descargas. Intervalos de 30-40 segundos o de más de 3 segundos harían que se comportaran como dos desfibrilaciones independientes y no como una técnica de doble secuencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c45") }, {"long_answer": "Antes de administrar cualquier descarga en la desfibrilación de doble secuencia debe confirmarse que el ritmo es desfibrilable, es decir, fibrilación ventricular o taquicardia ventricular sin pulso, y comprobar la seguridad del entorno. Un paciente consciente no está en parada cardiaca, por lo que nunca se le desfibrilaría. La apertura de la vía aérea es parte de la reanimación, pero no es la condición que determina la descarga, y el segundo monitor no debe desconectarse, ya que es imprescindible para administrar la segunda descarga."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c47") }, {"long_answer": "La desfibrilación de doble secuencia utiliza dos desfibriladores para administrar dos descargas separadas con vectores de corriente distintos, lo que permite despolarizar una mayor masa miocárdica y aumentar la probabilidad de terminar una fibrilación ventricular refractaria a las descargas estándar. No se usa para prolongar la reanimación sin pausas; tampoco reduce la intensidad de la corriente, ya que el miocardio recibe más energía total, y no sustituye la administración de fármacos como adrenalina o amiodarona, que siguen indicados según el algoritmo de soporte vital avanzado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c4c") }, {"long_answer": "El asma leve intermitente no se considera una condición de alto riesgo para recibir nirsevimab en la segunda temporada de VRS. Las recomendaciones del Ministerio de Sanidad incluyen como grupos de alto riesgo en menores de 24 meses a los niños con fibrosis quística, enfermedades neuromusculares graves, síndrome de Down con problemas respiratorios relevantes, cardiopatías congénitas hemodinámicamente significativas, inmunodepresión grave, displasia broncopulmonar o enfermedades metabólicas congénitas, entre otras, ya que estas situaciones aumentan el riesgo de enfermedad grave por VRS."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c4e") }, {"long_answer": "Según las recomendaciones de la actualización de nirsevimab, en la segunda temporada de VRS los niños de alto riesgo que pesan 10 kg o más reciben 200 mg, administrados en dos inyecciones intramusculares de 100 mg en lugares distintos, por lo que a un niño de 11 kg le corresponde esta pauta. La dosis de 100 mg en una inyección se reserva para los que pesan menos de 10 kg. Los 50 mg corresponden a lactantes de menos de 5 kg en su primera temporada, y no se administran 200 mg en una única inyección."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c52") }, {"long_answer": "En los lactantes sometidos a cirugía cardiaca con bypass cardiopulmonar, la circulación extracorpórea elimina parte del anticuerpo circulante, por lo que se recomienda administrar una dosis adicional de nirsevimab tan pronto como el niño esté estable tras la intervención, para restablecer niveles protectores. No debe esperarse a que aparezcan síntomas respiratorios, ya que su finalidad es preventiva. Administrarla solo antes de la cirugía no compensa la pérdida producida durante el bypass, y es falso que nunca se recomiende una dosis adicional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c53") }, {"long_answer": "En las recomendaciones de nirsevimab, la edad cronológica es el tiempo transcurrido desde el nacimiento, sin tener en cuenta la edad gestacional, y es la que se utiliza para establecer los criterios de edad de la inmunización en prematuros. La edad corregida a 40 semanas es un concepto diferente, empleado para valorar el desarrollo. La edad desde la concepción corresponde a la edad posmenstrual o posconcepcional, y la edad desde el alta neonatal no es un criterio utilizado en ningún caso."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c5b") }, {"long_answer": "Nirsevimab es un anticuerpo monoclonal humano que se une a la proteína F del virus respiratorio sincitial en su conformación prefusión, neutralizando el virus e impidiendo su entrada en las células. Proporciona, por tanto, inmunización pasiva. No es una vacuna, porque no induce una respuesta inmunitaria activa en el lactante. No es un antivírico que inhiba la replicación intracelular, sino que actúa antes de la infección celular, y tampoco es un inmunomodulador antiinflamatorio pulmonar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c61") }, {"long_answer": "La edad corregida es la edad que tendría el prematuro si hubiera nacido a término, es decir, ajustada a las 40 semanas de gestación: se calcula restando a la edad cronológica las semanas que faltaron hasta la semana 40. Se utiliza para valorar el crecimiento y el desarrollo. La edad desde el nacimiento sin corrección es la edad cronológica. El tiempo desde el alta neonatal no es un concepto de edad utilizado, y la edad según el desarrollo neurológico es una valoración funcional, no la definición de edad corregida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c6c") }, {"long_answer": "Según los datos recogidos en el Marco Estratégico para los Cuidados de Enfermería, en 2022 los hombres representaban aproximadamente el 14,5% de las enfermeras del Sistema Nacional de Salud, lo que refleja la marcada feminización histórica de la profesión. El 85,5% corresponde a la proporción de mujeres, no de hombres. El 50% supondría una paridad que no existe en la profesión enfermera, y el 5% infravalora la presencia masculina, que ha ido aumentando de forma progresiva en las últimas décadas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b7f") }, {"long_answer": "La Estrategia Farmacéutica para Europa identifica como retos del sector la resistencia a los antimicrobianos, los problemas de desabastecimiento de medicamentos y la necesidad de garantizar la sostenibilidad medioambiental de la producción y el uso de fármacos, además del acceso equitativo y la innovación. Un aumento ilimitado de la producción sin control no se plantea como objetivo ni como reto; la eliminación de la investigación biomédica sería contraria a la estrategia, y lo que se impulsa es la digitalización, no su reducción."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b81") }, {"long_answer": "La Estrategia de la Industria Farmacéutica destaca que el sector en España se caracteriza por un elevado nivel tecnológico, con capacidad para fabricar medicamentos complejos y biotecnológicos, y por contar con personal altamente cualificado, siendo uno de los sectores industriales más intensivos en I+D. No predomina la producción de baja tecnología, no existe una dependencia completa de las importaciones, ya que hay una importante producción local con capacidad exportadora, y España dispone de un ecosistema de investigación biotecnológica en crecimiento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b87") }, {"long_answer": "El Plan de acción para la prevención del suicidio recoge que estudios recientes muestran la limitada capacidad predictiva de los factores de riesgo tradicionales: tomados de forma aislada anticipan con poca precisión quién realizará una conducta suicida y no analizan la compleja interacción entre ellos. No se debe a una falta de datos demográficos, que suelen estar disponibles, ni a la escasa participación de los profesionales. Además, la presentación clínica es heterogénea, no homogénea, lo que precisamente dificulta la predicción."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b88") }, {"long_answer": "Franklin y colaboradores, en un amplio metaanálisis sobre factores de riesgo de pensamientos y conductas suicidas, concluyeron que su capacidad predictiva apenas superaba al azar y plantearon como posible mejora el uso de algoritmos de riesgo basados en aprendizaje automático, capaces de combinar un gran número de factores y sus interacciones. Aumentar la formación del personal es útil para la detección, pero no fue su propuesta para mejorar la predicción. Los enfoques psicoanalíticos y las encuestas de opinión no forman parte de sus conclusiones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b8a") }, {"long_answer": "Los métodos tradicionales de predicción del suicidio, basados en la suma de factores de riesgo, tienen baja precisión y generan tanto falsos positivos, al identificar como de alto riesgo a muchas personas que no realizarán conductas suicidas, como falsos negativos, al no detectar a otras que sí lo harán. Por ello el Plan aconseja combinar la valoración con intervenciones universales. Su limitación no se reduce a detectar peor a las personas de riesgo elevado, no impiden las intervenciones estructurales, y la ausencia de indicadores biológicos no es el riesgo principal señalado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b8b") }, {"long_answer": "Las intervenciones estructurales, especialmente la restricción del acceso a medios letales como armas de fuego, determinados fármacos o lugares de riesgo, se encuentran entre las medidas de prevención del suicidio con mayor evidencia de efectividad, ya que reducen la mortalidad de forma poblacional. La terapia farmacológica exclusiva es insuficiente sin un abordaje integral; las campañas de sensibilización superficial tienen escaso impacto demostrado, y las terapias individuales en centros privados no constituyen por sí mismas una estrategia de prevención poblacional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b8c") }, {"long_answer": "Los medios de comunicación influyen en la conducta suicida: una información sensacionalista puede inducir imitación (efecto Werther), mientras que un tratamiento riguroso y ético puede tener efecto protector (efecto Papageno). Por ello el Plan promueve que la información sea rigurosa, ética y alejada del sensacionalismo, aportando recursos de ayuda. No se recomienda evitar los testimonios personales, ya que los relatos de superación pueden ser protectores. Difundir estadísticas sin contexto o publicar detalles explícitos sobre los métodos empleados aumenta el riesgo de imitación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b8d") }, {"long_answer": "El Plan de acción identifica como grupos en situación de vulnerabilidad con mayor riesgo de conducta suicida a las personas con discapacidad, las personas mayores en situación de soledad no deseada, los adolescentes y jóvenes, entre otros colectivos como las personas privadas de libertad o con problemas de salud mental. El acceso a la educación superior, un alto nivel socioeconómico o la práctica regular de deporte no se consideran factores de riesgo; en general, los recursos económicos y la actividad física se relacionan más bien con un efecto protector."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b93") }, {"long_answer": "El enfoque comunitario de prevención del suicidio se caracteriza por implicar a la propia comunidad, incluidas familias, escuelas, asociaciones, entornos laborales y servicios locales, en la creación de entornos de apoyo y en el fortalecimiento de los lazos sociales, que actúan como factores protectores frente al aislamiento. Centrarse solo en tratamientos hospitalarios, delegar toda la intervención en los servicios de emergencia o promover exclusivamente intervenciones farmacológicas contradice este enfoque, que es por definición participativo, intersectorial y de base territorial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b94") }, {"long_answer": "La Ley Orgánica 8/2021, de protección integral a la infancia y la adolescencia frente a la violencia, crea en los centros educativos la figura del coordinador o coordinadora de bienestar y protección del alumnado, encargado de promover el bienestar, la cultura del buen trato y la detección de situaciones de riesgo, incluida la conducta suicida. El mediador escolar existe en algunos centros, pero no es la figura creada por esta ley. Tampoco lo son el psicólogo institucional ni un representante legal del estudiante."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b9a") }, {"long_answer": "El Observatorio para la Prevención del Suicidio que propone el Plan tiene como función recopilar y difundir información fiable y homogénea sobre la conducta suicida y contribuir a coordinar las actuaciones de prevención y atención entre administraciones y agentes implicados, facilitando la toma de decisiones basada en datos. No se limita a supervisar a pacientes psiquiátricos; no realiza campañas mediáticas sin base científica, ya que precisamente se fundamenta en la evidencia, y el control del consumo de medicamentos en farmacias no es una de sus funciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ba1") }, {"long_answer": "El Plan señala que las personas privadas de libertad presentan una tasa de suicidio claramente superior a la de la población general, de aproximadamente 90,9 por cada 100.000, lo que las convierte en un grupo prioritario de intervención en el medio penitenciario mediante programas específicos de prevención. El personal de los servicios penitenciarios y los funcionarios de prisiones no son los colectivos señalados con esa tasa, y la población en reinserción social no es el grupo al que se refiere este dato."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bad") }, {"long_answer": "Respecto a las vías venosas centrales ya insertadas, la guía recomienda obtener preferentemente los hemocultivos por venopunción periférica en dos sitios distintos. Si se extrae una muestra a través del catéter central, por ejemplo ante sospecha de bacteriemia relacionada con el catéter, debe acompañarse siempre de otro set obtenido por vena periférica para poder interpretar el resultado comparando ambos. Usar únicamente la vía central aumenta los falsos positivos. Tampoco se prohíbe de forma absoluta su uso, y el número de luces del catéter no es el criterio de la recomendación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bb0") }, {"long_answer": "Cuando el hemocultivo se obtiene de una vía venosa periférica recién insertada, no es necesario desechar un volumen inicial de sangre. La excepción son los dispositivos específicos de desvío que separan automáticamente los primeros 1-2 ml, que pueden contener fragmentos de piel colonizada, y que han demostrado reducir las contaminaciones. Por ello es incorrecto descartar siempre el volumen inicial, desaconsejar estos dispositivos o establecer el criterio en función de que la vía lleve más de una hora insertada.", "option_1": "No es necesario, salvo si se utilizan dispositivos específicos que desechan automáticamente 1-2 ml"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bb1") }, {"long_answer": "Cuando en una misma punción se extraen hemocultivos y muestras para analítica, deben inocularse primero los frascos de hemocultivo y después los tubos de analítica, porque los tubos no son estériles y contienen aditivos que podrían contaminar la muestra o arrastrarse al frasco por reflujo. Extraer primero la analítica aumenta el riesgo de contaminación del hemocultivo. Hacerlo simultáneamente sin orden o considerar que el orden no influye ignora este riesgo, que la guía tiene en cuenta en su recomendación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bb4") }, {"long_answer": "En adultos, el volumen de sangre es el factor más determinante de la rentabilidad del hemocultivo, por lo que se recomienda inocular alrededor de 10 ml por frasco (entre 8 y 10 ml), siguiendo las indicaciones del fabricante, lo que supone unos 20 ml por set. Inocular solo 5-7 ml o menos de 5 ml disminuye la sensibilidad y aumenta los falsos negativos, y no se justifica por el riesgo de anemia en adultos. Introducir más de 20 ml por frasco supera la capacidad recomendada y altera la proporción entre sangre y medio de cultivo.", "option_1": "Alrededor de 10 ml por frasco (8-10 ml), según recomendaciones del fabricante"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bb9") }, {"long_answer": "La guía sugiere evitar introducir aire en el frasco destinado al cultivo de anaerobios, ya que el oxígeno puede inhibir el crecimiento de las bacterias anaerobias estrictas y reducir la rentabilidad del cultivo. Por eso, cuando se usa jeringa, se inocula primero el frasco anaerobio y se evita que entren burbujas. Introducir aire para oxigenar la muestra es contrario a la finalidad del frasco anaerobio; la precaución no depende de sospechar previamente anaerobios, y la cuestión no queda a criterio del profesional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bba") }, {"long_answer": "La guía no recomienda cambiar la aguja antes de inocular la sangre en el frasco de hemocultivo, porque la evidencia no muestra una reducción significativa de las contaminaciones y la maniobra incrementa el riesgo de pinchazo accidental del profesional. Es incorrecto, por tanto, afirmar que siempre deba utilizarse una aguja nueva. Si la aguja ha tocado una superficie no estéril se habrá roto la técnica aséptica y deberá valorarse repetir la extracción, y el uso de sistemas de vacío no requiere cambiar la aguja."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bbc") }, {"long_answer": "Tras inocular la sangre, se recomienda agitar suavemente los frascos o mezclarlos por inversión para homogeneizar la muestra con el medio de cultivo y los anticoagulantes, evitando la formación de coágulos que pueden atrapar microorganismos y dificultar su detección. Es falso que la agitación suave dañe a los microorganismos. No debe reservarse para muestras ya coaguladas, pues su objetivo es precisamente prevenir la coagulación, y la recomendación es aplicable tanto a los frascos aerobios como a los anaerobios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bbe") }, {"long_answer": "Cuando la extracción se realiza con jeringa y aguja, debe inocularse primero el frasco anaerobio, para evitar que el aire que pueda quedar en la jeringa entre en él y comprometa el crecimiento de bacterias anaerobias. En cambio, si se usa un sistema de vacío con palomilla, se llena primero el aerobio, porque el aire del tubo de la alargadera pasaría al primer frasco. El orden no es indiferente, y no es necesario usar una jeringa nueva para cada frasco, ya que se inoculan con la misma muestra extraída."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bc0") }, {"long_answer": "Los primeros hemocultivos pueden extraerse en el mismo momento en que se canaliza una vía periférica, pero solo a través del catéter recién insertado y cuando no exista la alternativa de una venopunción independiente, ya que la punción directa sigue siendo la técnica de elección por su menor riesgo de contaminación. La correcta desinfección de la zona no convierte este procedimiento en la opción preferente. Esperar 30 minutos tras la canalización no tiene fundamento, y el uso de guantes estériles y mascarilla no modifica esta indicación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bc3") }, {"long_answer": "Los hemocultivos deben introducirse cuanto antes en el sistema automatizado de incubación. En los servicios donde el envío al laboratorio se demora, disponer de incubadoras conectadas al sistema del laboratorio permite iniciar la incubación y la lectura continua de inmediato, acortando los tiempos de detección y mejorando la calidad del proceso. Mantenerlos a temperatura ambiente durante tiempos prolongados retrasa el diagnóstico. Enviarlos sin incubar cuando hay demora no es la opción preferente, y la recomendación no se limita a periodos inferiores a dos horas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bc6") }, {"long_answer": "El Real Decreto 1029/2022, por el que se aprueba el Reglamento sobre protección de la salud contra los riesgos derivados de la exposición a las radiaciones ionizantes, establece un nivel de referencia de 300 Bq/m³ para la concentración media anual de radón en el aire en recintos cerrados, en consonancia con la Directiva 2013/59/Euratom. El valor de 150 Bq/m³ no corresponde a este nivel, y los de 600 y 1.000 Bq/m³ eran niveles de actuación utilizados en normativas o recomendaciones anteriores para lugares de trabajo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bd2") }, {"long_answer": "La instalación de detectores de humo especializados no forma parte de las medidas de protección frente al radón del Documento Básico HS 6 del Código Técnico de la Edificación, ya que el radón es un gas inodoro e incoloro que no genera humo y su control se basa en evitar su entrada y facilitar su evacuación. Las medidas fundamentales del HS 6 son las barreras de protección que impiden el paso del gas desde el terreno, los sistemas de despresurización o extracción para redirigirlo al exterior y la ventilación de cámaras de aire o espacios de contención."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bd4") }, {"long_answer": "El Plan Nacional contra el Radón está coordinado por el Ministerio de Sanidad, dado que su objetivo principal es reducir el riesgo de cáncer de pulmón asociado a la exposición al radón, aunque su elaboración y desarrollo implican a otros departamentos y organismos. El Consejo de Seguridad Nuclear participa como organismo técnico competente en protección radiológica; el Ministerio de Trabajo y Economía Social interviene en el ámbito laboral, y el Ministerio para la Transición Ecológica colabora en aspectos ambientales y urbanísticos, pero ninguno de ellos coordina el Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bda") }, {"long_answer": "Según el Plan Nacional, el protocolo de vigilancia sanitaria específica para trabajadores expuestos a radón se plantea con el objetivo de evaluar la efectividad del cribado de cáncer de pulmón mediante tomografía computarizada de baja dosis en este colectivo, siempre junto a medidas de prevención primaria como el abandono del tabaco. Las mediciones domiciliarias de radón no son objeto de la vigilancia sanitaria laboral; la vigilancia de la salud no elimina por sí misma la exposición, que se controla con medidas técnicas, ni actúa sobre el radón del suelo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bde") }, {"long_answer": "Durante la noche la temperatura exterior desciende y aumenta la diferencia con el interior de la vivienda, lo que intensifica el efecto chimenea: el aire caliente asciende y sale por la parte alta del edificio, generando una depresión en las plantas bajas que favorece la aspiración del radón desde el terreno. Por eso las concentraciones nocturnas suelen ser mayores. Una mayor presión atmosférica tiende a reducir la exhalación de radón, la baja humedad no explica este patrón y la ventilación forzada contribuye a disminuir la concentración interior."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977be0") }, {"long_answer": "Incluir datos de radón en el Sistema de Información Urbana permite que las administraciones y los técnicos tengan en cuenta el potencial de radón del terreno en la planificación urbanística y en la ordenación del territorio, de modo que se puedan prever medidas de protección en nuevos desarrollos y priorizar actuaciones en zonas de mayor riesgo. No tiene relación con la mejora de la accesibilidad de las viviendas, no pretende controlar la venta de materiales de construcción y tampoco busca reducir la densidad poblacional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977be3") }, {"long_answer": "La concentración de radón en los edificios depende sobre todo de las características geológicas del terreno: el contenido en uranio y radio de las rocas, como los granitos, y la permeabilidad del suelo determinan cuánto gas se genera y con qué facilidad migra hacia la superficie. Por ello el Plan considera la distribución geológica un elemento clave para estimar el riesgo y planificar las medidas. El nivel educativo de la población, la superficie urbana total o la cantidad de espacios verdes no determinan la presencia de radón."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977be6") }, {"long_answer": "El Plan para la ampliación de la cartera común de servicios de salud bucodental define como colectivos prioritarios a la población infantil y juvenil, las mujeres embarazadas, las personas con discapacidad y las personas con procesos oncológicos del territorio cervicofacial, que requieren cuidados preventivos y terapéuticos específicos antes, durante y después de los tratamientos oncológicos. Los adultos mayores de 60 años sin discapacidad, los pacientes con diabetes sin complicaciones bucodentales o las personas sin acceso a atención primaria no figuran como colectivos prioritarios del Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977be8") }, {"long_answer": "Según el diagnóstico de situación del Plan, la revisión anual de la salud bucodental es la prestación básica del Programa de Atención Dental Infantil que se ofrece en el 100% de las comunidades autónomas, ya que constituye la base de la prevención y la detección precoz en la infancia. La aplicación de flúor tópico, los tratamientos pulpares en dentición permanente y las tartrectomías son prestaciones también presentes en muchos programas, pero su implantación no es universal o depende de los criterios establecidos en cada comunidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bed") }, {"long_answer": "Según la propuesta aprobada, la ampliación de la cartera común para la población infantil de 6 a 14 años debía implantarse antes del 31 de diciembre de 2022, en la primera fase del Plan, junto con otras actuaciones prioritarias, aprovechando que en muchas comunidades ya existían programas de atención dental infantil. Los plazos de junio o diciembre de 2023 y el año 2025 corresponden a fases posteriores o no se ajustan al calendario establecido para este grupo de edad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bf1") }, {"long_answer": "El diagnóstico de situación del Plan señala que los tratamientos con sedación para personas con discapacidad que no colaboran en la atención dental se prestan a toda la población con discapacidad en el 94% de las comunidades autónomas, por lo que es una prestación ampliamente implantada aunque no universal. No se limita a la población infantil con discapacidad; es incorrecto que no se preste en ninguna comunidad, y no se restringe a la patología de la dentición temporal, ya que abarca también la dentición permanente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bf5") }, {"long_answer": "En la distribución presupuestaria para la ampliación de la cartera común de salud bucodental en 2022, Andalucía fue la comunidad autónoma que recibió la mayor asignación, ya que los fondos se repartieron principalmente según la población protegida y la de los colectivos destinatarios, y Andalucía es la comunidad más poblada de España. Cataluña y Madrid, aunque también recibieron cantidades elevadas por su volumen de población, obtuvieron asignaciones menores, y Castilla y León, con menos habitantes, recibió una cantidad claramente inferior."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bfe") }, {"long_answer": "Según el Sistema de Cuentas de Salud recogido en el Plan, la mayor parte del gasto público en salud bucodental corresponde a las administraciones públicas excluidas las de la Seguridad Social, es decir, fundamentalmente a los servicios de salud de las comunidades autónomas, que gestionan las prestaciones sanitarias. Las administraciones de la Seguridad Social y las mutualidades de funcionarios representan una parte menor de este gasto. Las empresas privadas de seguros no forman parte del gasto público, sino del gasto privado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c02") }, {"long_answer": "En la cadena de desintegración del uranio 238, el radón 222 procede directamente de la desintegración alfa del radio 226, que es su progenitor inmediato y está presente en rocas y suelos, especialmente en los graníticos. El torio 230 es el precursor del radio 226, de modo que precede al radón en la cadena pero no es su progenitor directo. El polonio 218 y el bismuto 210 son descendientes del radón, no sus precursores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c0b") }, {"long_answer": "El estudio europeo de análisis conjunto de estudios de casos y controles (pooling europeo, Darby y colaboradores) estimó que el riesgo de cáncer de pulmón aumenta aproximadamente un 16% por cada 100 Bq/m³ de incremento en la concentración residencial de radón a largo plazo, una vez corregida la incertidumbre en la medición de la exposición, y con una relación lineal sin umbral. El 11% corresponde a la estimación del análisis conjunto norteamericano, el 5% infravalora el riesgo y el 25% lo sobrestima."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c0c") }, {"long_answer": "La Organización Mundial de la Salud recomienda un nivel de referencia de 100 Bq/m³ para minimizar los riesgos del radón en interiores y, cuando las condiciones de un país no lo permitan, que el nivel elegido no supere los 300 Bq/m³. Un valor de 50 Bq/m³ no es el nivel propuesto por la OMS. Presentar los 300 Bq/m³ como un nivel simplemente permitido desvirtúa la recomendación, que lo considera un límite superior que no debe sobrepasarse, y 500 Bq/m³ excede ampliamente lo aconsejado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c11") }, {"long_answer": "En los estudios europeos recogidos en el Libro del Radón, una zona de alto potencial de radón (radon-prone area) se define como aquella en la que más del 10% de las viviendas presentan concentraciones superiores a 300 Bq/m³, coincidiendo con el nivel de referencia europeo. El criterio del 25% de viviendas por encima de 100 Bq/m³ no corresponde a esta definición. Exigir niveles superiores a 600 Bq/m³ sería demasiado restrictivo, y cualquier concentración detectable no sirve como criterio, porque el radón está presente en todas partes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c13") }, {"long_answer": "Los estudios recientes recogidos en el Libro del Radón muestran que aproximadamente un 20% de los lugares de trabajo situados en zonas de alto potencial de radón en España superan los 300 Bq/m³, lo que justifica la obligación de medir en estas zonas establecida por la normativa. Las cifras del 5% y del 10% infravaloran la magnitud del problema en esas áreas, mientras que el 50% sobrestima la proporción de centros de trabajo que superan el nivel de referencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c15") }, {"long_answer": "El Real Decreto 1029/2022 establece un nivel de referencia de 300 Bq/m³ para la concentración media anual de radón en el aire de los lugares de trabajo, siguiendo la Directiva 2013/59/Euratom; si se supera, el titular debe adoptar medidas de reducción y, en su caso, estimar las dosis de los trabajadores. Los 100 Bq/m³ corresponden al nivel preferente recomendado por la OMS, los 200 Bq/m³ a antiguas recomendaciones europeas para nuevas construcciones, y 500 Bq/m³ no es el nivel de referencia de la normativa española."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c18") }, {"long_answer": "Según el Libro del Radón, en el marco del Código Técnico de la Edificación una medición de radón válida debe tener una duración mínima de dos meses, y se recomienda preferiblemente de tres meses, para poder estimar con suficiente fiabilidad la concentración media anual, dado que el radón presenta importantes variaciones diarias y estacionales. Las mediciones de 24 horas o de una semana son útiles solo como cribado y no son representativas de la media anual. Un año completo es lo ideal, pero no es la duración mínima exigida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c1a") }, {"long_answer": "Ante exposiciones extremadamente altas, como 18.000 Bq/m³, el Instituto de Radioprotección y Seguridad Nuclear francés recomienda adoptar medidas de prevención: evitar fumar, ya que el tabaco multiplica el riesgo de cáncer de pulmón del radón, evitar la exposición a otros irritantes respiratorios y medir el radón en la vivienda para reducir la exposición total. Exponer a más radiación con fines diagnósticos carece de sentido. Hacer exámenes médicos mensuales sin otras medidas no está recomendado, y considerar que no se requiere ninguna acción es incorrecto ante niveles tan elevados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c1b") }, {"long_answer": "Las recomendaciones francesas recogidas en el Libro del Radón consideran de alto riesgo de cáncer de pulmón por radón a las personas de 55 a 74 años, fumadoras o exfumadoras con un consumo acumulado superior a 30 paquetes-año y con exposición laboral al radón durante al menos 10 años, combinación que las hace candidatas a cribado. Las personas menores de 40 años con exposición breve no cumplen los criterios de edad ni de exposición. Los mayores de 75 años quedan fuera del rango, y los no fumadores con exposición residencial no se incluyen en este grupo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c21") }, {"long_answer": "Según la normativa española de protección radiológica, el límite de dosis efectiva para los trabajadores expuestos, incluidos los expuestos a radón, es de 20 mSv por año oficial. El valor de 6 mSv al año es el umbral a partir del cual un trabajador debe clasificarse como expuesto y someterse a vigilancia, no el límite máximo. Los 10 mSv no corresponden a ningún límite anual establecido, y 30 mSv supera el límite legal permitido."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c23") }, {"long_answer": "En la vigilancia sanitaria de los trabajadores expuestos a radón, el Libro del Radón recomienda priorizar la prevención primaria: reducir la exposición mediante medidas técnicas en los lugares de trabajo y promover la cesación tabáquica, dado el efecto multiplicativo entre tabaco y radón, antes que plantear programas de cribado. La vigilancia radiológica frecuente para todos o la tomografía computarizada de baja dosis anual obligatoria no están justificadas de forma universal, y una vigilancia meramente pasiva sin acciones directas no reduce el riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c27") }, {"long_answer": "El estudio realizado en Galicia muestra que en las provincias de Ourense y Pontevedra alrededor del 20% de las viviendas superan los 300 Bq/m³, por su sustrato granítico rico en uranio, frente a porcentajes inferiores en A Coruña y Lugo. Madrid y Extremadura no pertenecen a Galicia, aunque algunas de sus zonas también tienen potencial de radón, y Sevilla y Cádiz son provincias andaluzas con concentraciones de radón generalmente bajas."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c28") }, {"long_answer": "El Plan Nacional contra el Radón se estructura en cinco ejes estratégicos: conocimiento e infraestructura básica, edificación y reducción del radón en edificios, lugares de trabajo, zonas de actuación prioritaria, y comunicación y concienciación. Las demás opciones no recogen esta estructura: la formación, la financiación o las sanciones pueden ser acciones dentro de los ejes, pero no ejes en sí mismas; el diagnóstico clínico y el tratamiento no son el núcleo del Plan, y la descontaminación o la fiscalidad no constituyen ejes estratégicos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c29") }, {"long_answer": "En el ámbito laboral, un trabajador se considera expuesto a radón cuando, a pesar de las medidas de reducción y con concentraciones superiores al nivel de referencia de 300 Bq/m³, su dosis efectiva anual puede superar los 6 mSv; en ese caso se aplican las medidas de protección radiológica propias de los trabajadores expuestos. Una exposición ocasional de menos de 100 horas al año no alcanza ese umbral. Ser fumador aumenta el riesgo de cáncer, pero no define la exposición laboral, y trabajar en altura no guarda relación con el radón."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c2c") }, {"long_answer": "Para realizar la desfibrilación de doble secuencia se necesitan dos monitores desfibriladores, cada uno con su propio juego de electrodos autoadhesivos, de forma que puedan administrarse dos descargas casi consecutivas con vectores de corriente diferentes. Un respirador o una bomba de infusión pueden formar parte de la reanimación, pero no permiten realizar esta técnica. Tampoco se plantea combinar un desfibrilador manual con uno automático, ya que el protocolo requiere control manual de ambas descargas para coordinarlas en el tiempo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c2d") }, {"long_answer": "Para realizar la desfibrilación de doble secuencia el paciente debe estar en decúbito supino, posición que permite una reanimación cardiopulmonar eficaz, en un lugar seguro y evitando superficies húmedas o metálicas no aisladas, que podrían conducir la corriente y poner en riesgo al equipo. Estar de pie sobre superficie metálica es inviable en una parada y peligroso. El decúbito prono impide realizar compresiones torácicas estándar, y la sedestación no permite una reanimación adecuada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c2f") }, {"long_answer": "Según el protocolo, tras la tercera desfibrilación estándar sin éxito, durante el ciclo de reanimación de 2 minutos que la sigue, se colocan los electrodos del segundo monitor desfibrilador, para que la técnica de doble secuencia pueda aplicarse en el siguiente análisis si persiste el ritmo desfibrilable, sin interrumpir las compresiones. No se debe continuar con descargas estándar hasta la sexta. Cambiar la posición de los electrodos iniciales no es el paso indicado, y esperar 5 minutos para encender el segundo monitor retrasaría la técnica sin justificación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c33") }, {"long_answer": "Al colocar los electrodos del segundo monitor durante la desfibrilación de doble secuencia, la precaución principal es minimizar las interrupciones de las compresiones torácicas, ya que la calidad y la continuidad de la reanimación son determinantes para la supervivencia. Colocarlos en cualquier lugar disponible impediría conseguir el vector de corriente deseado. Colocarlos juntos podría provocar arcos eléctricos y no aumenta la eficacia, y una separación concreta de más de 10 cm no es la precaución esencial que establece el protocolo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c38") }, {"long_answer": "El protocolo establece que deben haberse administrado al menos tres desfibrilaciones estándar sin éxito, en presencia de fibrilación ventricular o taquicardia ventricular sin pulso persistente, antes de iniciar la desfibrilación de doble secuencia, ya que esta se reserva para la fibrilación ventricular refractaria. Una o dos descargas son insuficientes para considerar el ritmo refractario y la técnica no debe aplicarse de inicio. Esperar a la cuarta descarga no es el criterio establecido y retrasaría su aplicación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c3a") }, {"long_answer": "Los electrodos del segundo monitor deben colocarse en posiciones anatómicas diferentes a las del primer juego, habitualmente en posición anteroposterior si los primeros están en anterolateral, procurando que no se toquen ni se superpongan. Así se consigue un vector de corriente distinto y se evita la formación de arcos eléctricos o daños en los equipos. Superponer los electrodos es incorrecto y peligroso, situarlos todos en la línea media esternal no garantiza un vector adecuado, y la separación es necesaria independientemente de su localización."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c41") }, {"long_answer": "En la desfibrilación de doble secuencia, un único operador coordina el procedimiento: anuncia la descarga, comprueba la seguridad y ejecuta las dos descargas de forma secuencial, con una diferencia aproximada de un segundo o menos entre ambas. Esta coordinación evita retrasos y riesgos para el equipo. La descarga simultánea exacta no se busca, entre otras razones por el posible daño a los equipos. Un minuto de diferencia anula el fundamento de la técnica, y el segundo monitor no es un mero dispositivo de reserva ante fallos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c46") }, {"long_answer": "Durante la desfibrilación de doble secuencia, el segundo monitor desfibrilador debe estar colocado, conectado a sus electrodos, en modo de desfibrilación y cargado con la misma energía que el primero, de forma que ambas descargas puedan administrarse de inmediato y de manera coordinada. Mantenerlo apagado como reserva o junto al paciente sin conectar no permite realizar la técnica. Configurarlo con el doble de energía no forma parte del protocolo, que utiliza la energía máxima habitual de cada equipo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c49") }, {"long_answer": "Nirsevimab permite una estrategia de inmunización poblacional frente al VRS porque es un anticuerpo monoclonal de vida media prolongada, gracias a una modificación de su fracción Fc, de forma que una sola dosis intramuscular protege a los lactantes durante toda la temporada, de al menos cinco meses. No es una vacuna viva atenuada, ya que confiere inmunidad pasiva, ni un antivírico oral. Tampoco es un inmunosupresor: neutraliza específicamente el virus sin deprimir la respuesta inmunitaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c50") }, {"long_answer": "Los estudios de efectividad realizados en España y recogidos en la actualización de las recomendaciones mostraron que los lactantes que recibieron nirsevimab tuvieron un riesgo de hospitalización por VRS entre un 81% y un 84% menor que los no inmunizados durante la primera temporada de implantación. Una reducción del 20-25% o del 50-55% infravalora el efecto observado, y es falso que no hubiera una reducción significativa, ya que el beneficio fue claro y consistente con los ensayos clínicos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c51") }, {"long_answer": "Cada dosis de nirsevimab administrada, con independencia del ámbito asistencial, sea un hospital, un centro de atención primaria, la red pública o la privada, debe registrarse en el sistema de información de vacunaciones de la comunidad autónoma correspondiente, lo que permite conocer las coberturas, evaluar la efectividad y realizar un seguimiento individual. No basta con comunicar las reacciones adversas, que además deben notificarse a farmacovigilancia. Es incorrecto que no se requiera registro, y este no se limita a los hospitales públicos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c55") }, {"long_answer": "En los lactantes sometidos a cirugía cardiaca con bypass cardiopulmonar en los 90 días siguientes a la primera dosis de nirsevimab durante su primera temporada de VRS, la dosis adicional se ajusta según el peso en el momento de administrarla: 50 mg si pesan menos de 5 kg y 100 mg si pesan 5 kg o más. No se administra siempre 100 mg ni una dosis única de 200 mg, que corresponde a la segunda temporada, y es incorrecto que no se administre dosis adicional en este periodo.", "option_1": "50 mg o 100 mg según el peso corporal en el momento de la dosis adicional (menos de 5 kg o 5 kg o más)", "question": "En un lactante en su primera temporada de VRS sometido a cirugía cardiaca con circulación extracorpórea en los 90 días siguientes a recibir nirsevimab, ¿cómo se ajusta la dosis adicional?"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c56") }, {"long_answer": "Los datos poblacionales recogidos en la actualización de las recomendaciones mostraron que, en la temporada 2023-2024, primera con inmunización sistemática con nirsevimab, las hospitalizaciones por VRS en menores de un año se redujeron aproximadamente entre un 71% y un 77% respecto a la temporada anterior. Es falso, por tanto, que aumentaran o que no hubiera diferencias significativas. La reducción tampoco se limitó a los prematuros, ya que la estrategia se aplicó a todos los lactantes nacidos durante la temporada o en los meses previos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c5c") }, {"long_answer": "Según la actualización de las recomendaciones del Ministerio de Sanidad, en la segunda temporada de VRS los niños de alto riesgo reciben una dosis adaptada al peso: si pesan menos de 10 kg, 100 mg en una única inyección intramuscular, y si pesan 10 kg o más, 200 mg divididos en dos inyecciones de 100 mg. Por tanto, a un niño de 9 kg le corresponden 100 mg. La dosis de 50 mg corresponde a lactantes de menos de 5 kg en su primera temporada, y es falso que no se administre nirsevimab en la segunda temporada a los niños de alto riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c5e") }, {"long_answer": "El virus respiratorio sincitial es la principal causa de bronquiolitis y de neumonía en lactantes y la primera causa de hospitalización en menores de 12 meses durante la temporada de otoño e invierno, lo que justifica la estrategia de inmunización con nirsevimab. La gripe estacional también provoca ingresos en la infancia, pero en menor número en este grupo de edad. La neumonía bacteriana es menos frecuente como causa de hospitalización en lactantes, y el asma no se diagnostica habitualmente en menores de un año."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c64") }, {"long_answer": "Para la temporada 2024-2025, a los lactantes menores de seis meses nacidos entre el 1 de abril y el 30 de septiembre de 2024 se les recomendó administrar nirsevimab al inicio de la campaña, en octubre de 2024, con la posibilidad de adelantarla según la situación epidemiológica, mientras que los nacidos desde el 1 de octubre de 2024 hasta el 31 de marzo de 2025 debían recibirlo lo antes posible tras el nacimiento. Limitar la administración a diciembre-febrero o a la primavera no se ajusta a la estacionalidad del VRS, y esperar a los 6 meses dejaría sin protección el periodo de mayor riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c6a") }, {"long_answer": "El Marco Estratégico para los Cuidados de Enfermería identifica el envejecimiento de la población y el descenso de la natalidad como uno de los principales desafíos sociodemográficos de España, ya que conlleva un aumento de la cronicidad, la dependencia y la demanda de cuidados. No se describe un incremento drástico de las enfermedades transmisibles. La esperanza de vida en España es de las más altas del mundo y no ha disminuido de forma significativa, y tampoco hay un aumento de población joven y de nacimientos, sino la tendencia contraria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c6d") }, {"long_answer": "Según los datos del INE recogidos en el Marco Estratégico, durante el primer semestre de 2024 la principal causa de muerte por causas naturales en España fueron las enfermedades del sistema circulatorio o cardiocirculatorio, seguidas muy de cerca por los tumores, que ocupan el segundo lugar. Las enfermedades del sistema respiratorio aparecen en tercer lugar. Los accidentes de tráfico son causas externas, no naturales, y su peso en la mortalidad global es mucho menor."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c6f") }, {"long_answer": "El Real Decreto 546/1995, que establece el título de Técnico en Cuidados Auxiliares de Enfermería, recoge como competencia general proporcionar cuidados auxiliares al paciente y actuar sobre las condiciones sanitarias de su entorno, bajo la dependencia del diplomado en enfermería o, en su caso, como miembro de un equipo de salud. La prestación autónoma de cuidados enfermeros especializados corresponde a las enfermeras especialistas. El diagnóstico y la prescripción de tratamientos no son competencias del TCAE, y tampoco lo es el desarrollo de programas de investigación clínica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b76") }, {"long_answer": "El programa PROFARMA, impulsado por la Administración, evalúa a las compañías farmacéuticas y reconoce sus esfuerzos en producción industrial, investigación y desarrollo y modernización, con el objetivo de fomentar la competitividad del sector y su contribución a la economía española. No limita la innovación a las empresas multinacionales, ya que incluye compañías nacionales y de distintos tamaños. Tampoco se centra exclusivamente en la comercialización de genéricos, y entre sus fines está favorecer la creación de empleo cualificado, no reducirlo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b78") }, {"long_answer": "La línea de ayudas Industria Conectada 4.0, Activa Financiación, financia proyectos de empresas industriales, incluidas las farmacéuticas, orientados a su transformación digital y a la mejora de la sostenibilidad ambiental de sus procesos productivos, en línea con la industria 4.0. No pretende fomentar la producción manual tradicional, sino la automatización y la digitalización. Tampoco regula la importación exclusiva de tecnologías extranjeras, y limitar la digitalización sería contrario a su objetivo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b79") }, {"long_answer": "El Fondo de Apoyo a la Inversión Industrial Productiva (FAIIP) proporciona apoyo financiero de carácter retornable, mediante préstamos y otros instrumentos, a proyectos de inversión industrial que favorezcan la competitividad, la transformación digital y la sostenibilidad ambiental de la industria, incluida la farmacéutica. No se dirige exclusivamente a grandes multinacionales; los proyectos se someten a una evaluación previa de su viabilidad, y no se trata de donaciones sin retorno, ya que la financiación debe devolverse."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b7b") }, {"long_answer": "La Estrategia Farmacéutica para Europa contempla la creación de HERA, la Autoridad Europea de Preparación y Respuesta ante Emergencias Sanitarias, cuyo propósito es anticipar amenazas sanitarias y garantizar la disponibilidad de contramedidas médicas, como vacunas y medicamentos, ante crisis como pandemias. No gestiona la comercialización de genéricos, competencia que corresponde a las agencias reguladoras. No se ocupa de la formación de los profesionales sanitarios, y su ámbito son precisamente los productos estratégicos, no los mercados no estratégicos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b84") }, {"long_answer": "La autonomía estratégica abierta que plantea la Estrategia Farmacéutica para Europa pretende reforzar en territorio europeo tanto la fabricación como la investigación, el desarrollo y la innovación de medicamentos, para recuperar competitividad global en innovación biomédica y reducir dependencias, sin renunciar a la cooperación internacional. Por ser abierta, no excluye la participación de terceros países. Tampoco busca centralizar la producción en un único país europeo, y no limita el desarrollo tecnológico a medicamentos tradicionales, ya que impulsa terapias innovadoras.", "option_1": "Abarcar fabricación e I+D+i para recuperar competitividad global en innovación biomédica"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b85") }, {"long_answer": "Mejorar el conocimiento mutuo entre los organismos públicos de investigación y la industria tiene como finalidad principal incrementar la colaboración público-privada y facilitar la transferencia del conocimiento generado en universidades, hospitales y centros de investigación hacia productos y medicamentos que lleguen a los pacientes. Mantener aisladas las iniciativas académicas y comerciales es justo lo contrario de lo que se busca. No se pretende fomentar una competencia desleal, y la estrategia promueve la innovación abierta, no su reducción."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b95") }, {"long_answer": "Según el Plan de acción, los protocolos para equipos de emergencia ante situaciones de riesgo suicida incluyen la definición de las competencias de cada interviniente, las fases de actuación desde la alerta hasta la derivación, y medidas de seguridad específicas tanto para la persona en riesgo como para los profesionales. Por tanto, no carecen de fases de actuación claras. No se limitan a la atención psicológica, ya que requieren coordinación con sanitarios, policía y otros servicios, y no se aplican solo en el ámbito hospitalario, sino especialmente en el extrahospitalario."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b97") }, {"long_answer": "El Plan de prevención del suicidio pretende fortalecer la equidad y la cohesión del Sistema Nacional de Salud promoviendo la colaboración entre las distintas administraciones, estatal, autonómica y local, y la sociedad civil, incluidas asociaciones de familiares y supervivientes, para que todas las personas tengan acceso a una atención de calidad con independencia de dónde vivan. Centralizar la atención en hospitales de Madrid, excluir a las comunidades autónomas, que tienen las competencias sanitarias, o limitar el acceso a la salud mental son contrarios a la equidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977b9b") }, {"long_answer": "Disponer de un registro de proyectos de investigación sobre conducta suicida permite conocer y centralizar los estudios en marcha, evitar duplicidades, favorecer la colaboración entre grupos y potenciar que los resultados se trasladen a la práctica clínica y a las políticas de prevención. Su objetivo no es elaborar informes para los medios de comunicación. Tampoco se limita a estudios epidemiológicos, ya que incluye investigación clínica, psicosocial y de intervenciones, y no pretende incentivar proyectos sin aplicación práctica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ba0") }, {"long_answer": "El Plan considera los factores sociales y comunitarios fundamentales en la prevención del suicidio: la conexión social, el apoyo de la red familiar y comunitaria y la reducción del aislamiento y de la soledad no deseada actúan como factores protectores frente a la conducta suicida. Por ello es incorrecto afirmar que no tienen influencia significativa. No debilitan la intervención clínica, sino que la complementan, y minimizarlos para priorizar solo los tratamientos individuales iría en contra del enfoque integral del Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ba2") }, {"long_answer": "La formación dirigida a los médicos de atención primaria en el Plan Nacional de Prevención del Suicidio tiene como objetivo mejorar la detección precoz del riesgo suicida y el seguimiento de las personas con conductas suicidas, dado que muchas de ellas consultan en atención primaria en las semanas previas a una tentativa. No pretende disminuir los diagnósticos de salud mental ni limitar las terapias psicológicas. Fomentar derivaciones sin seguimiento es contrario al objetivo de garantizar la continuidad asistencial."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ba4") }, {"long_answer": "Según el modelo de los cinco momentos de la OMS, la primera higiene de manos en la extracción de hemocultivos debe realizarse antes del contacto con el paciente, y nuevamente antes de la técnica aséptica, para evitar la transmisión de microorganismos y la contaminación de la muestra. La higiene después de la exposición a fluidos y después del contacto con el paciente corresponde a momentos posteriores del procedimiento. La retirada de guantes requiere higiene de manos después, no antes, y no constituye el primer momento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ba5") }, {"long_answer": "Antes de la extracción de hemocultivos, el método preferente de higiene de manos es la fricción con solución hidroalcohólica durante 20-30 segundos hasta su secado completo, por su rapidez, eficacia antimicrobiana y mejor tolerancia cutánea. El lavado con agua y jabón durante 40-60 segundos se reserva para cuando las manos están visiblemente sucias o contaminadas con fluidos, por lo que no es el método de elección habitual. El uso de guantes no sustituye la higiene de manos, y el lavado quirúrgico no está indicado en este procedimiento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ba6") }, {"long_answer": "Sí es necesaria la higiene de manos entre cada pareja de hemocultivos: debe realizarse antes de cada extracción, que es una técnica aséptica, y después de la exposición a fluidos corporales, conforme a los momentos de la OMS, para prevenir la contaminación de las muestras y la transmisión de microorganismos. Una sola higiene para todo el procedimiento es insuficiente. La indicación no depende solo de cambiar el punto de punción, y el tipo de guantes empleado no exime de realizarla."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ba8") }, {"long_answer": "La guía no recomienda el uso rutinario de mascarilla quirúrgica durante la extracción de hemocultivos, porque no se ha demostrado que reduzca la tasa de contaminación de las muestras cuando se aplica correctamente la técnica aséptica. Por tanto, no es cierto que siempre deba utilizarse. Su empleo responde a las precauciones de transmisión por gotas o aérea según la situación clínica del paciente, no a la prevención de contaminación del hemocultivo, y no existe indicación específica en pacientes inmunodeprimidos con este fin."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bab") }, {"long_answer": "La guía recomienda aplicar el antiséptico con movimientos de ida y vuelta, frotando de forma enérgica durante unos 30 segundos, y dejarlo secar completamente antes de la punción, ya que la fricción ayuda a que el antiséptico penetre en las capas superficiales de la piel y el secado es necesario para que ejerza su acción. Los movimientos circulares concéntricos desde el centro hacia la periferia son la técnica clásica, pero menos eficaz con clorhexidina alcohólica. La aplicación rápida sin frotar o sin respetar el tiempo de secado reduce la eficacia de la antisepsia.", "option_1": "Aplicación mediante movimientos de ida y vuelta con frotación durante 30 segundos, dejando secar completamente"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bc1") }, {"long_answer": "Si no pueden introducirse de inmediato en el sistema de incubación, los hemocultivos deben mantenerse a temperatura ambiente durante el menor tiempo posible, preferiblemente menos de dos horas y sin superar las 18 horas, ya que los retrasos prolongados reducen la capacidad de detección de los sistemas automatizados. La refrigeración está contraindicada porque puede inhibir el crecimiento de microorganismos exigentes. La incubación en estufa fuera del sistema automatizado puede generar falsos negativos, y nunca deben congelarse."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bca") }, {"long_answer": "El radón se genera en el terreno por la desintegración del radio presente en rocas y suelos, y su principal vía de entrada en los edificios es a través de las grietas y fisuras de suelos y paredes en contacto con el terreno, las juntas y los pasos de instalaciones, favorecida por la diferencia de presión entre el interior y el suelo. El aire acondicionado no es una fuente de radón. La ventilación natural y el aire exterior, con concentraciones bajas, contribuyen a diluirlo, no a aumentarlo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bcb") }, {"long_answer": "Los estudios epidemiológicos, tanto en mineros como los análisis conjuntos de estudios residenciales, describen una relación lineal sin umbral entre la concentración de radón y el riesgo de cáncer de pulmón: el riesgo aumenta de forma proporcional a la exposición y no existe un nivel por debajo del cual sea nulo. Por eso los niveles de referencia no son umbrales de seguridad. No se ha descrito una relación cuadrática con umbral en 150 Bq/m³, el riesgo existe también por debajo de 300 Bq/m³, y la relación no es sigmoidal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bce") }, {"long_answer": "Los descendientes de vida corta del radón 222 que contribuyen a la mayor parte de la dosis por inhalación son el polonio 218, el plomo 214, el bismuto 214 y el polonio 214, que se depositan en el epitelio bronquial y emiten radiación, sobre todo partículas alfa de los isótopos del polonio. El radio 226, el uranio 238, el torio 232 y el potasio 40 son radionúclidos primordiales o precursores. El polonio 210, el plomo 210 y el bismuto 210 son descendientes de vida larga, y el resto de la última opción no pertenece a esta serie de vida corta."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bcf") }, {"long_answer": "El análisis conjunto europeo de estudios de casos y controles se basó en la concentración media de radón a largo plazo en las viviendas ocupadas por cada persona durante los años previos, corrigiendo además la incertidumbre de las mediciones, lo que permitió estimar un aumento del riesgo de cáncer de pulmón del 16% por cada 100 Bq/m³. No se basó en concentraciones puntuales. Sí incluyó el efecto del tabaquismo, ajustando por él y mostrando su interacción con el radón, y no se limitó al radón procedente de los materiales de construcción."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bd3") }, {"long_answer": "El Consejo de Seguridad Nuclear es el organismo responsable de elaborar y actualizar el mapa de potencial de radón de España, que clasifica el territorio según la probabilidad de encontrar concentraciones elevadas en los edificios y sirve de base para delimitar las zonas de actuación prioritaria. El Ministerio de Sanidad coordina el Plan Nacional, pero no elabora el mapa. El Ministerio para la Transición Ecológica y la Federación Española de Municipios y Provincias colaboran en otras acciones del plan, pero no tienen esta responsabilidad técnica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bd5") }, {"long_answer": "Para garantizar la fiabilidad y la calidad de las mediciones de radón, el Plan Nacional contempla la organización periódica de ejercicios de intercomparación entre laboratorios, que permiten verificar que los distintos servicios de medida obtienen resultados exactos y comparables. Las campañas mediáticas y los folletos pertenecen al eje de comunicación y concienciación, no al control de calidad de las mediciones. Reducir el nivel de referencia a 150 Bq/m³ no es una medida del Plan, y los detectores domésticos estándar no aseguran por sí solos la calidad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bd8") }, {"long_answer": "Según el marco normativo recogido en el Plan Nacional, un trabajador debe considerarse expuesto y quedar sujeto a medidas específicas de protección radiológica, como la vigilancia dosimétrica y sanitaria, cuando la dosis efectiva anual debida al radón puede superar los 6 mSv. El valor de 1 mSv al año corresponde al límite de dosis para el público. Los 3 mSv no constituyen un umbral establecido, y los 20 mSv representan el límite máximo de dosis para trabajadores expuestos, no el criterio para clasificarlos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bdb") }, {"long_answer": "Según el Plan Nacional contra el Radón, alrededor del 17% del territorio nacional se considera zona de actuación prioritaria, es decir, área en la que se estima que una proporción significativa de los edificios puede superar los 300 Bq/m³, a partir del mapa de potencial de radón elaborado por el Consejo de Seguridad Nuclear. Estas zonas se concentran sobre todo en áreas graníticas como Galicia, el oeste de Castilla y León, Extremadura y el Sistema Central. El 5% infravalora la extensión de estas zonas, mientras que el 30% y el 50% la sobrestiman."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977be1") }, {"long_answer": "El Plan Nacional contra el Radón señala que en Canarias la geología volcánica es muy heterogénea, de modo que el potencial geogénico de radón puede variar mucho en distancias cortas; por eso la metodología de los mapas se adapta y caracteriza dicho potencial a nivel de parcela, en lugar de asignar un valor homogéneo a todo el municipio. No se limita a medir en plantas superiores, que son precisamente las menos expuestas al radón procedente del suelo, ni se restringe a edificios públicos. Tampoco supone aplicar la normativa estatal sin adaptaciones, ya que la peculiaridad geológica del archipiélago es justamente lo que obliga a modificar el enfoque."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977be2") }, {"long_answer": "El riesgo de cáncer de pulmón atribuible al radón depende de la exposición acumulada, es decir, de la concentración a la que se está expuesto y del tiempo que dura esa exposición a lo largo de la vida. La edad por sí misma no es un factor de riesgo directo: si las personas mayores presentan más casos es porque han acumulado más años de exposición. Es falso que el radón afecte solo a jóvenes, que solo las personas mayores estén expuestas o que sea más frecuente en niños; toda la población que vive o trabaja en espacios cerrados con radón está expuesta, con independencia de su edad."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bea") }, {"long_answer": "En la valoración económica del Plan de ampliación de la cartera común de salud bucodental, el análisis de los programas que ya desarrollaban las comunidades autónomas para la población infantojuvenil estimó un gasto medio total de 53,4 euros por niño o niña atendido. Esta cifra se utilizó como base para calcular el impacto presupuestario de extender las prestaciones a todo el territorio. Los importes de 41,87, 70,75 y 21,36 euros no corresponden al gasto medio total por niño atendido recogido en el documento, sino a valores distintos que no representan esta estimación global."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977beb") }, {"long_answer": "Para estimar el impacto económico de la ampliación de la cartera común de salud bucodental infantil, el Plan asumió una cobertura del 70% de la población diana, ya que no toda la población infantojuvenil acude a los programas aunque tenga derecho a ellos. Aplicar el 100% sobrestimaría el gasto, puesto que la utilización real de este tipo de servicios nunca es universal. Los porcentajes del 50% y del 90% no son los empleados en el cálculo: el primero infraestimaría el uso esperado y el segundo se aleja de la cobertura observada en los programas autonómicos existentes."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977bec") }, {"long_answer": "La cartera común básica de salud bucodental del SNS, tal como la recogía el Real Decreto 1030/2006 y analiza el Plan de ampliación, excluía expresamente el tratamiento reparador de la dentición temporal, es decir, las obturaciones definitivas y los tratamientos pulpares en dientes de leche; esta es una de las carencias que la ampliación pretende corregir. Sí estaban incluidas actuaciones preventivas como la aplicación de flúor tópico y el sellado de fosas y fisuras, así como las exodoncias de piezas temporales, por lo que ninguna de ellas puede considerarse excluida."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c04") }, {"long_answer": "El radón procede fundamentalmente del terreno sobre el que se asienta el edificio, y penetra en el interior principalmente a través de grietas, fisuras, juntas y pasos de instalaciones en soleras, cimientos y muros en contacto con el suelo, impulsado por la diferencia de presión entre el interior y el subsuelo. Los materiales de construcción y el agua de consumo pueden aportar radón, pero su contribución suele ser mucho menor que la del suelo. Abrir las ventanas no es una vía de entrada, sino al contrario una medida que favorece la ventilación y reduce la concentración interior."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c07") }, {"long_answer": "Los estudios epidemiológicos y organismos como la OMS sitúan la exposición a radón como la segunda causa de cáncer de pulmón tras el tabaco, y la primera en personas que nunca han fumado. El radón es un gas radiactivo cuyos descendientes emiten partículas alfa que dañan el epitelio bronquial. El amianto y la contaminación atmosférica son también carcinógenos pulmonares, pero su contribución poblacional al conjunto de casos es inferior. El consumo de alcohol no se considera un factor causal relevante del cáncer de pulmón."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c09") }, {"long_answer": "El informe BEIR VI estableció un modelo lineal sin umbral para la relación entre exposición a radón y cáncer de pulmón, lo que significa que cualquier concentración, por baja que sea, conlleva un incremento del riesgo proporcional a la exposición. Por ello los niveles de referencia no son límites de seguridad, sino valores a partir de los cuales se recomienda actuar. Afirmar que solo las exposiciones altas producen riesgo, que no existe riesgo a concentraciones bajas o que hay un nivel seguro contradice precisamente la idea de ausencia de umbral."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c0a") }, {"long_answer": "El estudio pooling europeo dirigido por Darby combinó los datos individuales de casos y controles de trece estudios realizados en distintos países, reanalizándolos de forma conjunta con una metodología común. Esta fusión de datos individuales aporta mayor potencia estadística y permite ajustar mejor por tabaquismo que un metaanálisis clásico, que solo combina los resultados agregados publicados por cada estudio. No se trata de un estudio transversal, que mide exposición y efecto en un único momento, ni de una serie de casos retrospectiva, que carece de grupo control."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c0d") }, {"long_answer": "El primer estudio de casos y controles sobre radón y cáncer de pulmón realizado en Galicia observó un incremento del riesgo estadísticamente significativo ya a partir de concentraciones de 37 Bq/m³, muy por debajo de los niveles de referencia habituales. Este hallazgo es coherente con la relación sin umbral entre radón y cáncer de pulmón y con la elevada exposición de esta comunidad, de geología granítica. Los valores de 75, 150 y 200 Bq/m³ no corresponden al umbral de significación descrito en dicho estudio, que detectó riesgo a concentraciones claramente inferiores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c0f") }, {"long_answer": "Según los resultados del pooling europeo recogidos en el Libro del Radón, el riesgo de cáncer de pulmón de un fumador expuesto a 400 Bq/m³ se multiplica por unas 42 veces respecto al de un no fumador sin exposición relevante a radón, reflejo del efecto sinérgico, más que aditivo, entre tabaco y radón. Por eso la mayoría de los cánceres de pulmón atribuibles al radón se producen en fumadores. Los valores de 16, 10 y 5 veces infraestiman este efecto combinado y no corresponden a la cifra descrita en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c16") }, {"long_answer": "El Real Decreto 1029/2022, que aprueba el Reglamento sobre protección de la salud contra los riesgos derivados de la exposición a las radiaciones ionizantes, establece que las personas trabajadoras cuya exposición a radón pueda dar lugar a una dosis efectiva superior a 6 mSv al año deben gestionarse como trabajadores expuestos, con vigilancia dosimétrica y sanitaria. El valor de 1 mSv corresponde al límite de dosis para el público, no a este umbral. Las cifras de 3 y 10 mSv no son las que fija la norma para clasificar a un trabajador como expuesto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c1d") }, {"long_answer": "La tomografía computarizada de baja dosis es el método preferente en los programas de cribado de cáncer de pulmón, ya que ensayos como el NLST y el NELSON demostraron que reduce la mortalidad por esta causa en poblaciones de alto riesgo. La radiografía simple de tórax y la citología de esputo no mostraron beneficio en mortalidad como pruebas de cribado por su baja sensibilidad para lesiones precoces. La broncoscopia es una técnica invasiva diagnóstica que no se utiliza de forma rutinaria para el cribado poblacional."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c1e") }, {"long_answer": "El principal motivo por el que la Unión Europea no ha generalizado el cribado de cáncer de pulmón es el balance entre riesgos y beneficios: la tomografía de baja dosis implica una exposición adicional a radiación ionizante y genera falsos positivos y sobrediagnóstico, mientras que el beneficio no está plenamente establecido para todos los grupos de población. El coste importa, pero no es el elemento central del debate. No es cierto que todos los estudios hayan sido negativos, puesto que varios ensayos mostraron reducción de mortalidad, ni que la barrera principal sea la falta de aceptación por los trabajadores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c24") }, {"long_answer": "En trabajadores que nunca han fumado y están expuestos a radón no se justifica actualmente el cribado con tomografía de baja dosis, porque su riesgo absoluto de cáncer de pulmón es mucho menor que el de los fumadores y los beneficios no compensarían los riesgos de la radiación, los falsos positivos y el sobrediagnóstico. La evidencia de beneficio procede de poblaciones con alto consumo tabáquico. Por ello no se recomienda una tomografía anual ni cada cinco años en este grupo, ni existe un criterio de 100 mSv acumulados para indicarla."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c26") }, {"long_answer": "Las estimaciones recogidas en el Libro del Radón atribuyen aproximadamente un 4% de la mortalidad por cáncer de pulmón en España a la exposición excesiva a radón residencial, lo que supone varios cientos de muertes al año y explica que el radón se considere un problema relevante de salud pública. El 1% infraestimaría el impacto observado, mientras que el 10% y el 20% sobreestiman claramente la fracción atribuible a la exposición excesiva, ya que el tabaco sigue siendo responsable de la gran mayoría de los casos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c30") }, {"long_answer": "En la desfibrilación de doble secuencia, el segundo juego de parches se coloca en posición anteroposterior para que la corriente atraviese el corazón en un vector distinto al de la disposición estándar. Según el protocolo, el parche identificado en el envoltorio como «bajo la clavícula derecha» se sitúa en la espalda, en posición vertical bajo la escápula izquierda, mientras que el otro va en la región paraesternal izquierda. Colocarlo bajo la clavícula derecha o en la línea axilar reproduciría el vector anterolateral del primer monitor, y el tórax anterior medio no corresponde a la posición indicada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c31") }, {"long_answer": "En la desfibrilación de doble secuencia el segundo monitor se conecta en disposición anteroposterior. El parche marcado en el envoltorio como «bajo la mamila izquierda» se coloca en posición vertical en la zona paraesternal izquierda, en la cara anterior del tórax, procurando que no toque ni se superponga al electrodo del primer monitor para evitar arcos eléctricos y quemaduras. La línea axilar derecha y la posición horizontal bajo la mamila izquierda corresponden a la colocación estándar del primer juego, y la región lumbar no se utiliza porque el vector no atravesaría el corazón."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c34") }, {"long_answer": "La desfibrilación de doble secuencia se plantea en la fibrilación ventricular refractaria, es decir, la que persiste pese a varias descargas estándar, con el objetivo de aumentar la probabilidad de terminar la arritmia y lograr la recuperación de la circulación espontánea. Para ello se aplican dos descargas casi simultáneas desde dos monitores y con dos vectores distintos. No consiste en dar una única descarga de mayor energía, no busca acortar las compresiones torácicas ni permite prescindir de la ventilación, que deben mantenerse según las recomendaciones de soporte vital avanzado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c35") }, {"long_answer": "Durante la desfibrilación de doble secuencia el segundo monitor debe configurarse con la misma energía que el primero, habitualmente la máxima disponible en cada equipo, de forma que ambas descargas sean equivalentes y se administren de manera secuencial y casi simultánea. No se recomienda reducir la energía del segundo equipo, ya que disminuiría la eficacia del procedimiento, ni duplicar la del primero, algo que además no permiten los desfibriladores. Tampoco es válido usar cualquier valor por encima de 50 J, porque esa cantidad sería insuficiente en una fibrilación ventricular refractaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c36") }, {"long_answer": "Antes de administrar la descarga con el segundo monitor hay que confirmar, en el análisis del ritmo, que este sigue siendo desfibrilable, es decir, fibrilación ventricular o taquicardia ventricular sin pulso; si el ritmo ha cambiado a otro no desfibrilable o hay signos de circulación, la técnica no está indicada. Un pulso palpable contraindica precisamente la descarga. La administración previa de vasopresor no es un requisito para realizarla, y las compresiones no deben interrumpirse durante 30 segundos, ya que las pausas han de ser mínimas para preservar la perfusión."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c3d") }, {"long_answer": "El protocolo de desfibrilación de doble secuencia incluye la rasuradora entre el material necesario para eliminar el vello de las zonas donde se van a colocar los parches del segundo monitor, sobre todo en la espalda y la región paraesternal. Así se garantiza una buena adherencia y un contacto eléctrico adecuado, se reduce la impedancia transtorácica y se evitan arcos y quemaduras. No se utiliza para limpiar la piel, que se seca si está húmeda, ni para cortar la ropa, para lo que se emplean tijeras, ni para marcar puntos anatómicos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c3e") }, {"long_answer": "El protocolo de desfibrilación de doble secuencia incluye un esquema específico, la figura 2, en el que se muestra la colocación del segundo juego de electrodos en disposición anteroposterior, complementaria a la anterolateral del primer monitor que se ilustra en la figura 1. Por ello no es correcto usar la figura 1 para ambas secuencias, ya que reproduciría el mismo vector. Tampoco se trata de una figura internacional que se aplique sin cambios, ni los parches se colocan libremente, puesto que su posición condiciona la eficacia y la seguridad de la técnica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c3f") }, {"long_answer": "La desfibrilación de doble secuencia se plantea cuando el ritmo sigue siendo desfibrilable tras tres descargas estándar, situación que define la fibrilación ventricular refractaria en la que la técnica puede aportar beneficio. El criterio es clínico y está protocolizado, por lo que no depende de una autorización adicional, aunque el equipo deba coordinarse. No se vincula a la segunda dosis de adrenalina, que sigue su propia pauta dentro del algoritmo de soporte vital avanzado, ni a haber completado media hora de reanimación, lo que retrasaría innecesariamente la intervención."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c40") }, {"long_answer": "Para iniciar la desfibrilación de doble secuencia no se apaga ni se reconfigura a la baja el primer monitor: se mantiene encendido con sus parches anterolaterales y con la misma energía que el segundo, habitualmente la máxima, para que las dos descargas se apliquen de forma secuencial y casi simultánea por vectores distintos. Usar solo el segundo monitor eliminaría el fundamento de la técnica, y bajar la energía de uno de los equipos restaría eficacia. Cambiar al modo de cardioversión sincronizada no procede en la fibrilación ventricular, que no tiene complejos QRS con los que sincronizar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c42") }, {"long_answer": "La función de emplear dos monitores desfibriladores es aplicar dos descargas eléctricas casi simultáneas, cada una por un vector distinto, para aumentar la probabilidad de terminar una fibrilación ventricular refractaria a las descargas estándar. Se busca despolarizar una mayor masa miocárdica y superar posibles problemas de vector o de umbral. No pretende acortar la reanimación a menos de cinco minutos, ni sustituye la administración de fármacos intravenosos, que siguen indicados según el algoritmo. Tampoco tiene relación con la sincronización de marcapasos internos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c43") }, {"long_answer": "Durante la desfibrilación de doble secuencia, como en cualquier desfibrilación, deben evitarse las superficies metálicas sin aislamiento y las superficies mojadas, porque conducen la corriente y aumentan el riesgo de descargas accidentales al personal y de quemaduras al paciente. Una superficie dura es en realidad deseable para que las compresiones torácicas sean eficaces, mientras que una superficie blanda y acolchada las hace menos efectivas, pero no supone un riesgo eléctrico específico. Las superficies plásticas son aislantes y no plantean problema."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c44") }, {"long_answer": "Los parches del segundo monitor se colocan durante el intervalo de dos minutos de compresiones torácicas que sigue a la tercera descarga estándar, de manera que, si en el siguiente análisis persiste un ritmo desfibrilable, la doble secuencia pueda aplicarse sin demora y sin interrumpir la reanimación. Colocarlos antes de la primera descarga no procede, porque la técnica solo se indica en la fibrilación ventricular refractaria. Esperar a la sexta descarga o al décimo minuto retrasaría innecesariamente una intervención cuya eficacia depende de aplicarla precozmente."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c4b") }, {"long_answer": "En la población infantil con condiciones de alto riesgo de enfermedad grave por VRS, las recomendaciones de inmunización con nirsevimab indican su administración antes del inicio de cada temporada de VRS mientras el niño tenga menos de 24 meses de edad cronológica, de modo que puede recibir una dosis en su primera y otra en su segunda temporada. Restringirla a los menores de 6 meses o a la primera temporada dejaría sin protección a este grupo vulnerable. Nirsevimab es una medida preventiva, no un tratamiento, por lo que no se administra cuando aparecen síntomas respiratorios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c4d") }, {"long_answer": "La dosis de nirsevimab en lactantes durante su primera temporada de VRS depende del peso: 50 mg intramusculares en dosis única si pesan menos de 5 kg y 100 mg si pesan 5 kg o más. Por tanto, un lactante de 4,5 kg debe recibir 50 mg. La dosis de 100 mg corresponde a los lactantes de 5 kg o más en su primera temporada. La de 200 mg, administrada en dos inyecciones de 100 mg, se reserva para los niños vulnerables de 10 kg o más en su segunda temporada; los de menos de 10 kg reciben entonces 100 mg. La cifra de 25 mg no es una dosis autorizada."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c58") }, {"long_answer": "En la población infantil con condiciones de alto riesgo de enfermedad grave por VRS, como cardiopatías congénitas significativas, displasia broncopulmonar o inmunodepresión grave, nirsevimab se recomienda antes de cada temporada mientras el niño tenga menos de 24 meses de edad cronológica, cubriendo así su segunda temporada. El criterio de menores de 6 meses se aplica a la población general nacida fuera de temporada, y el de menores de 12 meses no cubriría la segunda temporada de estos niños. Los 36 meses superan la edad para la que está indicado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c59") }, {"long_answer": "Entre las condiciones de alto riesgo que justifican la inmunización con nirsevimab en menores de 24 meses se incluyen, además de cardiopatías congénitas significativas y displasia broncopulmonar, las enfermedades oncohematológicas y las inmunodeficiencias primarias, como las combinadas, por el elevado riesgo de infección grave por VRS. No se limita a la prematuridad, que es un criterio de riesgo en la primera temporada, ni solo a las cardiopatías cianosantes, ya que se incluyen también las hemodinámicamente significativas. El asma intermitente y las alergias nasales no son condiciones de riesgo para esta indicación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c5a") }, {"long_answer": "La actualización de las recomendaciones de nirsevimab señala que, tras su uso masivo en la temporada 2023-2024 en España y otros países, la farmacovigilancia no ha identificado nuevas señales ni riesgos adicionales de seguridad respecto a los observados en los ensayos clínicos, en los que el perfil fue favorable con reacciones locales leves y exantema poco frecuente. Por ello no es cierto que se hayan detectado nuevas señales, que la seguridad sea inferior a la de los ensayos o que se recomiende suspender su uso; al contrario, se mantiene y amplía la recomendación de inmunización."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c60") }, {"long_answer": "Los estudios de efectividad realizados en España durante la primera temporada de uso de nirsevimab mostraron una reducción de las hospitalizaciones por VRS de alrededor del 80% en los lactantes inmunizados, con resultados consistentes entre distintas comunidades autónomas y con los observados en otros países. Las cifras del 10-20% o del 50-60% infravaloran claramente el efecto observado. Tampoco es cierto que no existan datos, ya que la experiencia española fue de las primeras en evaluar su impacto en condiciones reales a gran escala."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c65") }, {"long_answer": "Según las recomendaciones del Ministerio de Sanidad, en la segunda temporada de VRS los niños que siguen siendo vulnerables reciben una dosis de nirsevimab según el peso: si pesan 10 kg o más, 200 mg administrados en dos inyecciones intramusculares de 100 mg en el mismo acto y en lugares distintos; si pesan menos de 10 kg, una única inyección de 100 mg. Los recién nacidos de menos de 5 kg en su primera temporada reciben una única dosis de 50 mg. La pauta no se limita a prematuros de menos de 29 semanas, y es falso que nunca se divida la dosis, ya que la de 200 mg se administra precisamente en dos inyecciones.", "option_2": "En la segunda temporada de VRS en niños con condiciones de alto riesgo que pesan 10 kg o más", "question": "¿En qué contexto se administra nirsevimab en forma de dos inyecciones de 100 mg en el mismo acto?"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c66") }, {"long_answer": "Los estudios realizados en España durante la temporada 2023-2024 mostraron que nirsevimab, además de reducir las hospitalizaciones, disminuyó de forma significativa las infecciones por VRS atendidas en atención primaria y en urgencias, lo que confirma su beneficio también en las formas menos graves de la enfermedad y su impacto en la carga asistencial. Por eso no es correcto afirmar que no tenga impacto relevante o que solo actúe sobre las hospitalizaciones. Tampoco aumenta la detección de VRS; al contrario, reduce los casos diagnosticados en los lactantes inmunizados.", "option_2": "Reducción significativa también de las infecciones por VRS atendidas en atención primaria"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c69") }, {"long_answer": "El Marco Estratégico para los Cuidados de Enfermería distingue entre cuidado informal, prestado habitualmente por familiares o personas del entorno sin remuneración, y cuidado formal, que proporcionan profesionales remunerados que no forman parte del entorno cercano de la persona cuidada. La definición que corresponde al familiar que cuida voluntariamente sin retribución es la de cuidador informal. Los voluntarios comunitarios no son cuidadores formales al no estar remunerados, y la definición no depende de tener un título universitario, sino del carácter profesional y retribuido del cuidado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c6b") }, {"long_answer": "El análisis de situación del Marco Estratégico para los Cuidados de Enfermería recoge, a partir del Barómetro Sanitario, que la población adulta valora la atención prestada por las enfermeras de atención primaria con una puntuación media de 8,13 sobre 10, una de las más altas entre los servicios del SNS. Este dato refleja el elevado reconocimiento ciudadano del trabajo enfermero. Las puntuaciones de 5,5 y 7,2 infravaloran la satisfacción descrita en el documento, y 9,5 la sobrestima, por lo que ninguna corresponde a la cifra recogida.", "question": "Según el análisis del Marco Estratégico, ¿qué puntuación media (sobre 10) otorga la población adulta del SNS a la atención de enfermería en atención primaria?"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c6e") }, {"long_answer": "La Enfermería Obstétrico-Ginecológica (Matrona) es una de las especialidades de Enfermería oficialmente reconocidas en España, junto con Salud Mental, Geriátrica, del Trabajo, Cuidados Médico-Quirúrgicos, Familiar y Comunitaria y Pediátrica, conforme al Real Decreto 450/2005 que desarrolla el marco de la Ley 44/2003 de Ordenación de las Profesiones Sanitarias. La Enfermería Veterinaria y la Enfermería Dental no existen como especialidades enfermeras, ya que esos ámbitos corresponden a otras profesiones. La Enfermería de Terapias Alternativas tampoco es una especialidad oficial.", "question": "En el marco de la Ley 44/2003 de Ordenación de las Profesiones Sanitarias y su desarrollo normativo (RD 450/2005), ¿cuál es una de las especialidades de Enfermería oficialmente reconocidas?"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c70") }, {"long_answer": "La línea estratégica sobre la situación de las necesidades de salud y la adecuación de los recursos humanos tiene como objetivo determinar la dotación de enfermeras necesaria para garantizar cuidados seguros y de calidad, teniendo en cuenta tanto las necesidades actuales de la población como las futuras, condicionadas por el envejecimiento y la cronicidad. No se centra en los recursos tecnológicos ni en la investigación de nuevas enfermedades. Reducir costes tampoco es su finalidad; la evidencia muestra que dotaciones insuficientes empeoran los resultados en salud."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c73") }, {"long_answer": "El Marco Estratégico recomienda que el modelo de práctica profesional se oriente a la atención centrada en la persona, respetando su autonomía, sus valores y preferencias y favoreciendo su participación en decisiones informadas sobre sus cuidados. Limitarse a protocolos hospitalarios ignora la diversidad de ámbitos asistenciales, especialmente la atención primaria y comunitaria. Excluir al paciente de las decisiones contradice el principio de autonomía y el derecho a la información, y restringir la atención primaria iría en contra del refuerzo de este nivel asistencial que defiende el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c81") }, {"long_answer": "La participación ciudadana en el diseño y seguimiento del Marco Estratégico es relevante porque aumenta la transparencia y la rendición de cuentas, y permite que los cuidados se ajusten a las necesidades y expectativas reales de las personas, que son sus destinatarias. Es un principio de buena gobernanza sanitaria con impacto práctico, no un mero requisito formal. No pretende sustituir el papel de los profesionales, cuya competencia técnica sigue siendo imprescindible, ni añadir complejidad administrativa sin resultados, sino mejorar la calidad y la legitimidad de las políticas de cuidados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c82") }, {"long_answer": "Según el Comité de Cuidados en Salud, el modelo de práctica profesional consensuado debe recoger la misión, las poblaciones diana, las trayectorias profesionales, la forma de prestación de los cuidados, el liderazgo y la evaluación del impacto, de manera que ofrezca un marco integral para organizar y desarrollar la práctica enfermera. Limitarlo a los protocolos hospitalarios o a la formación inicial universitaria dejaría fuera elementos esenciales como el liderazgo o la evaluación. La supuesta falta de interés de la población por los cuidados no es un contenido del modelo, sino una afirmación sin fundamento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c87") }, {"long_answer": "El Marco Estratégico plantea que los cuidados del siglo XXI deben incorporar un concepto de salud más amplio e integrado, entendido como la capacidad de adaptación y autogestión ante los retos físicos, mentales y sociales, que incluye la calidad de vida y la autodeterminación de las personas. Mantener la definición clásica de salud como ausencia de enfermedad resulta insuficiente ante la cronicidad y el envejecimiento. Limitarse a cuidados médicos sin considerar los determinantes sociales o eliminar la promoción del autocuidado iría en contra de los principios del documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c8e") }, {"long_answer": "En el cáncer de cuello uterino en estadio inicial de bajo riesgo, definido por tumor menor de 2 cm, ausencia de invasión linfovascular e infiltración estromal inferior al 50%, la guía recomienda la histerectomía tipo A o simple extrafascial, ya que la evidencia, incluido el ensayo SHAPE, muestra resultados oncológicos equivalentes a la histerectomía radical con menos morbilidad. Las histerectomías radicales tipo B2 y C1 suponen un sobretratamiento en este escenario. La traquelectomía radical es una alternativa conservadora reservada a pacientes con deseo gestacional, no la recomendación general."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c90") }, {"long_answer": "El verde de indocianina es el trazador recomendado para la biopsia selectiva del ganglio centinela en cáncer de cuello uterino porque ofrece las tasas más altas de detección bilateral, identificado mediante cámara de fluorescencia de infrarrojo cercano. El azul de metileno o los colorantes azules tienen menores tasas de detección cuando se usan solos. El tecnecio-99m es útil, sobre todo combinado con colorante, pero su uso aislado no supera al verde de indocianina en detección bilateral. El yodo-131 no se emplea como trazador para esta técnica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c91") }, {"long_answer": "Ante un ganglio centinela positivo en el estudio intraoperatorio del cáncer de cuello uterino se recomienda abandonar la cirugía sobre el útero, ya que la paciente necesitará radioquimioterapia y combinar histerectomía radical con radioterapia aumenta la morbilidad sin mejorar la supervivencia; en ese caso se completa la estadificación ganglionar. Un tumor menor de 2 cm o un estadio IA1 sin invasión linfovascular son situaciones favorables en las que la cirugía está indicada. La ausencia de drenaje unilateral obliga a realizar la linfadenectomía de ese lado, no a suspender la cirugía."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c96") }, {"long_answer": "La guía recomienda la laparotomía como vía de abordaje para los procedimientos radicales que incluyen la extirpación del parametrio en el cáncer de cuello uterino, porque el ensayo LACC demostró peor supervivencia libre de enfermedad y global con la cirugía mínimamente invasiva, tanto laparoscópica como robótica. Por ello la cirugía robótica no es la vía recomendada para la histerectomía radical. La cirugía vaginal no es el abordaje estándar para estos procedimientos, y la quimioterapia neoadyuvante es un tratamiento sistémico, no una vía quirúrgica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c98") }, {"long_answer": "La radioterapia de intensidad modulada (IMRT) y su variante volumétrica en arco (VMAT) permiten adaptar la distribución de la dosis al volumen tumoral con gran precisión, reduciendo la irradiación de órganos de riesgo como el intestino, la vejiga, el recto y la médula ósea, lo que disminuye la toxicidad aguda y tardía. La radioterapia convencional 2D tiene una conformación muy inferior. La radioterapia intraoperatoria exclusiva no es un tratamiento estándar del cáncer de cuello uterino, y la terapia con radionúclidos no se emplea en esta indicación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c9b") }, {"long_answer": "Para la técnica del ganglio centinela en cáncer de cuello uterino se recomienda inyectar el trazador en el cérvix, de forma superficial y peritumoral, en los cuatro cuadrantes o al menos a las 3 y a las 9 horarias, lo que favorece un drenaje bilateral representativo hacia los ganglios pélvicos. Inyectar solo en un lado reduciría la detección bilateral. La inyección directa en el tumor visible no se recomienda porque altera el drenaje linfático, y la inyección en la vagina distal no refleja el drenaje cervical."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c9d") }, {"long_answer": "La conservación ovárica puede plantearse en mujeres jóvenes con cáncer de cuello uterino, pero el adenocarcinoma independiente del VPH, como el de tipo gástrico, la contraindica por su mayor riesgo de diseminación y de metástasis ováricas. La edad menor de 45 años es, al contrario, una de las situaciones en las que se valora preservar los ovarios para evitar la menopausia precoz. Un tumor en estadio pT1a tiene bajo riesgo de afectación ovárica, y la histología escamosa se asocia a metástasis ováricas muy infrecuentes, por lo que no contraindican la conservación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c9f") }, {"long_answer": "En la clasificación de Querleu-Morrow, la histerectomía radical tipo C1 corresponde a la técnica con preservación nerviosa, en la que se respeta la porción del plexo hipogástrico responsable de la inervación vesical, lo que reduce la disfunción urinaria posoperatoria. La tipo C2 implica una resección completa del parametrio sin preservación de estos nervios. La tipo B2 es una histerectomía radical modificada con linfadenectomía paracervical, y la tipo A es la histerectomía simple extrafascial, que no incluye resección parametrial y no se define por la preservación nerviosa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ca5") }, {"long_answer": "En el cáncer de cuello uterino localmente avanzado con ganglios pélvicos positivos y paraaórticos negativos en las pruebas de imagen, la guía recomienda la linfadenectomía paraaórtica de estadificación por vía mínimamente invasiva hasta la arteria mesentérica inferior, ya que la PET-TC tiene falsos negativos y detectar afectación aórtica oculta permite ampliar el campo de radioterapia. La PET-TC sola no permite descartar enfermedad microscópica. La biopsia de ganglio centinela no está validada en tumores avanzados, y la exploración física sin imagen es insuficiente para estadificar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ca9") }, {"long_answer": "En mujeres con síntomas climatéricos tras el tratamiento del cáncer de cuello uterino puede utilizarse terapia hormonal sistémica, ya que este tumor en su mayoría no es hormonodependiente, empleando la dosis mínima eficaz para controlar los síntomas. Si se ha realizado histerectomía bastan los estrógenos solos, y si se conserva el útero, por ejemplo tras radioterapia, deben asociarse gestágenos para proteger el endometrio. Por eso es incorrecto usar estrógenos solos en todas o considerarla una contraindicación absoluta, y limitarse a la terapia local no controlaría los síntomas vasomotores."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cad") }, {"long_answer": "La escala de Bishop valora la dilatación, el borramiento, la consistencia y la posición del cérvix y la altura de la presentación, con una puntuación máxima de 13. Según la escala de referencia, una puntuación de 7 o más indica un cuello favorable, con alta probabilidad de éxito de la inducción del parto con oxitocina y amniorrexis, mientras que puntuaciones inferiores aconsejan maduración cervical previa con prostaglandinas. Las puntuaciones de 3 o 5 corresponden a un cuello desfavorable, y exigir 10 o más puntos sería demasiado restrictivo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cb0") }, {"long_answer": "En el test de O'Sullivan se administran 50 g de glucosa oral y se mide la glucemia a la hora; un valor igual o superior a 140 mg/dL se considera positivo y obliga a realizar la prueba confirmatoria de sobrecarga oral con 100 g de glucosa para diagnosticar diabetes gestacional. El punto de corte de 120 mg/dL no es el utilizado, y los de 160 o 180 mg/dL dejarían sin confirmar a muchas gestantes con alteración del metabolismo de la glucosa."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cb1") }, {"long_answer": "La escala de satisfacción del parto de Mackey es un instrumento que evalúa la satisfacción y la experiencia de la mujer con el proceso de parto, incluyendo aspectos como la atención recibida por los profesionales, la participación en las decisiones, el confort y la relación con el recién nacido. No mide la duración del parto, que se registra en el partograma, ni la intensidad del dolor, para lo que se utilizan escalas como la EVA. Tampoco detecta el riesgo de depresión posparto, que se valora con la escala de Edimburgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cb3") }, {"long_answer": "El test de Malinas valora la paridad, la duración del trabajo de parto, la duración y la frecuencia de las contracciones y la rotura de bolsa para estimar la inminencia del parto. Una puntuación alta indica que el parto es inminente, por lo que el traslado puede ser arriesgado y debe valorarse la asistencia in situ o un traslado urgente con preparación para atender el parto en el trayecto. No indica trabajo de parto retrasado ni riesgo bajo, que se asocian a puntuaciones bajas, ni sirve para indicar una inducción farmacológica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cb9") }, {"long_answer": "La escala RASS (Richmond Agitation-Sedation Scale) va de +4 a -5, donde 0 corresponde al paciente alerta y tranquilo. La puntuación de +4 define la agitación combativa, con conducta violenta y peligro inmediato para el personal. La somnolencia corresponde a -1, la sedación profunda a -4, en la que el paciente no responde a la voz pero sí a la estimulación física, y la ausencia de respuesta a cualquier estímulo, equivalente al coma, a -5."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cc2") }, {"long_answer": "La escala de Morse valora el riesgo de caídas a partir de seis ítems: antecedentes de caídas, diagnóstico secundario, ayuda para deambular, terapia intravenosa, tipo de marcha y estado mental. Según la escala de referencia, una puntuación superior a 45, es decir, de 46 o más puntos, indica alto riesgo de caída y obliga a implantar medidas preventivas específicas. Las puntuaciones por debajo de 25 corresponden a ausencia de riesgo o riesgo bajo, y las situadas entre 25 y 45 a riesgo moderado, por lo que ninguna indica riesgo alto."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cc6") }, {"long_answer": "En la escala ASIA (AIS) de lesión medular, el grado A corresponde a una lesión completa, sin función motora ni sensitiva preservada en los segmentos sacros S4-S5. El grado B es una lesión incompleta con sensibilidad conservada pero sin función motora por debajo del nivel lesional. El grado C es incompleto con función motora preservada, pero con más de la mitad de los músculos clave con fuerza inferior a 3. El grado E indica función motora y sensitiva normal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cc8") }, {"long_answer": "La escala qSOFA valora tres criterios: frecuencia respiratoria de 22 o más por minuto, alteración del estado mental y presión arterial sistólica de 100 mmHg o menos. Una puntuación de 2 o más en un paciente con sospecha de infección identifica un alto riesgo de mala evolución, con mayor probabilidad de disfunción orgánica, estancia prolongada en UCI o muerte, y obliga a una valoración urgente. No indica bajo riesgo ni ausencia de deterioro, y tampoco es diagnóstica de sepsis, que requiere un aumento de 2 o más puntos en la escala SOFA."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cca") }, {"long_answer": "El cuestionario PHQ-9 consta de nueve ítems basados en los criterios diagnósticos de depresión mayor del DSM y pregunta por la frecuencia de los síntomas durante las dos semanas previas, permitiendo detectar la depresión y graduar su intensidad. La ansiedad se evalúa con instrumentos como el GAD-7, no con el PHQ-9. El trastorno bipolar requiere una valoración clínica específica de episodios maníacos o hipomaníacos, y la adherencia al tratamiento se mide con otros cuestionarios, como el de Morisky-Green."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ccb") }, {"long_answer": "El cuestionario AUDIT consta de diez preguntas y su puntuación va de 0 a 40. Una puntuación entre 20 y 40 indica probable dependencia del alcohol y aconseja derivación para evaluación diagnóstica y tratamiento especializado. El rango de 0 a 7 corresponde a consumo de bajo riesgo, el de 8 a 15 a consumo de riesgo, en el que se recomienda intervención breve, y el de 16 a 19 a consumo perjudicial, que requiere intervención breve y seguimiento, pero no indica por sí mismo dependencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ccc") }, {"long_answer": "La escala de Karnofsky evalúa el estado funcional del paciente oncológico, es decir, su capacidad para realizar actividades habituales y de autocuidado y su grado de dependencia, con puntuaciones de 0 a 100 en intervalos de 10. Tiene valor pronóstico y se utiliza para decidir tratamientos. No mide la severidad del dolor, para lo que se usan escalas como la EVA, ni constantes vitales como la presión arterial o la frecuencia cardíaca, ni específicamente la calidad de vida emocional, que requiere cuestionarios propios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cd1") }, {"long_answer": "El Boletín de indicadores clave del Plan Nacional sobre Drogas define el consumo intensivo de alcohol o binge drinking como la ingesta de cinco o más bebidas alcohólicas en una misma ocasión, entendiendo como tal un intervalo aproximado de dos horas. Este patrón produce intoxicaciones agudas y es especialmente dañino en adolescentes. Tres bebidas sin límite de tiempo no cumplen la definición, una bebida en menos de una hora es un consumo puntual, y el primer consumo de alcohol es un indicador de edad de inicio, no de consumo intensivo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cda") }, {"long_answer": "Según el Boletín de indicadores clave del Plan Nacional sobre Drogas, el uso de fármacos opioides sin receta en la población adulta se mantuvo estable en torno al 0,6% entre 2020 y 2024, un nivel bajo pero vigilado por el riesgo de dependencia y sobredosis asociado a estos medicamentos. Los porcentajes del 1%, el 2% y el 3,5% no corresponden a la prevalencia recogida en el documento, sino que sobrestiman el uso no prescrito de estos fármacos en España."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cdb") }, {"long_answer": "El Boletín de indicadores clave del Plan Nacional sobre Drogas recoge que en 2024 el 9,2% de la población adulta declaró haber consumido alguna droga ilegal en el último mes, siendo el cannabis la sustancia que más contribuye a esta cifra. Los porcentajes del 7,7%, el 8,7% y el 9,6% son valores cercanos que no corresponden al dato de 2024 del documento, por lo que conviene memorizar la cifra exacta, ya que este tipo de indicadores se suelen preguntar con distractores próximos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ce0") }, {"long_answer": "Según el Boletín de indicadores clave del Plan Nacional sobre Drogas, la proporción de adultos con posible trastorno por juego problemático disminuyó entre 2018 y 2024, pasando del 2,6% al 1,4%. Este descenso se ha relacionado, entre otros factores, con las medidas de regulación de la publicidad del juego. No es correcto afirmar que aumentó del 1,4% al 2,6%, ya que es la tendencia inversa, ni que se mantuviera estable en el 2,0% o que no se haya registrado ninguna tendencia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ce1") }, {"long_answer": "El Boletín de indicadores clave del Plan Nacional sobre Drogas estima que en 2024 el 1,4% de la población adulta presentaba un posible trastorno por consumo de cannabis, identificado mediante el cuestionario CAST, que detecta consumo problemático entre quienes han consumido cannabis en el último año. Las cifras del 1,9%, el 2,2% y el 0,9% no corresponden al dato de 2024 recogido en el documento. Hay que distinguir este indicador del consumo de cannabis en el último mes, que es bastante más elevado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ce2") }, {"long_answer": "Según el Boletín de indicadores clave del Plan Nacional sobre Drogas, la proporción de adultos con posible trastorno por consumo de cocaína en 2024 fue del 0,2%, una cifra baja en comparación con la del cannabis, aunque relevante por la gravedad clínica y social de esta dependencia. Los porcentajes del 0,3%, el 0,4% y el 0,5% son valores próximos que no corresponden al dato recogido en el documento, por lo que deben descartarse."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ce6") }, {"long_answer": "El Boletín de indicadores clave del Plan Nacional sobre Drogas, con datos de la Dirección General de Tráfico y del Instituto Nacional de Toxicología, recoge que en 2021 el 30,7% de los conductores implicados en siniestros mortales dieron positivo en las pruebas de alcohol, lo que muestra el peso del alcohol en la siniestralidad vial grave. Los porcentajes del 26,1%, el 24% y el 27% no corresponden al dato de 2021 de este indicador, por lo que deben descartarse."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ceb") }, {"long_answer": "Para la Dirección General de Tráfico, un resultado positivo en las pruebas de alcohol de los conductores implicados en siniestros mortales significa que se superan las tasas máximas permitidas para ese conductor, que varían según su tipología y circunstancias, como en conductores noveles o profesionales, con límites más estrictos. Por tanto no basta con la presencia de cualquier cantidad de alcohol, ni se considera positivo un consumo por debajo de la tasa legal. Tampoco es necesario superar el doble del límite, umbral asociado a otras consecuencias legales."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977ced") }, {"long_answer": "El AUDIT (Alcohol Use Disorders Identification Test), desarrollado por la OMS, es el instrumento utilizado para identificar el consumo de riesgo de alcohol en adultos, así como el consumo perjudicial y la probable dependencia, y es el que emplea la encuesta EDADES. El CAST (Cannabis Abuse Screening Test) se utiliza para detectar consumo problemático de cannabis, no de alcohol. Los criterios DSM-5 para el juego valoran el juego problemático, y la entrevista clínica estructurada es una herramienta diagnóstica, no un instrumento poblacional de cribado.", "option_1": "Cuestionario AUDIT", "option_2": "Cuestionario CAST"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cee") }, {"long_answer": "El Boletín de indicadores clave del Plan Nacional sobre Drogas recoge que en 2022 la proporción de adultos con posible trastorno por consumo de cannabis, medido con la escala CAST, fue del 1,6%, cifra que descendió al 1,4% en 2024. Por ello el 1,4% es un distractor que corresponde a la medición posterior, y no al dato de 2022. Los porcentajes del 1,9% y el 2,2% no corresponden a ninguno de los registros de este indicador recogidos en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cf4") }, {"long_answer": "La elaboración y el uso de Guías de Práctica Clínica en el SNS, incluida la de atención al parto normal, se enmarcan en la Estrategia décima del Plan de Calidad para el Sistema Nacional de Salud, dedicada a la mejora de la práctica clínica, cuyo objetivo es reducir la variabilidad injustificada y basar las decisiones en la mejor evidencia disponible. Las demás opciones mencionan áreas como infraestructuras, formación continua o investigación biomédica, que no corresponden a la estrategia en la que el Plan sitúa el programa de Guías de Práctica Clínica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977cfd") }, {"long_answer": "La Guía de Práctica Clínica sobre la atención al parto normal ofrece recomendaciones elaboradas mediante una revisión sistemática de la evidencia científica, clasificadas según su nivel de evidencia y graduadas en función de la fuerza de la recomendación. No se basa en experiencias anecdóticas, que son precisamente el tipo de práctica que las guías pretenden superar. Sus recomendaciones no son de cumplimiento obligatorio, ya que no sustituyen el juicio clínico, y van dirigidas a todos los profesionales que atienden el parto, no solo a enfermería."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d05") }, {"long_answer": "Los datos de edición de la versión resumida de la Guía de Práctica Clínica sobre la atención al parto normal indican una tirada de 2.700 ejemplares destinados a su difusión general entre los profesionales y servicios del SNS. No se trata de una edición limitada a expertos ni de una tirada para distribución internacional. Tampoco es exclusivamente digital, aunque la guía puede consultarse además en formato electrónico a través de GuíaSalud y de las páginas institucionales.", "option_2": "2.700 ejemplares para difusión general"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d06") }, {"long_answer": "El grupo que elaboró la Guía de Práctica Clínica sobre la atención al parto normal fue multidisciplinar, con profesionales de distintas Comunidades Autónomas implicados en la atención al parto, como obstetras, matronas, enfermeras, pediatras y anestesiólogos, además de representantes de asociaciones de usuarias como «El parto es nuestro». Los cirujanos maxilofaciales no formaron parte del grupo, ya que su especialidad no interviene en la atención al parto normal. Por eso la respuesta correcta es la que los menciona, mientras que las demás opciones corresponden a perfiles implicados en la elaboración.", "option_2": "Pediatras y anestesiólogos", "option_3": "Enfermeras y representantes de asociaciones de usuarias"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d0c") }, {"long_answer": "La Guía de Práctica Clínica sobre la atención al parto normal se elaboró en colaboración con OSTEBA, la agencia de evaluación de tecnologías sanitarias del País Vasco, y por ello su registro bibliográfico se remite al catálogo de la Biblioteca General del Gobierno Vasco, accesible en http://www.euskadi.net/ejgvbiblioteka. Las páginas del Ministerio de Sanidad, de GuíaSalud o de OSTEBA permiten consultar o descargar la guía y otros documentos, pero no son el recurso que el documento indica para consultar el registro bibliográfico de la obra original."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d10") }, {"long_answer": "La presentación de la Guía de Práctica Clínica sobre la atención al parto normal señala que su aplicación pretende mejorar la calidad de la atención y aumentar la satisfacción tanto de los profesionales como de las mujeres y sus familias, favoreciendo un parto con menos intervenciones innecesarias y más participación de la mujer. No promete eliminar por completo la mortalidad materna, objetivo irreal, ni fijar una duración máxima del parto. Tampoco busca aumentar la anestesia general, que no es una técnica de analgesia del parto normal."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d14") }, {"long_answer": "La guía de práctica clínica sobre extracción de hemocultivos recomienda utilizar guantes estériles durante el procedimiento, ya que la evidencia muestra que reducen la tasa de contaminación, especialmente cuando es necesario volver a palpar la vena tras la antisepsia de la piel. Los guantes de látex no estériles ofrecen protección al profesional pero no garantizan la asepsia de la zona de punción. Los guantes reutilizables no son apropiados para procedimientos clínicos, y no utilizar guantes incumple las precauciones estándar y aumenta el riesgo de contaminación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d1c") }, {"long_answer": "Cuando se extrae sangre para hemocultivos y para otras analíticas en la misma punción, se recomienda inocular primero los frascos de hemocultivo, ya que los tubos de analítica no son estériles por fuera ni por dentro y pueden contaminar la aguja o el sistema, aumentando la probabilidad de falsos positivos. Por esa razón no es indiferente el orden y no deben extraerse antes las analíticas generales. La recogida de orina es una muestra distinta que no se intercala en la extracción de sangre."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d1e") }, {"long_answer": "En adultos con sospecha de bacteriemia se recomienda extraer como mínimo dos parejas de hemocultivos, cada una formada por un frasco aerobio y otro anaerobio, obtenidas preferentemente de punciones distintas. Así se alcanza el volumen de sangre necesario para una buena sensibilidad y se facilita distinguir una bacteriemia verdadera de una contaminación, ya que un microorganismo de la piel en un solo frasco sugiere contaminación. Un único frasco o una única muestra reduce la rentabilidad diagnóstica, y tres parejas no son necesarias de forma rutinaria."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d27") }, {"long_answer": "Tras inocular la sangre en los frascos de hemocultivo se recomienda mezclar su contenido mediante inversión suave varias veces, para que la sangre se distribuya en el medio de cultivo con anticoagulante y se eviten coágulos que dificulten el crecimiento bacteriano y la detección. Mantener los frascos quietos favorece la coagulación de la muestra. La mezcla se aplica a los frascos aerobios y anaerobios por igual, y una agitación suave no rompe el frasco ni daña la muestra."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d2d") }, {"long_answer": "Cuando no es posible introducir los hemocultivos de inmediato en el sistema automatizado del laboratorio, la mejor opción es utilizar incubadoras automáticas satélite que permiten iniciar la incubación y la monitorización sin demora, o mantenerlos a temperatura ambiente durante un tiempo limitado. Los hemocultivos nunca deben refrigerarse ni congelarse, porque las bajas temperaturas comprometen la viabilidad de algunos microorganismos. Tampoco pueden mantenerse a temperatura ambiente de forma indefinida, ya que el retraso en la incubación reduce la rentabilidad diagnóstica."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d36") }, {"long_answer": "El Plan Nacional contra el Radón recoge que, según el Real Decreto 1029/2022, una persona trabajadora debe gestionarse como trabajador expuesto cuando su exposición a radón en el puesto de trabajo pueda suponer una dosis efectiva superior a 6 mSv al año, lo que conlleva vigilancia dosimétrica y sanitaria específica. El valor de 1 mSv por año corresponde al límite de dosis para miembros del público. Las cifras de 3 y 10 mSv por año no son las que establece la norma para esta clasificación."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d38") }, {"long_answer": "La sección HS6 del Documento Básico de Salubridad del Código Técnico de la Edificación obliga a adoptar soluciones constructivas de protección frente al radón, como barreras o sistemas de extracción, en los edificios situados en los municipios que figuran en su apéndice, es decir, aquellos con una probabilidad significativa de superar el nivel de referencia. No se aplica a todos los municipios sin excepción, ya que depende del potencial de radón de la zona. Tampoco se limita a edificios públicos ni a construcciones anteriores al año 2000; afecta a obra nueva y a determinadas intervenciones."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d39") }, {"long_answer": "En España, la Entidad Nacional de Acreditación (ENAC) es el organismo que acredita, conforme a la norma UNE-EN ISO/IEC 17025, a los laboratorios que miden la concentración de radón en aire, tanto con detectores pasivos como con monitores en continuo, garantizando su competencia técnica. El Consejo de Seguridad Nuclear es el regulador en materia de protección radiológica y elabora guías y mapas, pero no es la entidad acreditadora de laboratorios. El CSIC es un organismo de investigación y el Ministerio de Sanidad coordina el Plan, pero ninguno acredita laboratorios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d3e") }, {"long_answer": "La concentración de radón en los edificios varía con las condiciones ambientales, especialmente con la temperatura y los movimientos convectivos del aire: la diferencia de temperatura entre el interior y el exterior genera un efecto chimenea que aspira gas del subsuelo, lo que explica los aumentos nocturnos y en los meses fríos. La presión atmosférica y la humedad también influyen, pero no son los únicos factores, por lo que las opciones que las presentan como determinantes exclusivos son incorrectas. La contaminación exterior no condiciona la concentración de radón."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d40") }, {"long_answer": "Los materiales de construcción como ladrillos, hormigón o algunas piedras naturales pueden contener radio-226, cuya desintegración genera radón que se emana hacia el interior de las viviendas y contribuye a su concentración, aunque generalmente en menor medida que el terreno. El contenido de radio depende del origen de las materias primas, por lo que algunos materiales tienen mayor actividad. Las arenas silíceas puras, los plásticos derivados del petróleo y el vidrio contienen cantidades muy bajas de radio y no son una fuente relevante."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d48") }, {"long_answer": "El Plan Nacional contra el Radón destaca que el nuevo laboratorio metrológico de radón del CIEMAT dispondrá de un patrón primario, único en España, que permitirá garantizar la trazabilidad de las medidas de concentración de radón realizadas por los laboratorios del país a patrones nacionales. Su función no se limita a medir radón en aguas subterráneas ni a la formación de usuarios domésticos. Tampoco se define como laboratorio de referencia internacional para materiales, sino como un instrumento para asegurar la calidad metrológica de las mediciones en España."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d4a") }, {"long_answer": "El procedimiento de medida asociado al Código Técnico de la Edificación establece que la medición de radón en viviendas para valorar la necesidad de intervenir debe tener una duración mínima de dos meses, que puede realizarse en cualquier época del año aplicando un factor de corrección o de cobertura que tenga en cuenta las variaciones estacionales y permita estimar la concentración media anual. Un mes es insuficiente. Medir un año completo es lo ideal, pero no es la duración mínima exigida, y restringir la medición al verano infraestimaría la concentración."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d4c") }, {"long_answer": "Las intercomparaciones periódicas de medida de radón, en las que distintos laboratorios analizan detectores expuestos a las mismas condiciones de referencia, permiten verificar que sus resultados son correctos, garantizando la calidad, la fiabilidad y la trazabilidad de las mediciones en las que se basan las decisiones de protección. No tienen como finalidad principal comparar países, ni son procedimientos para reducir la concentración de radón, que corresponde a las medidas de remediación. Tampoco se aplican solo a edificios públicos, sino a toda medición realizada por laboratorios."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d4d") }, {"long_answer": "El Plan Nacional contra el Radón propone campañas de comunicación conjuntas sobre prevención del tabaquismo y del radón, porque ambos factores actúan de forma sinérgica sobre el riesgo de cáncer de pulmón y la mayoría de los casos atribuibles al radón se producen en fumadores. Integrar ambos mensajes refuerza la concienciación de toda la población. Dirigir los mensajes solo a fumadores activos dejaría fuera a los no fumadores, que también están en riesgo. Evitar relacionar ambos factores o limitarse a medios especializados reduciría el alcance de la estrategia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d4f") }, {"long_answer": "El Plan de ampliación de la cartera común de servicios de salud bucodental prioriza a la población infantojuvenil, junto con las mujeres embarazadas y las personas con determinadas discapacidades, por ser los grupos con mayor beneficio esperado de las intervenciones preventivas y asistenciales y por las desigualdades en el acceso observadas entre comunidades autónomas. La población adulta general y las personas mayores de 65 años no fueron priorizadas en esta fase. Las embarazadas sí están incluidas, pero no de forma exclusiva.", "option_1": "Población infantojuvenil"});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d52") }, {"long_answer": "El diagnóstico de situación del Plan de ampliación de la cartera de salud bucodental recoge que el 71% de las comunidades autónomas realizaba tratamientos pulpares en la dentición permanente dentro de su atención infantil, lo que evidenciaba la variabilidad entre territorios que la ampliación pretende corregir. El 100% no es correcto, ya que no todas las comunidades ofrecían esta prestación. Los porcentajes del 59% y el 88% no corresponden al dato recogido en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d54") }, {"long_answer": "Según los datos de gasto sanitario público recogidos en el Plan de ampliación de la cartera de salud bucodental, en 2019 la asistencia odontológica ambulatoria supuso el 37,9% del gasto en asistencia curativa y de rehabilitación ambulatoria considerado en el análisis. Las cifras del 10%, el 45% y el 67% no corresponden al dato del documento. Conviene recordar el valor exacto, ya que este tipo de cifras suele preguntarse con distractores numéricos próximos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d55") }, {"long_answer": "El Plan de Recuperación, Transformación y Resiliencia estableció como hito que la ampliación de la cartera común de servicios de salud bucodental para la población infantojuvenil, las mujeres embarazadas y las personas con discapacidad se implementara antes del 31 de diciembre de 2022. Las fechas del 30 de junio y el 31 de diciembre de 2023 son posteriores al plazo fijado, y la opción de 2025 tampoco corresponde al calendario del Plan."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d61") }, {"long_answer": "El Plan de ampliación de la cartera común de servicios de salud bucodental estimó un impacto presupuestario total de 45.585.460 euros para extender las prestaciones a los grupos priorizados en todo el SNS, cifra calculada a partir del gasto medio por persona atendida y de la cobertura esperada. Las cantidades de 34.555.210, 3.867.000 y 20.271.370 euros no corresponden al impacto total, sino a cifras parciales o ajenas al cálculo global recogido en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d69") }, {"long_answer": "El diagnóstico de situación del Plan de ampliación de la cartera de salud bucodental muestra que, para los tratamientos especiales de la población infantil, predomina una provisión mixta en la que los servicios públicos se complementan con medios privados concertados, como en los modelos de tipo PADI con dentistas de cabecera privados. La provisión pública exclusiva no es el modelo predominante para estos tratamientos. La provisión privada sin convenio no forma parte de la cartera pública, y la atención domiciliaria exclusiva no es un modelo de provisión de salud bucodental."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d6a") }, {"long_answer": "Para medir la cobertura en la población infantojuvenil en el seguimiento de la ampliación del programa de salud bucodental se utiliza el porcentaje de niños y niñas atendidos respecto a la población diana, indicador que refleja qué proporción de la población con derecho a la prestación la recibe realmente. El número total de tratamientos indica actividad, no cobertura. El número de dentistas por comunidad es un indicador de recursos, y el gasto por niño es un indicador económico, por lo que ninguno mide la cobertura."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d6d") }, {"long_answer": "La ampliación de la cartera de salud bucodental contempla para las personas con discapacidad que limita la movilidad de los miembros superiores, y por tanto dificulta la higiene oral, la realización de tratamientos de odontología conservadora, como obturaciones, cuando estén indicados por su mayor riesgo de patología bucodental. No se limita a las exodoncias preventivas, que no son una práctica recomendada. La ortodoncia y los tratamientos de estética dental no forman parte de las prestaciones previstas para este grupo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977d6f") }, {"long_answer": "Según el Plan de ampliación de la cartera de salud bucodental, en 2019 el gasto total en prestaciones dentarias de las mutualidades de funcionarios fue de aproximadamente 19,3 millones de euros, cifra que se analiza junto al resto del gasto público en salud bucodental para dimensionar la ampliación. Las cantidades de 48,3 y 316 millones de euros no corresponden a este concepto, y la de 5 millones infravalora el gasto recogido en el documento."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c74") }, {"long_answer": "El Marco Estratégico para los Cuidados de Enfermería considera la mentoría una herramienta clave, porque favorece la integración y retención de las enfermeras, especialmente las de nueva incorporación, apoya el desarrollo de competencias clínicas y profesionales y contribuye a mejorar la calidad de los cuidados y la seguridad del paciente. Por ello no es irrelevante para el desarrollo profesional. Tampoco se limita a la formación de pregrado ni se dirige solo a las enfermeras especialistas, sino a todas las profesionales en distintas etapas de su carrera."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c76") }, {"long_answer": "El Marco Estratégico atribuye a la enfermería un papel activo en la sostenibilidad del sistema sanitario y de la sociedad, aplicando prácticas de cuidados respetuosas con el medio ambiente, como la gestión responsable de residuos y recursos, y promoviendo estilos de vida saludables y sostenibles en la población, en línea con el enfoque One Health. Reducir su intervención en cuestiones ambientales o centrarse solo en el tratamiento médico contradice este planteamiento. Sustituir la promoción de la salud por la farmacoterapia iría en contra del papel preventivo de los cuidados."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c77") }, {"long_answer": "El Marco Estratégico considera la perspectiva de género un elemento fundamental, porque las profesiones de cuidados están muy feminizadas y el cuidado, formal e informal, ha sido históricamente infravalorado; incorporar este enfoque permite identificar y mitigar desigualdades en condiciones laborales, acceso a puestos de responsabilidad y reconocimiento, y promover la igualdad efectiva. Por ello no es secundaria ni ajena a la enfermería. Tampoco se limita a los procesos de selección, sino que afecta de forma transversal a todas las líneas del Marco."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c79") }, {"long_answer": "Para mejorar el reconocimiento y la visibilidad del cuidado y de sus profesionales, el Marco Estratégico propone elaborar un plan de comunicación que utilice una terminología adecuada y promueva la presencia de las enfermeras en los medios de comunicación, las instituciones y los órganos de decisión. Reducir la comunicación tendría el efecto contrario. Excluir a los profesionales de las campañas públicas les restaría protagonismo, y utilizar solo materiales técnicos sin adaptarlos al público general limitaría la comprensión social del valor del cuidado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c7c") }, {"long_answer": "La evidencia internacional recogida en el Marco Estratégico muestra que una mayor ratio de enfermeras con titulación de grado por paciente se asocia a mejores resultados en salud, con menor mortalidad, menos eventos adversos y menos reingresos. Por eso la dotación de enfermeras se considera un indicador fundamental de calidad. Reducir el número de enfermeras para ahorrar costes empeora los resultados, aumentar camas sin incrementar el personal incrementa la carga asistencial y el riesgo, y la contratación exclusiva de médicos no sustituye las competencias enfermeras."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c7f") }, {"long_answer": "El Marco Estratégico señala que las enfermeras desarrollan múltiples funciones fuera del hospital público: trabajan en el sector sanitario privado, en servicios de prevención de riesgos laborales, en residencias y centros sociosanitarios y en las administraciones públicas, además de en docencia, gestión e investigación. Por ello es incorrecto afirmar que solo trabajan en hospitales públicos o que no tienen presencia en servicios de prevención o en el sector privado. Tampoco se limitan a la docencia y la gestión, que son solo algunos de sus ámbitos."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c84") }, {"long_answer": "El análisis internacional del Marco Estratégico muestra que, mientras en España la matriculación en el Grado de Enfermería ha aumentado, en más de la mitad de los países de la Unión Europea se ha observado una disminución, lo que agrava el riesgo de escasez de profesionales a escala europea. No se trata por tanto de una disminución generalizada en todos los países, ya que España es una excepción, ni de un incremento uniforme en toda la Unión. Tampoco hay un estancamiento sin variaciones, puesto que las tendencias difieren entre países."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c85") }, {"long_answer": "El enfoque One Health, recogido en el Marco Estratégico, parte de que la salud humana, la salud animal y la salud del medio ambiente están estrechamente interrelacionadas y forman un único ecosistema, de modo que los cuidados y las políticas de salud deben abordarlas conjuntamente. No se refiere a la atención exclusiva al autocuidado individual ni a un sistema centrado en la salud infantil. Aunque es muy útil frente a las zoonosis, tampoco se limita a las enfermedades transmisibles, sino que incluye aspectos como el cambio climático o la resistencia antimicrobiana."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c86") }, {"long_answer": "Uno de los principales retos que identifica el Marco Estratégico para las profesiones de cuidados en España es el abandono profesional, vinculado a condiciones laborales como la temporalidad, la sobrecarga o la falta de desarrollo profesional, junto con el envejecimiento de la plantilla y las jubilaciones previstas, lo que amenaza la disponibilidad de enfermeras. No existe un exceso de profesionales, sino un déficit respecto a la media europea. La demanda de cuidados crece por el envejecimiento poblacional y la cronicidad, por lo que las demás opciones contradicen la situación descrita."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c88") }, {"long_answer": "La estrategia de la OMS para eliminar el cáncer de cuello uterino como problema de salud pública fija para 2030 los objetivos 90-70-90: vacunar frente al VPH al 90% de las niñas antes de los 15 años, realizar cribado con una prueba de alta calidad al 70% de las mujeres a los 35 y a los 45 años y tratar al 90% de las mujeres con lesiones precancerosas o cáncer. Las demás opciones alteran los porcentajes o invierten las poblaciones diana de la vacunación y del cribado."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c8a") }, {"long_answer": "En pacientes con deseo gestacional no cumplido y para la valoración diagnóstica, la guía recomienda la conización con asa de diatermia obteniendo una pieza única no fraccionada, ya que permite valorar correctamente los márgenes de resección y la profundidad de la invasión, imprescindibles para estadificar y decidir el tratamiento, con menor impacto obstétrico que el bisturí frío. Obtener la pieza en varios fragmentos, con bisturí o con láser, impide una evaluación fiable de los márgenes. El legrado endocervical no sustituye a la conización para el diagnóstico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c92") }, {"long_answer": "Tras la histerectomía radical en el cáncer de cuello uterino en estadio inicial, la presencia de factores de alto riesgo, como ganglios positivos, márgenes afectos o afectación parametrial, indica tratamiento adyuvante con radioquimioterapia concomitante basada en cisplatino semanal, que mejora la supervivencia respecto a la radioterapia sola. La radioterapia sin quimioterapia se reserva para pacientes con factores de riesgo intermedio. La quimioterapia con carboplatino sin radioterapia no es el estándar, y el seguimiento sin tratamiento no es adecuado ante factores de alto riesgo."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c94") }, {"long_answer": "El esquema estándar de quimioterapia concurrente con radioterapia en el cáncer de cuello uterino localmente avanzado es cisplatino 40 mg/m² semanal durante unas cinco o seis semanas, que actúa como radiosensibilizante y ha demostrado mejorar la supervivencia frente a la radioterapia exclusiva. El carboplatino puede emplearse como alternativa cuando el cisplatino está contraindicado, pero no es el estándar ni se pauta así. El paclitaxel sin cisplatino y la doxorrubicina mensual no forman parte del tratamiento radioquimioterápico estándar."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c97") }, {"long_answer": "En el cáncer de cuello uterino localmente avanzado con ganglios pélvicos positivos y ganglios aórticos negativos en las pruebas de imagen, se recomienda realizar una linfadenectomía aórtica de estadificación hasta la arteria mesentérica inferior, porque la imagen puede no detectar metástasis microscópicas y su hallazgo obliga a ampliar el campo de radioterapia a la región paraaórtica. Omitirla puede dejar enfermedad sin tratar. La braquiterapia sola no es suficiente en tumores avanzados, y la histerectomía radical no está indicada en este escenario, que se trata con radioquimioterapia."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c99") }, {"long_answer": "La braquiterapia es un componente imprescindible del tratamiento radical del cáncer de cuello uterino tratado con radioterapia, ya que permite administrar dosis muy altas en el tumor y su entorno gracias a la rápida caída de la dosis con la distancia, respetando órganos de riesgo como el recto, la vejiga y el sigma. Su objetivo no es reducir la toxicidad del tratamiento sistémico ni evitar la cirugía radical, ya que forma parte de un tratamiento distinto. Tampoco se utiliza para tratar metástasis a distancia, que requieren tratamiento sistémico."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c9a") }, {"long_answer": "En el tratamiento con radioquimioterapia y braquiterapia guiada por imagen del cáncer de cuello uterino localmente avanzado, la guía recomienda alcanzar en el volumen tumoral residual (GTVres) una dosis total equivalente en fracciones de 2 Gy (EQD2) igual o superior a 90 Gy, ya que dosis tan altas se asocian a un mejor control local. Los 45 Gy corresponden aproximadamente a la dosis de la radioterapia externa pélvica, no al objetivo total. Las dosis de 30 Gy o inferiores a 60 Gy son claramente insuficientes para controlar el tumor."});
fix('examen_protocolos', { _id: ObjectId("6ac4063e0ee40273ca977c9c") }, {"long_answer": "En el dolor neuropático refractario del cáncer de cuello uterino avanzado, por ejemplo por infiltración del plexo lumbosacro, se recomienda asociar a los opioides fármacos coadyuvantes como gabapentina, pregabalina o antidepresivos tricíclicos, que actúan sobre los mecanismos del dolor neuropático. Aumentar la morfina sin coadyuvantes suele ser poco eficaz en este tipo de dolor y aumenta los efectos adversos. Los procedimientos invasivos se valoran como complemento, no en lugar de la analgesia farmacológica, y la quimioterapia paliativa no es el tratamiento del dolor neuropático."});
